window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0089", [{"word":"mammalian","ipa_uk":"/məˈmeɪliən/","ipa_us":"/məˈmeɪliən/","definition_zh":"哺乳动物的；哺乳动物个体；哺乳类生理特征的；哺乳动物演化与区系的；哺乳动物式的（温情照护）","definition_en":"belonging to the class of animals that suckle their young, or describing a member, a trait, a lineage, a laboratory model or a regional fauna drawn from that class","core_image":"一只母兽侧卧，幼崽贴住它的腹部吃奶，两个体温合成一块暖区","scene":"标本室里，一排骨架从鼩鼱排到鲸鱼，每副都挂着同一类群的标签。 Every skeleton in the drawer carries a label marking it as mammalian, whatever its size.","sceneCN":"这里 mammalian 是「哺乳动物的」（第 1 个义项：分类学上属于哺乳纲的）；句意：抽屉里每副骨架都贴着标明它属于哺乳动物的标签，无论体型大小。","pos":[{"tag":"adj.","zh":"哺乳动物的；哺乳纲的"},{"tag":"n.","zh":"哺乳动物（动物学专业用法，可数，复数 mammalians）"}],"collocations":[{"phrase":"mammalian species","zh":"哺乳动物物种"},{"phrase":"mammalian evolution","zh":"哺乳动物演化"},{"phrase":"mammalian physiology","zh":"哺乳动物生理学"},{"phrase":"mammalian fauna","zh":"哺乳动物区系"},{"phrase":"mammalian model","zh":"哺乳动物模型"},{"phrase":"mammalian lineage","zh":"哺乳动物支系"}],"forms":[{"label":"原级","form":"mammalian"},{"label":"比较级","form":"more mammalian"},{"label":"最高级","form":"most mammalian"},{"label":"复数（作名词）","form":"mammalians"},{"label":"同根名词","form":"mammal"},{"label":"同根名词（纲名）","form":"Mammalia"}],"derivatives":[{"word":"mammal","pos":"n.","zh":"哺乳动物"},{"word":"Mammalia","pos":"n.","zh":"哺乳纲"},{"word":"mammalogy","pos":"n.","zh":"哺乳动物学"},{"word":"mammalogist","pos":"n.","zh":"哺乳动物学家"},{"word":"mammal-like","pos":"adj.","zh":"似哺乳动物的"}],"senses":[{"no":"01","title":"Of the Class Mammalia","titleCN":"属于哺乳纲的","definition":"belonging to Mammalia, the class of vertebrates that have hair and suckle their young","definitionCN":"属于哺乳纲的，即体表有毛、以乳汁哺育幼崽的脊椎动物类群","example":"The mammalian skull differs from the reptilian one in its jaw joint.","exampleCN":"哺乳动物的头骨在颌关节处与爬行动物的头骨不同。","why":"Mammalia is the taxonomic name Linnaeus gave the class, so the adjective simply labels membership in it.","whyCN":"Mammalia 是林奈为这一纲所立的分类名，形容词因此只负责标明「属于该纲」。"},{"no":"02","title":"A Member of the Class","titleCN":"哺乳动物个体（名词）","definition":"as a noun, one animal belonging to Mammalia","definitionCN":"作名词时，指属于哺乳纲的一个动物个体","example":"Each mammalian in the sample was weighed before release.","exampleCN":"样本中的每只哺乳动物都在放归前称了重。","why":"zoologists routinely turn class adjectives into countable nouns, so the adjective can stand for the animal itself.","whyCN":"动物学家惯于把纲的形容词用作可数名词，这个形容词因此能直接指那只动物。"},{"no":"03","title":"Of the Defining Traits","titleCN":"哺乳类生理特征的","definition":"describing the warm-blooded, milk-producing, live-bearing traits that define the class","definitionCN":"描述恒温、泌乳、胎生这些界定该纲的生理特征","example":"Mammalian warmth comes from a high metabolic rate, not from the sun.","exampleCN":"哺乳动物的体温来自高代谢率，而不是太阳。","why":"those traits are exactly what makes an animal mammalian, so the adjective can name the mechanism rather than the membership.","whyCN":"正是这些特征使一只动物成为哺乳动物，形容词因此可以指机制本身，而不只是指身份。"},{"no":"04","title":"Of an Evolutionary Lineage","titleCN":"哺乳动物演化支系的","definition":"used of a branch of the mammalian family tree and the animals that sit on it","definitionCN":"用于哺乳动物演化树上的一个支系以及该支系上的动物","example":"The mammalian line split from the reptile line long before the dinosaurs died out.","exampleCN":"哺乳动物这一支在恐龙灭绝之前很久就与爬行动物一支分开了。","why":"every class is a branch on a tree, so the adjective can follow the branch through time and not merely through a checklist.","whyCN":"每个纲都是演化树上的一根枝条，形容词因此能沿时间追踪这一支，而不只是对应一份名录。"},{"no":"05","title":"Of a Laboratory Model","titleCN":"实验用哺乳动物模型的","definition":"used of a mammal bred and kept for experiments","definitionCN":"用于为实验而饲养繁殖的哺乳动物","example":"The drug was cleared in a mammalian model before any human trial.","exampleCN":"这种药在进入任何人体试验之前已在哺乳动物模型中获得通过。","why":"a model animal is valued precisely for sharing mammalian physiology with humans, so the class name becomes a quality label.","whyCN":"模型动物之所以有价值，正因为它与人类共享哺乳动物的生理，纲名于是变成一种品质标签。"},{"no":"06","title":"Of a Regional Fauna","titleCN":"地区哺乳动物区系的","definition":"used of the mammals native to a particular region, taken together as one group","definitionCN":"用于某一地区原生的哺乳动物整体","example":"The island's mammalian fauna is small because few species crossed the water.","exampleCN":"这座岛的哺乳动物区系很小，因为越过水面的物种寥寥无几。","why":"a fauna is a collective noun for one class in one place, so the adjective marks both the class and the boundary.","whyCN":"区系是某一纲在某一地点的集合名词，形容词因此同时标出类群与边界。"},{"no":"07","title":"Belonging to Mammalogy","titleCN":"与哺乳动物学相关的","definition":"relating to the study of mammals as an academic discipline","definitionCN":"与以哺乳动物为研究对象的学科有关","example":"Her mammalian research began in a museum drawer of unlabelled skins.","exampleCN":"她的哺乳动物学研究始于一抽屉没有标签的皮张。","why":"the discipline and its object share one root, so the adjective slides from the animal to the scholarship built around it.","whyCN":"学科与其研究对象同出一根，形容词因此能从动物滑向围绕它建立的学术工作。"},{"no":"08","title":"Figurative Warmth","titleCN":"比喻：哺乳动物式的温情","definition":"figurative, of care that is bodily, close and continuous, like a mother suckling her young","definitionCN":"比喻用法，指像母兽哺育幼崽那样贴身、持续、出于本能的照护","example":"The old house offered a mammalian sort of comfort, warm and slightly damp.","exampleCN":"那座老房子给人一种哺乳动物式的舒适，温暖而略带潮气。","why":"the core image is one body kept warm against another, and that physical closeness is what the metaphor borrows.","whyCN":"核心意象是一个身体贴着另一个身体取暖，比喻借用的正是这份身体上的贴近。"}],"etymology":{"intro":{"en":"Mammalian joins mammal, the English shortening of Linnaeus's Mammalia, with the adjective suffix -ian. Mammalia itself was built from Latin mamma 'breast' plus a neuter plural ending. Dates are approximate.","cn":"mammalian 由 mammal 加形容词后缀 -ian 构成，而 mammal 是林奈所立 Mammalia 的英语缩略；Mammalia 本身由拉丁 mamma「乳房」加中性复数词尾构成。年代均为约数。"},"items":[{"era":"LATIN MAMMA","en":"Mamma was the ordinary Latin word for the breast or teat, not a technical term; its deeper origin is not settled, and an onomatopoeic account has been proposed.","cn":"mamma 是拉丁语中「乳房、乳头」的平常说法，并非术语；它更早的来源不确定，另有拟声说。"},{"era":"LINNAEAN MAMMALIA","en":"Linnaeus introduced Mammalia in 1758 as the class name for animals that suckle, choosing the breast rather than hair or womb as the defining feature.","cn":"林奈于一七五八年立 Mammalia 为这一纲的名称，选择「乳房」而不是毛发或子宫作为界定特征。"},{"era":"LATIN -ALIA","en":"The ending -alia is a neuter plural of the same pattern as Reptilia; it marks a collective taxonomic group rather than a single animal.","cn":"词尾 -alia 是中性复数，与 Reptilia 等纲名同一模式；它标记集合性的分类群，而非单个动物。"},{"era":"ENGLISH MAMMAL","en":"English mammal is an eighteenth-century shortening of Mammalia, coined so that the class would have a singular noun like every other class.","cn":"英语 mammal 是十八世纪对 Mammalia 的缩略，造出它是为了让这一纲像其他纲一样有一个单数名词。"},{"era":"SUFFIX -IAN","en":"The suffix -ian comes from Latin -ianus and means 'belonging to, connected with', so mammalian means 'belonging to the mammals'.","cn":"后缀 -ian 来自拉丁 -ianus，意为「属于……、与……有关」，所以 mammalian 就是「属于哺乳动物的」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin ancestry of mamma is unknown and competing hypotheses are not settled here; the first date of mammalian as an English adjective is also approximate.","cn":"来源不确定：mamma 在拉丁语之前的来历不明，各种假说此处不选定论；mammalian 作为英语形容词的首见年代同样只是约数。"}]},"similar":{"note":{"en":"Group one holds near-identical shapes, two sharing the root mamma and two not. Group two holds words that overlap with mammalian in meaning but differ in scope.","cn":"第一组是外形相近的词，两个与 mamma 同根、两个不同根；第二组是含义重叠但范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mammary","ipa":"/ˈmæməri/","tag":"same root, organ word","definition":"Built on mamma plus -ary, it names the milk glands themselves rather than the class of animals.","definitionCN":"由 mamma 加 -ary 构成，指乳腺本身，而不是动物类群。"},{"word":"mammal","ipa":"/ˈmæməl/","tag":"same root, shortened form","definition":"The singular noun derived from Mammalia; mammalian is its adjective, so the two differ in part of speech rather than in root.","definitionCN":"由 Mammalia 派生的单数名词；mammalian 是它的形容词，二者差别在词性而不在词根。"},{"word":"mammoth","ipa":"/ˈmæməθ/","tag":"different root, Russian loan","definition":"The extinct elephant takes its name from Russian mamont, whose own origin is uncertain; its resemblance to mamma is accidental.","definitionCN":"这种已灭绝的象得名于俄语 mamont，该词自身来源不确定；它与 mamma 的相似只是巧合。"},{"word":"mamba","ipa":"/ˈmɑːmbə/","tag":"different root, Zulu loan","definition":"An African snake named from Zulu; it contains no Latin element and shares only letters with mammalian.","definitionCN":"一种非洲蛇，名字来自祖鲁语；其中没有拉丁成分，与 mammalian 只是字母相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"placental","ipa":"/pləˈsentəl/","tag":"subgroup of mammals","definition":"Relating to the placental mammals, the largest subgroup of Mammalia; it is narrower than mammalian, which covers the whole class.","definitionCN":"与有胎盘类哺乳动物有关，那是哺乳纲中最大的一支；它比 mammalian 窄，后者覆盖整纲。"},{"word":"marsupial","ipa":"/mɑːˈsuːpiəl/","tag":"another mammalian subgroup","definition":"Relating to the pouched mammals, and also a noun for one of them; it parallels mammalian but names a different branch.","definitionCN":"与有袋类哺乳动物有关，也可作名词指其中一种；它和 mammalian 结构相仿，却指另一支。"},{"word":"vertebrate","ipa":"/ˈvɜːtɪbrət/","tag":"wider class","definition":"An animal with a backbone; every mammal is a vertebrate, but most vertebrates are not mammals, so this word is broader.","definitionCN":"有脊柱的动物；每只哺乳动物都是脊椎动物，但多数脊椎动物不是哺乳动物，因此这个词范围更宽。"},{"word":"warm-blooded","ipa":"/ˈwɔːm ˈblʌdɪd/","tag":"one defining trait","definition":"Maintaining a constant body temperature; it describes a single mammalian feature rather than membership in the class.","definitionCN":"维持恒定体温；它描述哺乳动物的一项特征，而非是否属于这一纲。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real Linnaean class name, and the real zoological phrases that fix each sense.","cn":"正常联想：真实的拉丁词根、真实的林奈纲名，以及固定各个义项的真实动物学搭配。"},"normal":[{"en":"mamma 'breast' plus the neuter plural -alia made Mammalia; mammal is its English shortening, and -ian adds 'belonging to'.","cn":"mamma「乳房」加中性复数 -alia 构成 Mammalia；mammal 是它的英语缩略，-ian 再加「属于」。"},{"en":"The class name chose the breast over hair or womb, which is why milk sits at the centre of the image.","cn":"纲名选的是乳房而非毛发或子宫，乳汁因此位于意象中心。"},{"en":"The same root runs through mammary, mammalogy, mammalogist and mammal.","cn":"同一词根贯穿 mammary、mammalogy、mammalogist 与 mammal。"},{"en":"Zoological phrases fix the senses: mammalian species, mammalian fauna, mammalian model, mammalian lineage.","cn":"动物学搭配固定义项：哺乳动物物种、哺乳动物区系、哺乳动物模型、哺乳动物支系。"},{"en":"Mammalians is the rare plural noun; the ordinary word for one animal is simply mammal.","cn":"mammalians 是罕见的复数名词，指一只动物时通常直接用 mammal。"}],"abstract":[{"en":"Picture a mother's body curved around a smaller body, the two temperatures merging into one pocket of warmth.","cn":"想象母兽的身体弯成一道弧，把更小的身体裹进去，两个体温合成一袋暖意。"},{"en":"Picture a family tree whose branches are drawn as bodies rather than as lines.","cn":"想象一棵族谱，枝条不是线，而是一个个身体。"},{"en":"Picture a museum drawer of skulls, each labelled with the same class name whatever its size.","cn":"想象一只装满头骨的抽屉，不论大小都贴着同一个纲名。"}]},"examples":[{"en":"Mammalian red blood cells lose their nuclei before they mature.","cn":"哺乳动物的红细胞在成熟之前就失去了细胞核。"},{"en":"The fossil beds show a mammalian presence in the valley by the early Eocene.","cn":"化石层显示，这座山谷在始新世早期已有哺乳动物存在。"},{"en":"The team compared the mammalian immune response with that of birds.","cn":"研究团队把哺乳动物的免疫反应与鸟类的作了比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「妈么连」——幼崽贴着母亲、连着乳汁的一类，就是哺乳动物。","word":"mammalian"},"root":"拉丁 mamma「乳房」+ 中性复数 -alia = 林奈一七五八年所立 Mammalia；英语 mammal 为其缩略，mammalian = mammal + -ian（拉丁 -ianus「属于」）。mamma 更早的来源不确定，另有拟声说，此处不选定论。","sensesIntro":{"en":"The eight senses radiate from one picture: a body that feeds and warms its young. From it come the taxonomic label, the countable animal, the defining physiology, the lineage, the laboratory stand-in, the regional fauna, the discipline, and finally the metaphor of bodily warmth.","cn":"八个义项都从同一个画面发散：一个用乳汁喂养、用体温护住幼崽的身体。分类标签、可数的动物、界定性的生理、演化支系、实验室替身、地区区系、学科名，最后是身体温暖的比喻，都由此而来。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mother's body feeding and warming a smaller body.","cn":"核心意象：一个母体用乳汁和体温护住更小的身体。"},"chain":["SUCKLE","WARM BODY","CLASS LABEL","EVOLUTIONARY BRANCH","LAB MODEL","BORROWED WARMTH"],"branches":[{"senses":"01 · 02","en":"MEMBERSHIP: the class name yields both the adjective and the countable animal.","cn":"归类：纲名同时产生形容词与可数的动物。"},{"senses":"03 · 06","en":"DEFINING BODY: warm blood and milk define the class, and a whole regional fauna is described the same way.","cn":"界定性的身体：温血与乳汁界定这一类，整个地区区系也用同样方式描述。"},{"senses":"04 · 07","en":"LONG BRANCH: the class is a lineage in time and later an object of study.","cn":"长枝：这一类既是时间上的支系，后来也成为研究对象。"},{"senses":"05","en":"STAND-IN: a laboratory mammal carries the class into an experiment.","cn":"替身：一只实验室哺乳动物把这一纲带进实验。"},{"senses":"08","en":"BORROWED WARMTH: physical closeness becomes a metaphor for care.","cn":"借来的温暖：身体上的贴近成为照护的比喻。"}]},"affixes":{"intro":{"en":"Mammalian can be read in four pieces: a Latin noun for the breast, a neuter plural that turns it into a class name, the English shortening of that class name, and an adjective suffix.","cn":"mammalian 可以分四段读：表「乳房」的拉丁名词、把它变成纲名的中性复数词尾、该纲名的英语缩略，以及形容词后缀。"},"latinIntro":{"en":"Latin mamma belongs to the first declension and gives the class name Mammalia; the same stem reappears in mammal, mammary and mammalogy, while -ianus supplies the English -ian.","cn":"拉丁 mamma 属第一变格法，由此产生纲名 Mammalia；同一词干再现于 mammal、mammary 与 mammalogy，而 -ianus 提供英语的 -ian。"},"items":[{"word":"mamm-","structure":"mamma (Latin noun, first declension)","meaning":"breast, teat","meaningCN":"乳房；乳头","example":"The root names the organ that defines the class.","exampleCN":"这个词根命名了界定这一纲的器官。"},{"word":"Mammalia","structure":"mamma + -alia (neuter plural)","meaning":"the class of suckling animals","meaningCN":"哺乳纲，以哺乳为特征的动物纲","example":"Linnaeus placed humans inside Mammalia.","exampleCN":"林奈把人类也放在哺乳纲之内。"},{"word":"mammal","structure":"Mammalia shortened in English","meaning":"one member of the class","meaningCN":"哺乳动物（单数名词）","example":"Every mammal has hair at some stage of life.","exampleCN":"每只哺乳动物在生命的某个阶段都有毛。"},{"word":"-ian","structure":"-ianus (Latin adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix turns the class noun into a descriptive adjective.","exampleCN":"这个后缀把纲名变成描述性的形容词。"},{"word":"mammalian","structure":"mammal + -ian","meaning":"belonging to the mammals","meaningCN":"哺乳动物的","example":"The adjective labels any trait or member of the class.","exampleCN":"这个形容词标记该纲的任何特征或成员。"},{"word":"mammary","structure":"mamma + -ary (Latin -arius)","meaning":"relating to the milk glands","meaningCN":"乳腺的","example":"Mammary tissue enlarges before birth.","exampleCN":"乳腺组织在分娩前增大。"},{"word":"mammalogy","structure":"mamma + Greek -logia","meaning":"the study of mammals","meaningCN":"哺乳动物学","example":"Mammalogy grew out of general zoology.","exampleCN":"哺乳动物学由普通动物学中分化而来。"},{"word":"mammalogist","structure":"mammalogy + -ist","meaning":"a specialist in mammals","meaningCN":"哺乳动物学家","example":"The mammalogist sorted the skins by species.","exampleCN":"哺乳动物学家按物种把皮张分开。"},{"word":"mammal-like","structure":"mammal + -like (compound adjective)","meaning":"resembling a mammal","meaningCN":"似哺乳动物的","example":"Some extinct reptiles were mammal-like in their teeth.","exampleCN":"一些已灭绝的爬行动物牙齿似哺乳动物。"}],"latinEntries":[{"word":"mamma","structure":"mamma, mammae (f., first declension)","meaning":"breast, teat","meaningCN":"乳房；乳头"},{"word":"Mammalia","structure":"Mammalia (neuter plural, third declension)","meaning":"the class of mammals","meaningCN":"哺乳纲"},{"word":"-ianus","structure":"-ianus, -iana, -ianum (adjective suffix)","meaning":"belonging to","meaningCN":"属于……的"}]}},{"word":"mammalogy","ipa_uk":"/mæˈmælədʒi/","ipa_us":"/mæˈmælədʒi/","definition_zh":"哺乳动物学；哺乳动物学专著或论集；大学的哺乳动物学课程与系科；哺乳动物分类与比较解剖研究；野生哺乳动物的调查与管理","definition_en":"the branch of zoology that studies mammals, and by extension a book, a course, a method or a body of field work devoted to them","core_image":"一张长桌上摊开皮张、头骨与测量记录，每一件都编了号","scene":"博物馆的库房里，研究员把一叠泛黄的采集记录摊在长桌上，按类群重新编号。 She has spent thirty years in mammalogy, mostly on bats and shrews.","sceneCN":"这里 mammalogy 是「哺乳动物学」（第 1 个义项：以哺乳动物为研究对象的动物学分支）；句意：她在哺乳动物学里度过了三十年，主要研究蝙蝠和鼩鼱。","pos":[{"tag":"n.","zh":"哺乳动物学（不可数）；哺乳动物学论著（可数，复数 mammalogies）"}],"collocations":[{"phrase":"mammalogy collection","zh":"哺乳动物学标本收藏"},{"phrase":"mammalogy course","zh":"哺乳动物学课程"},{"phrase":"applied mammalogy","zh":"应用哺乳动物学"},{"phrase":"field mammalogy","zh":"野外哺乳动物学"},{"phrase":"mammalogy journal","zh":"哺乳动物学期刊"},{"phrase":"comparative mammalogy","zh":"比较哺乳动物学"}],"forms":[{"label":"原形","form":"mammalogy"},{"label":"复数（指多部论著，罕用）","form":"mammalogies"},{"label":"同根名词（人）","form":"mammalogist"},{"label":"同根形容词","form":"mammalogical"}],"derivatives":[{"word":"mammalogist","pos":"n.","zh":"哺乳动物学家"},{"word":"mammalogical","pos":"adj.","zh":"哺乳动物学的"},{"word":"mammal","pos":"n.","zh":"哺乳动物"},{"word":"Mammalia","pos":"n.","zh":"哺乳纲"},{"word":"mammalian","pos":"adj./n.","zh":"哺乳动物的；哺乳动物"}],"senses":[{"no":"01","title":"The Discipline Itself","titleCN":"哺乳动物学这门学科","definition":"the branch of zoology devoted to the description, classification and biology of mammals","definitionCN":"动物学中专门描述、分类并研究哺乳动物生物学的分支","example":"Mammalogy began as a subsection of general zoology in the nineteenth century.","exampleCN":"哺乳动物学在十九世纪只是普通动物学中的一个分支。","why":"the second element -logia names a field of study, so the word is first of all the name of a discipline.","whyCN":"第二成分 -logia 命名一门研究领域，因此这个词首先是一个学科名。"},{"no":"02","title":"A Treatise on Mammals","titleCN":"一部哺乳动物学专著","definition":"a book or long paper that presents the mammals of a region or of a group","definitionCN":"系统论述某一地区或某一类群哺乳动物的专著或长文","example":"His shelf holds a mammalogy of the valley that no later survey has replaced.","exampleCN":"他的书架上有一部关于这座山谷的哺乳动物学专著，后来的调查都无法取代它。","why":"a discipline's name transfers to a single work when that work is the discipline written down.","whyCN":"当一门学科被写成一本书，学科名就转移到这部作品上。"},{"no":"03","title":"A Course or a Department","titleCN":"课程与系科","definition":"a taught course, or an academic unit, in which mammals are studied","definitionCN":"讲授哺乳动物研究的课程，或设置该研究的院系单位","example":"She signed up for mammalogy in her second year and never left the lab.","exampleCN":"她二年级时选了哺乳动物学，从此再没离开实验室。","why":"what a department teaches is called by the name of the field, so the same word names the course and the unit.","whyCN":"一个系所教的内容以学科名为名，同一个词因此既是课程也是单位。"},{"no":"04","title":"The Taxonomic Branch","titleCN":"其中的分类学分支","definition":"the part of the field that names, describes and sorts mammal species","definitionCN":"该领域中负责命名、描述并排序哺乳动物物种的部分","example":"Modern mammalogy relies on genetic data as much as on skull measurements.","exampleCN":"现代哺乳动物学对基因数据的依赖不亚于对头骨测量。","why":"naming and sorting was the historical core of the discipline and remains the branch other work depends on.","whyCN":"命名与排序是这门学科历史上的核心，至今仍是其他工作所依赖的分支。"},{"no":"05","title":"Applied Mammalogy","titleCN":"应用哺乳动物学","definition":"the use of mammal research in managing wild populations and in conservation","definitionCN":"把哺乳动物研究用于野生种群管理与保护","example":"Applied mammalogy set the quotas that keep the deer herd stable.","exampleCN":"应用哺乳动物学制定了配额，使鹿群数量保持稳定。","why":"once the discipline can count and model a population, its findings become a management tool.","whyCN":"一旦这门学科能清点并建模一个种群，它的结论便成为管理工具。"},{"no":"06","title":"Comparative Anatomy Approach","titleCN":"比较解剖的研究取向","definition":"a research approach that compares skeletons, teeth and organs across mammal groups","definitionCN":"在哺乳动物各类群之间比较骨骼、牙齿与器官的研究取向","example":"His mammalogy is comparative, built on measurements of the same bone in forty species.","exampleCN":"他的哺乳动物学研究是比较性的，建立在四十个物种同一块骨头的测量之上。","why":"mammals differ in ways that can be measured, so the discipline often proceeds by comparison rather than by description alone.","whyCN":"哺乳动物之间的差异可以测量，学科因此常靠比较推进，而不只是描述。"},{"no":"07","title":"Field Survey and Records","titleCN":"野外调查与记录","definition":"the practical work of trapping, observing and recording mammals in the wild","definitionCN":"在野外捕捉、观察并记录哺乳动物的实际工作","example":"Good mammalogy depends on notes written in the rain, not on memory.","exampleCN":"扎实的哺乳动物学依赖雨中写下的笔记，而不是记性。","why":"a specimen is useless without its date, place and conditions, so the discipline carries its field method inside its name.","whyCN":"标本若没有日期、地点与条件便毫无用处，学科因此把野外方法也带进了名字里。"},{"no":"08","title":"The Early History","titleCN":"学科史与早期形态","definition":"the early record of how mammals were collected, named and arranged","definitionCN":"哺乳动物如何被采集、命名与编排的早期记录","example":"Early mammalogy was largely a matter of skins bought from trappers.","exampleCN":"早期的哺乳动物学主要是向捕兽人收购皮张的事。","why":"before there were field stations there were markets, and that origin is part of what the word can still name.","whyCN":"在野外站出现之前先有集市，那段起源仍是这个词所能指的内容之一。"}],"etymology":{"intro":{"en":"Mammalogy is a modern compound of Latin mamma 'breast' and Greek -logia 'study', modelled on pairs such as zoology. Its two halves come from different languages, which is normal in scientific naming. Dates are approximate.","cn":"mammalogy 是拉丁 mamma「乳房」与希腊 -logia「研究」构成的现代复合词，仿照 zoology 一类词造出。两半来自不同语言，这在科学命名中很常见。年代均为约数。"},"items":[{"era":"LATIN MAMMA","en":"Mamma is the Latin word for the breast and gave Linnaeus the stem of Mammalia; its deeper origin is not settled.","cn":"mamma 是拉丁语中「乳房」一词，并给林奈提供了 Mammalia 的词干；它更早的来源不确定。"},{"era":"GREEK LOGOS","en":"Logos meant 'word, account, reason', and the derived -logia came to mean 'the study of'.","cn":"logos 意为「言词、叙述、道理」，由它派生的 -logia 后来意为「对……的研究」。"},{"era":"GREEK -LOGIA","en":"The suffix -logia first named a body of writing about a subject and only later named a science; English -logy follows it.","cn":"-logia 先指关于某一主题的一批著述，后来才指一门科学；英语 -logy 沿用它。"},{"era":"MODERN COMPOUND","en":"Mammalogy was formed in the nineteenth century on the pattern of zoology and biology, joining a Latin stem to a Greek suffix.","cn":"mammalogy 于十九世纪仿照 zoology 与 biology 的模式构成，把拉丁词干接在希腊后缀上。"},{"era":"ENGLISH -LOGY","en":"English -logy keeps the Greek stress pattern of -logia, which is why the stress falls on the syllable before the suffix.","cn":"英语 -logy 保留 -logia 的重音模式，重音因此落在后缀前一个音节上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first citation of mammalogy in English is not firmly dated, and the pre-Latin origin of mamma remains unknown.","cn":"来源不确定：mammalogy 在英语中的最早书证没有确切年代，mamma 在拉丁语之前的来历同样不明。"}]},"similar":{"note":{"en":"Group one holds words that look like mammalogy; two share the stem mamma and two do not. Group two holds the zoological fields that overlap with it.","cn":"第一组是外形与 mammalogy 相近的词，两个共享 mamma 词干、两个不共享；第二组是与之范围重叠的动物学学科名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mammography","ipa":"/mæˈmɒɡrəfi/","tag":"same root, medical compound","definition":"Mamma plus Greek graphein 'to write, record', meaning breast imaging; the second half has nothing to do with the study of mammals.","definitionCN":"mamma 加希腊 graphein「书写、记录」，指乳腺影像检查；后半与哺乳动物研究毫无关系。"},{"word":"mammon","ipa":"/ˈmæmən/","tag":"different root, Semitic loan","definition":"Wealth personified as an idol, coming into English through Greek and Aramaic; despite the shared letters it has no link with mamma.","definitionCN":"把财富当作偶像，经希腊语与阿拉姆语进入英语；尽管字母相同，与 mamma 并无关联。"},{"word":"malacology","ipa":"/ˌmæləˈkɒlədʒi/","tag":"different root, Greek malakos","definition":"The study of molluscs, built on Greek malakos 'soft'; it shares only the -logy ending with mammalogy.","definitionCN":"研究软体动物的学科，建立在希腊 malakos「柔软」之上；与 mammalogy 只共享 -logy 词尾。"},{"word":"mammal","ipa":"/ˈmæməl/","tag":"same root, shorter word","definition":"The animal noun from which the adjective mammalian is formed; mammalogy names the study of those animals.","definitionCN":"动物名词，形容词 mammalian 由它构成；mammalogy 则指对这些动物的研究。"}]},{"heading":"NEAR MEANING","entries":[{"word":"zoology","ipa":"/zəʊˈɒlədʒi/","tag":"wider field","definition":"The study of all animals; mammalogy is one branch of it, so the two differ in scope rather than in method.","definitionCN":"研究一切动物；哺乳动物学是其中一支，因此二者差别在范围而不在方法。"},{"word":"theriology","ipa":"/ˌθɪəriˈɒlədʒi/","tag":"rare near-synonym","definition":"A rarer term for the study of mammals, built on Greek therion 'wild beast'; it overlaps with mammalogy almost completely.","definitionCN":"哺乳动物研究的罕见别称，建立在希腊 therion「野兽」之上；与 mammalogy 几乎完全重叠。"},{"word":"primatology","ipa":"/praɪˈmætələdʒi/","tag":"subfield","definition":"The study of primates only; it is a specialised branch inside mammalogy.","definitionCN":"只研究灵长类；它是哺乳动物学内部的一个专门分支。"},{"word":"ornithology","ipa":"/ˌɔːnɪˈθɒlədʒi/","tag":"sister field","definition":"The study of birds; it is the parallel discipline for the other great class of warm-blooded animals.","definitionCN":"研究鸟类；它是针对另一个温血动物大类的平行学科。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek suffix, the real Latin stem and the real institutional phrases that carry each sense.","cn":"正常联想：真实的希腊后缀、真实的拉丁词干，以及承载各个义项的真实机构用语。"},"normal":[{"en":"mamma 'breast' plus -logia 'study': the study of the suckling class.","cn":"mamma「乳房」加 -logia「研究」：研究这一哺乳的纲。"},{"en":"The same first half appears in mammal, mammalian and mammary; only the second half changes.","cn":"同一个前半见于 mammal、mammalian 与 mammary，变化的只是后半。"},{"en":"The stress sits on the syllable before the suffix, because that is where Greek -logia put it.","cn":"重音落在后缀前一个音节上，因为希腊 -logia 就把它放在那里。"},{"en":"Zoology is the whole; mammalogy is one branch of it.","cn":"动物学是整体，哺乳动物学是其中一支。"},{"en":"Museum departments and journals both use the word: a mammalogy collection, a mammalogy journal.","cn":"博物馆部门与期刊都用这个词：哺乳动物学收藏、哺乳动物学期刊。"}],"abstract":[{"en":"Picture a long table where skins, skulls and measuring rods lie in numbered rows.","cn":"想象一张长桌，皮张、头骨与量尺按编号排成行。"},{"en":"Picture a ledger in which every animal receives a date, a place and a name.","cn":"想象一本账簿，每只动物都得到日期、地点与名字。"},{"en":"Picture a shelf of monographs whose spines all end in the same suffix.","cn":"想象一架专著，书脊都以同一个后缀收尾。"}]},"examples":[{"en":"Mammalogy and ornithology grew apart only after collections became systematic.","cn":"哺乳动物学与鸟类学直到收藏系统化之后才分道扬镳。"},{"en":"He teaches mammalogy to second-year biology students.","cn":"他给生物学二年级学生讲授哺乳动物学。"},{"en":"A good mammalogy must state where each specimen was taken.","cn":"一部好的哺乳动物学专著必须说明每件标本的采集地点。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「妈么学」——研究喂奶那一类动物的学问，就是哺乳动物学。","word":"mammalogy"},"root":"拉丁 mamma「乳房」+ 希腊 -logia（由 logos「言说、研究」派生）→ mammalogy；与 mammalian 同出 mamma；mamma 更早来源不确定，-logia 的「学科」义是较晚的用法。","sensesIntro":{"en":"The eight senses follow one path: a name for a field of study, then for the books and courses that carry it, then for its taxonomic core, its applied use, its comparative method, its field notes, and finally its own past.","cn":"八个义项沿一条路展开：先是研究领域的名称，再是承载它的书与课程，然后是它的分类内核、应用、比较方法、野外笔记，最后是它自己的过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a numbered table of skins, skulls and measurements.","cn":"核心意象：一张编号的长桌，摆着皮张、头骨与测量数据。"},"chain":["STUDY","TREATISE","COURSE","TAXONOMY","WILDLIFE MANAGEMENT","FIELD NOTES"],"branches":[{"senses":"01","en":"THE DISCIPLINE: one name for the whole field of study.","cn":"这门学科：一个名字指称整个研究领域。"},{"senses":"02 · 08","en":"WRITTEN RECORD: a monograph and the early history both live in books.","cn":"书面记录：专著与早期历史都活在书里。"},{"senses":"04 · 06","en":"COMPARISON: naming species and measuring the same bone across them.","cn":"比较：命名物种并跨物种测量同一块骨头。"},{"senses":"07","en":"FIELD WORK: notes written in the rain while animals are counted.","cn":"野外工作：在雨中计数、观察并写下的记录。"},{"senses":"03 · 05","en":"FROM CAMPUS TO WILD: what a course teaches ends up as a quota on the ground.","cn":"从课堂到野外：课程所教最终变成地面上的配额。"}]},"affixes":{"intro":{"en":"Mammalogy splits into a Latin stem for the breast and a Greek suffix for a field of study; the stress falls on the syllable before that suffix.","cn":"mammalogy 可拆成表「乳房」的拉丁词干与表「学科」的希腊后缀；重音落在该后缀之前的一个音节。"},"latinIntro":{"en":"The Latin side is mamma of the first declension, shared with mammal and mammary; the Greek side is logos and its derivative -logia, shared with biology and zoology.","cn":"拉丁一侧是第一变格法的 mamma，与 mammal、mammary 共享；希腊一侧是 logos 及其派生 -logia，与 biology、zoology 共享。"},"items":[{"word":"mamm-","structure":"mamma (Latin noun, first declension)","meaning":"breast, teat","meaningCN":"乳房；乳头","example":"The stem points to the organ that gave the class its name.","exampleCN":"这个词干指向为该纲命名的那个器官。"},{"word":"-logy","structure":"-logia (Greek noun suffix, from logos)","meaning":"a field of study","meaningCN":"学科；……学","example":"The suffix turns the stem into the name of a discipline.","exampleCN":"这个后缀把词干变成一门学科的名称。"},{"word":"mammalogy","structure":"mamma + -logia","meaning":"the study of mammals","meaningCN":"哺乳动物学","example":"The compound is a modern scientific coinage.","exampleCN":"这个复合词是现代的科学造词。"},{"word":"mammalogist","structure":"mammalogy + -ist (Greek -istēs)","meaning":"a person who studies mammals","meaningCN":"哺乳动物学家","example":"The mammalogist identified the skull from its teeth.","exampleCN":"哺乳动物学家凭牙齿认出了那头骨。"},{"word":"mammalogical","structure":"mammalogy + -ical","meaning":"relating to the study of mammals","meaningCN":"哺乳动物学的","example":"The paper appears in a mammalogical journal.","exampleCN":"这篇论文发表在一份哺乳动物学期刊上。"},{"word":"mammal","structure":"Mammalia shortened in English","meaning":"a member of the class","meaningCN":"哺乳动物","example":"The noun names one animal of the class.","exampleCN":"这个名词指该纲中的一只动物。"},{"word":"mammalian","structure":"mammal + -ian","meaning":"belonging to the mammals","meaningCN":"哺乳动物的","example":"The adjective modifies traits, models and lineages.","exampleCN":"这个形容词修饰特征、模型与支系。"},{"word":"mammary","structure":"mamma + -ary (Latin -arius)","meaning":"relating to the milk glands","meaningCN":"乳腺的","example":"Mammary glands define the class as much as hair does.","exampleCN":"乳腺与毛发一样界定这一纲。"},{"word":"therio-","structure":"therion (Greek noun, 'wild beast')","meaning":"beast, mammal","meaningCN":"野兽；哺乳动物","example":"Theriology is a rarer name for the same field.","exampleCN":"theriology 是同一领域的罕见别称。"}],"latinEntries":[{"word":"mamma","structure":"mamma, mammae (f., first declension)","meaning":"breast, teat","meaningCN":"乳房；乳头"},{"word":"logos","structure":"logos, logou (m., second declension, Greek)","meaning":"word, account, reason","meaningCN":"言词；叙述；道理"},{"word":"-logia","structure":"-logia (f., first declension, Greek)","meaning":"the study or account of","meaningCN":"对……的研究或论述"}]}},{"word":"bird","ipa_uk":"/bɜːd/","ipa_us":"/bɜːrd/","definition_zh":"鸟；一只鸟或一种鸟；禽类（供食用或狩猎）；羽毛球；（口语）年轻女子；飞行器（行话）","definition_en":"a feathered animal with wings and a beak, or one of the many things English names after it, from a table bird to a shuttlecock to an aircraft","core_image":"一只麻雀停在篱笆顶上，胸羽蓬起，下一瞬就要振翅","scene":"厨房的炉火边，铁钩上的整禽慢慢转着，油脂一滴一滴落进下方的托盘。 The bird had been turning over the fire since noon, and its skin had gone the colour of amber.","sceneCN":"这里 bird 是「供食用的禽类」（第 3 个义项：宰杀后整只上炉的禽）；句意：那只禽从中午起就在火上转着，皮已经变成琥珀色。","pos":[{"tag":"n.","zh":"鸟；禽类；羽毛球；（口语）年轻女子"},{"tag":"vi.","zh":"（口语）观鸟；到野外观察并记录鸟类"}],"collocations":[{"phrase":"game bird","zh":"猎禽；供狩猎的野禽"},{"phrase":"migratory bird","zh":"候鸟"},{"phrase":"bird of prey","zh":"猛禽"},{"phrase":"bird watching","zh":"观鸟"},{"phrase":"early bird","zh":"早起的人；早到者"},{"phrase":"rare bird","zh":"稀有的鸟；罕见的人"}],"forms":[{"label":"复数","form":"birds"},{"label":"第三人称单数","form":"birds"},{"label":"过去式","form":"birded"},{"label":"过去分词","form":"birded"},{"label":"现在分词","form":"birding"}],"derivatives":[{"word":"birder","pos":"n.","zh":"观鸟者"},{"word":"birding","pos":"n.","zh":"观鸟活动"},{"word":"birdie","pos":"n.","zh":"小鸟；羽毛球"},{"word":"birdlike","pos":"adj.","zh":"似鸟的"},{"word":"birdhouse","pos":"n.","zh":"鸟舍"}],"senses":[{"no":"01","title":"The Feathered Class","titleCN":"鸟类（生物类群）","definition":"the group of warm-blooded, egg-laying animals that have feathers, wings and a beak","definitionCN":"有羽毛、翅膀与喙的温血卵生动物这一类群","example":"The feather is what separates a bird from every other living animal.","exampleCN":"羽毛是把鸟与其他一切现存动物区分开的东西。","why":"the class is defined by feathers, so the word can name the whole group before it names any member.","whyCN":"这一纲由羽毛界定，因此这个词可以先指整个类群，再指其中成员。"},{"no":"02","title":"One Individual or One Species","titleCN":"一只鸟或一种鸟","definition":"a single animal of that class, or a species counted as one unit","definitionCN":"该类群中的一只动物，或作为一个单位计数的某个物种","example":"A single bird sang from the top of the hedge for most of the morning.","exampleCN":"一只鸟在篱笆顶上唱了大半个上午。","why":"once the class has a name, any member can take it, and counting turns a species into a unit as easily as an individual.","whyCN":"类群有了名字，任一成员都能用它；计数时物种也像个体一样成为单位。"},{"no":"03","title":"A Table Bird or Game Bird","titleCN":"供食用或狩猎的禽类","definition":"a bird raised or hunted to be eaten","definitionCN":"为食用而饲养或猎取的禽类","example":"They roasted a whole bird for the family dinner.","exampleCN":"他们为家宴烤了一整只禽。","why":"the animal's body becomes food, and English keeps the animal's name for the meat on the table.","whyCN":"动物的身体变成食物，英语仍用动物之名来指桌上的肉。"},{"no":"04","title":"Dated British: A Young Woman","titleCN":"英式旧义：年轻女子","definition":"dated British slang for a young woman, once common and now avoided","definitionCN":"英式旧时俚语，指年轻女子，曾经流行，如今已少用","example":"In the old comedy, the young bird outwits her guardian and marries whom she likes.","exampleCN":"在那部老喜剧里，那位年轻姑娘骗过监护人，嫁给了自己中意的人。","why":"the slang borrows the smallness and liveliness of a bird, a common pattern in affectionate words for young people.","whyCN":"俚语借用了鸟的娇小与活泼，这是称呼年轻人时常见的亲昵造词模式。"},{"no":"05","title":"The Shuttlecock","titleCN":"羽毛球","definition":"the feathered projectile struck across the net in badminton","definitionCN":"羽毛球运动中击过球网的羽制小球","example":"The bird clipped the net and dropped on her side of the court.","exampleCN":"羽毛球擦过网，落在她这一侧的场地上。","why":"the shuttlecock is a cork weighted with feathers, so the animal's name passed to the object that flies like one.","whyCN":"羽毛球是软木托加羽毛，动物之名于是转给了那个像鸟一样飞的东西。"},{"no":"06","title":"Slang for an Aircraft","titleCN":"行话：飞行器","definition":"informal, of a plane, rocket or satellite, treated as a machine with a personality","definitionCN":"口语用法，指飞机、火箭或卫星，把它当作有脾气的机器","example":"The pilot patted the fuselage and called the old bird steady.","exampleCN":"飞行员拍了拍机身，说这架老飞机还算稳当。","why":"a machine that flies invites the same metaphor as the animal that flies, and pilots shorten it to one syllable.","whyCN":"会飞的机器自然借用会飞的动物的比喻，飞行员又把它缩成一个音节。"},{"no":"07","title":"Give Someone the Bird","titleCN":"喝倒彩；下逐客令","definition":"in the phrase give someone the bird, to jeer at a performer or to dismiss a person abruptly","definitionCN":"用于一个意为「给某人一只鸟」的固定短语，指对表演者喝倒彩，或突然把人解雇、赶走","example":"The audience gave the singer the bird after the second verse.","exampleCN":"观众在第二段唱完后对歌手喝了倒彩。","why":"the phrase began as theatre slang for hissing an actor off the stage, and the bird here is a sound rather than an animal.","whyCN":"这一短语原为剧院俚语，指用嘘声把演员赶下台，这里的 bird 是一种声音，而非动物。"},{"no":"08","title":"A Bird in the Hand","titleCN":"谚语：手中之物胜过未得之物","definition":"in the proverb a bird in the hand is worth two in the bush, what you already hold is safer than what you hope to gain","definitionCN":"用于一句关于猎鸟的古老谚语，意为手中已有之物比希望得到之物更可靠","example":"He took the modest offer, remembering that a bird in the hand is worth two in the bush.","exampleCN":"他接受了那个不大的提议，记着手中一鸟胜过林中两鸟。","why":"the proverb is a hunting image: the bird you hold cannot escape, while the ones in the bush still can.","whyCN":"这条谚语是一个狩猎画面：手里的鸟跑不掉，灌木丛里的还可能飞走。"}],"etymology":{"intro":{"en":"Bird comes from Old English bridd, a word for a young bird or nestling. Its earlier origin is unknown and no Indo-European root can be reconstructed with confidence. In Middle English it displaced fowl as the general word. Dates are approximate.","cn":"bird 来自古英语 bridd，指幼鸟、雏鸟。它更早的来源不确定，无法可靠重构出印欧词根。中古英语时期它取代 fowl 成为通称。年代均为约数。"},"items":[{"era":"OLD ENGLISH BRIDD","en":"Bridd is recorded in Old English with the sense 'young bird, nestling'; it did not yet mean the class as a whole.","cn":"bridd 在古英语中有记录，意为「幼鸟、雏鸟」，当时还不指整个类群。"},{"era":"MIDDLE ENGLISH SHIFT","en":"In Middle English bird widened from the nestling to any bird, and by the end of the period it had replaced fowl as the everyday word.","cn":"中古英语时期，bird 从雏鸟扩大为任何鸟，到该时期末已在日常语中取代 fowl。"},{"era":"FOWL NARROWED","en":"Fowl, the older general word, shrank to mean farmyard poultry and the meat from them.","cn":"fowl 这个更早的通称缩小为指农家饲养的家禽及其肉。"},{"era":"UNCERTAIN ORIGIN","en":"Source uncertain: the pre-Old-English origin of bridd is unknown, and proposed links with other Germanic words are not accepted as settled.","cn":"来源不确定：bridd 在古英语之前的来历不明，与其他日耳曼语词的关联假说均未成为定论。"},{"era":"NEW SPECIAL SENSES","en":"The table sense, the dated sense 'young woman' and the badminton sense all appear in later centuries, each by its own metaphor.","cn":"餐桌义、「年轻女子」旧义与羽毛球义都出现在更晚的世纪，各自循自己的比喻而来。"},{"era":"AVIATION SLANG","en":"The aircraft sense belongs to the twentieth century, when flying machines made the old metaphor available again.","cn":"飞行器义属于二十世纪，当飞行机器让这个旧比喻重新可用时出现。"}]},"similar":{"note":{"en":"Group one holds spellings and neighbours that look like bird, only one of which is the same word. Group two holds the words whose meanings touch bird without sharing its origin.","cn":"第一组是与 bird 形近的拼写与邻词，其中只有一个是同一个词；第二组是含义触及 bird 但不同源的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"burd","ipa":"/bɜːd/","tag":"variant spelling, same word","definition":"An archaic spelling of bird, also used for a woman; it is the same word with a different vowel letter, not a separate root.","definitionCN":"bird 的古旧拼法，也曾用来指女子；它是同一个词换了元音字母，并非另一个词根。"},{"word":"bride","ipa":"/braɪd/","tag":"different root, Old English bryd","definition":"A woman about to be married, from Old English bryd; it looks close to bird but has its own root and no connection.","definitionCN":"即将成婚的女子，来自古英语 bryd；外形接近 bird，却有独立词根，并无关联。"},{"word":"brad","ipa":"/bræd/","tag":"different root, fastener","definition":"A thin nail, from a Germanic word for a spike; it shares three letters with bird and nothing else.","definitionCN":"一种细钉，来自日耳曼语中指尖刺的词；与 bird 只共享三个字母，别无其他。"},{"word":"birdie","ipa":"/ˈbɜːdi/","tag":"same root, diminutive","definition":"Bird plus the diminutive -ie, used for a small bird, a shuttlecock, or one stroke under par in golf.","definitionCN":"bird 加指小后缀 -ie，可指小鸟、羽毛球，或高尔夫中低于标准杆一杆的成绩。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fowl","ipa":"/faʊl/","tag":"the word bird replaced","definition":"The older general word that bird displaced; it now means poultry or game birds rather than the whole class.","definitionCN":"被 bird 取代的更早通称；如今指家禽或猎禽，而非整个类群。"},{"word":"avian","ipa":"/ˈeɪviən/","tag":"adjective, Latin root","definition":"The formal adjective for anything to do with birds, from Latin avis; it has no connection with bird.","definitionCN":"指与鸟有关的正式形容词，来自拉丁 avis；与 bird 没有关联。"},{"word":"poultry","ipa":"/ˈpəʊltri/","tag":"domesticated birds","definition":"Domesticated birds kept for eggs and meat; it covers only the farmyard part of bird.","definitionCN":"为蛋与肉而饲养的家禽；只覆盖 bird 中农家饲养的那一部分。"},{"word":"nestling","ipa":"/ˈnestlɪŋ/","tag":"the original sense","definition":"A young bird not yet able to fly, which is close to what Old English bridd first meant.","definitionCN":"还不能飞的幼鸟，接近古英语 bridd 最早的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Old English word, the real historical shift from fowl, and the real phrases that fix each later sense.","cn":"正常联想：真实的古英语词、真实发生的从 fowl 到 bird 的替换，以及固定各个后起义项的真实短语。"},"normal":[{"en":"Old English bridd meant a nestling; the modern word still keeps that smallness in birdie.","cn":"古英语 bridd 指雏鸟；现代词仍把这份娇小留在 birdie 里。"},{"en":"Bird replaced fowl at the same time that fowl narrowed to the farmyard.","cn":"bird 取代 fowl 的同时，fowl 恰好缩小到农家院落。"},{"en":"The feather fixes the class: no other living animal has one.","cn":"羽毛界定了这一纲：其他现存动物都没有。"},{"en":"Badminton, aircraft and audiences all borrowed the same flying image.","cn":"羽毛球、飞行器与观众都借用了同一个飞翔的意象。"},{"en":"The proverb keeps the hunting scene: one held, two still in the bush.","cn":"谚语保留狩猎场景：一鸟在手，两鸟仍在灌木丛。"}],"abstract":[{"en":"Picture a small body on a fence post, feathers lifted, weight already shifting to leave.","cn":"想象篱笆柱上的一个小身体，羽毛竖起，重心已在准备离开。"},{"en":"Picture a shuttlecock turning in the air, feathers first and cork behind.","cn":"想象一只羽毛球在空中翻转，羽毛在前，软木在后。"},{"en":"Picture a hand closing on one bird while two others rise from a hedge.","cn":"想象一只手攥住一只鸟，另外两只从树篱里飞起。"}]},"examples":[{"en":"The island has no native bird that cannot fly.","cn":"这座岛上没有不会飞的本土鸟类。"},{"en":"Bird song changes with the season and with the hour.","cn":"鸟鸣随季节与时辰而变化。"},{"en":"He has watched the same bird return to the same branch for four springtimes.","cn":"他眼看着同一只鸟连续四个春天回到同一根枝条。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「伯德」——球场上被拍子抽来抽去的那只小东西，先是鸟，后来成了羽毛球。","word":"bird"},"root":"古英语 bridd「幼鸟、雏鸟」，中古英语扩大为「鸟」并取代 fowl；词源不确定，没有可可靠重构的印欧词根，不宜拆成若干字母词根。","sensesIntro":{"en":"The eight senses start from a small feathered animal: the class it belongs to, one of its members, its body on a table, a slang name for a young woman, a shuttlecock, an aircraft, a jeering phrase, and a proverb about holding what you have.","cn":"八个义项从一只覆羽的小动物出发：它所属的类群、其中一个成员、它上桌的身体、指年轻女子的旧俚语、羽毛球、飞行器、一句喝倒彩的话，以及一句劝人守住手中之物的谚语。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small feathered body ready to leave its perch.","cn":"核心意象：一个覆着羽毛的小身体，随时准备离枝。"},"chain":["FEATHERED CLASS","SINGLE BIRD","TABLE BIRD","YOUNG WOMAN","FLYING OBJECT","HELD BIRD"],"branches":[{"senses":"01 · 02","en":"THE CLASS AND ITS MEMBER: a name for the group becomes a name for one of them.","cn":"类群与成员：类群之名变成其中一个的名字。"},{"senses":"03 · 05","en":"BODY USED AS THING: the animal becomes food, and its feathers become a game piece.","cn":"身体转为物件：动物变成食物，羽毛变成球具。"},{"senses":"04","en":"BORROWED SMALLNESS: a lively young woman is called by the small creature's name.","cn":"借来的娇小：活泼的年轻女子被冠以小动物的名字。"},{"senses":"06","en":"MACHINE THAT FLIES: the metaphor moves from feathers to metal.","cn":"会飞的机器：比喻从羽毛移到金属。"},{"senses":"07 · 08","en":"VOICE AND PRUDENCE: one phrase hisses, the other warns against letting go.","cn":"声音与谨慎：一个短语发出嘘声，另一个告诫人别放手。"}]},"affixes":{"intro":{"en":"Bird is a free-standing Old English word with no productive prefix or root; the pieces below are real English compounds and suffixes attached to it, not Latin or Greek segments.","cn":"bird 是一个独立的古英语词，没有可拆分的前缀或词根；下面列出的都是真实附加在它上面的英语复合成分与后缀，而非拉丁或希腊语素。"},"latinIntro":{"en":"No reliable Latin or Greek cognate exists: Latin avis 'bird' and Greek ornis are different words with different roots, and treating them as a family here would be invention.","cn":"没有可靠的拉丁或希腊同族词：拉丁 avis「鸟」与希腊 ornis 都是词根不同的另一些词，把它们当作同族便是编造。"},"items":[{"word":"bird","structure":"free morpheme (Old English bridd)","meaning":"a feathered animal","meaningCN":"鸟","example":"The word stands alone and takes suffixes directly.","exampleCN":"这个词可独立使用，并直接接后缀。"},{"word":"birder","structure":"bird + -er (agent suffix)","meaning":"a person who watches birds","meaningCN":"观鸟者","example":"Birders arrive before dawn with notebooks.","exampleCN":"观鸟者带着笔记本在天亮前到达。"},{"word":"birding","structure":"bird + -ing (verbal noun suffix)","meaning":"the activity of watching birds","meaningCN":"观鸟活动","example":"Birding counts the species seen within a set area.","exampleCN":"观鸟活动统计在划定区域内见到的物种。"},{"word":"birdie","structure":"bird + -ie (diminutive suffix)","meaning":"a small bird, or a shuttlecock","meaningCN":"小鸟；羽毛球","example":"Players on the court call the shuttlecock a birdie.","exampleCN":"球场上的球员把羽毛球叫作 birdie。"},{"word":"birdlike","structure":"bird + -like (compound adjective)","meaning":"resembling a bird","meaningCN":"似鸟的","example":"The dinosaur had a birdlike hip.","exampleCN":"那只恐龙有一副似鸟的髋部。"},{"word":"birdhouse","structure":"bird + house (compound noun)","meaning":"a small shelter for birds","meaningCN":"鸟舍","example":"A birdhouse hangs from the apple tree.","exampleCN":"苹果树上挂着一只鸟舍。"},{"word":"birdbath","structure":"bird + bath (compound noun)","meaning":"a shallow basin for birds to wash in","meaningCN":"供鸟洗浴的浅水盆","example":"The birdbath freezes solid in January.","exampleCN":"那只鸟浴盆在一月冻得结结实实。"},{"word":"game bird","structure":"game + bird (compound term)","meaning":"a bird hunted for sport and food","meaningCN":"猎禽","example":"Grouse and pheasant are game birds.","exampleCN":"松鸡与雉鸡都是猎禽。"},{"word":"bird of prey","structure":"bird + of + prey (fixed phrase)","meaning":"a bird that hunts live animals","meaningCN":"猛禽","example":"The hawk is a bird of prey.","exampleCN":"鹰是猛禽。"}],"latinEntries":[]}},{"word":"avian","ipa_uk":"/ˈeɪviən/","ipa_us":"/ˈeɪviən/","definition_zh":"鸟类的；鸟纲的；禽源的（疾病）；某一地区鸟类区系的；似鸟的","definition_en":"relating to birds, whether as a class of animals, as the source of a disease, as a regional fauna, or as a model for birdlike form","core_image":"清晨湿地的芦苇丛里，鸟的骨架、羽毛与鸣声被同一位记录者收进同一本册子","scene":"养殖场的鸡舍外拉起警戒线，防疫人员穿着白色防护服逐笼取样。 The outbreak was confirmed as avian influenza after samples from three sheds tested positive.","sceneCN":"这里 avian 是「禽源的」（第 3 个义项：指病原源自鸟类、在禽类之间传播的疾病）；句意为三个鸡舍的样本检测呈阳性后，这次暴发被确认为禽流感。","pos":[{"tag":"adj.","zh":"鸟类的；鸟纲的；禽源的"},{"tag":"n.","zh":"（罕用名词）鸟；可数"}],"collocations":[{"phrase":"avian influenza","zh":"禽流感"},{"phrase":"avian flu","zh":"禽流感（口语简称）"},{"phrase":"avian species","zh":"鸟类物种"},{"phrase":"avian diversity","zh":"鸟类多样性"},{"phrase":"avian ecology","zh":"鸟类生态学"},{"phrase":"avian malaria","zh":"禽疟疾"},{"phrase":"avian anatomy","zh":"鸟类解剖（学）"}],"forms":[{"label":"原级","form":"avian"},{"label":"比较级","form":"more avian"},{"label":"最高级","form":"most avian"},{"label":"名词（罕用）","form":"avians"},{"label":"同根名词","form":"avifauna（鸟类区系）"},{"label":"同根形容词","form":"avifaunal（鸟类区系的）"}],"derivatives":[{"word":"avifauna","pos":"n.","zh":"某一地区的鸟类区系"},{"word":"avifaunal","pos":"adj.","zh":"鸟类区系的"},{"word":"aviary","pos":"n.","zh":"鸟舍；大鸟笼"},{"word":"aviculture","pos":"n.","zh":"养禽业；鸟类饲养"},{"word":"aviculturist","pos":"n.","zh":"养禽者；鸟类饲养者"}],"senses":[{"no":"01","title":"Of or Relating to Birds","titleCN":"鸟类的；与鸟有关的","definition":"of, relating to, or characteristic of birds as a class of animals","definitionCN":"属于、关于鸟类这一动物类群的，或为其特征的","example":"The aviary sign explained the avian traits shared by all the birds inside.","exampleCN":"鸟舍的标牌说明了里面所有鸟共有的鸟类特征。","why":"Latin avis simply means 'bird', and -an makes an adjective, so the widest sense is the plainest one: anything that has to do with birds.","whyCN":"拉丁 avis 就是「鸟」，-an 使其成为形容词，所以最宽的义项也是最直白的：与鸟有关的一切。"},{"no":"02","title":"Resembling a Bird in Form","titleCN":"形似鸟的；有鸟的形态的","definition":"having a shape, outline, or movement that suggests a bird without actually being one","definitionCN":"形状、轮廓或动作像鸟，但本身并不是鸟","example":"The glider's avian profile let it ride thermals with very little engine noise.","exampleCN":"滑翔机形似鸟的轮廓使它几乎不需要引擎声就能乘着热气流飞行。","why":"once the adjective means 'of birds', it can be lent to anything that borrows a bird's silhouette or motion, with no claim that the thing is alive.","whyCN":"形容词一旦表示「鸟的」，就可以借给任何借用鸟的轮廓或动作的事物，并不声称那东西是活物。"},{"no":"03","title":"Of Diseases Carried by Birds","titleCN":"禽源的（疾病）","definition":"used of infections whose pathogen circulates in birds and can pass from them to other animals","definitionCN":"用于描述病原在鸟类中循环、并可由鸟传给其他动物的感染","example":"Avian influenza reached the farm through wild waterfowl using the pond.","exampleCN":"禽流感经由使用池塘的野生水禽传入这家养殖场。","why":"public health naming puts the source animal in front of the disease, so avian marks where the pathogen normally lives, not who is sick now.","whyCN":"公共卫生命名把来源动物放在疾病名前，因此 avian 标明病原通常寄居何处，而不是眼下谁在生病。"},{"no":"04","title":"Of a Region's Bird Fauna","titleCN":"某一地区鸟类区系的","definition":"used of the whole assemblage of bird species found in a given area","definitionCN":"用于描述某一地区所见的全部鸟类物种组合","example":"Avian diversity falls sharply above the treeline on this mountain.","exampleCN":"在这座山上，鸟类多样性在树线以上急剧下降。","why":"because avis is a kind of animal, the adjective can label a fauna by its kind, the way one says mammalian fauna for the mammals of a place.","whyCN":"因为 avis 是一类动物，形容词可以按类别给一个动物区系贴标签，就像用哺乳动物区系指某地的哺乳类。"},{"no":"05","title":"Of Bird Anatomy and Air Flow","titleCN":"鸟类解剖结构的（如肺与气囊）","definition":"used of anatomical structures unique to birds, especially the fixed lung and the air sacs","definitionCN":"用于描述鸟类特有的解剖结构，尤其是固定的肺与气囊","example":"The avian lung does not expand like a mammal's; air moves through it in one direction.","exampleCN":"鸟类的肺不像哺乳动物的肺那样扩张，空气单向穿过它。","why":"comparative anatomy needs a short label for 'the bird version of an organ', and avian supplies it without naming a species.","whyCN":"比较解剖学需要一个短标签来表示「器官的鸟类版本」，avian 不必点名物种就能提供它。"},{"no":"06","title":"Of Research That Takes Birds as Its Subject","titleCN":"以鸟为研究对象的（方法与课题）","definition":"used of field methods and study designs whose subject is birds rather than of the birds themselves","definitionCN":"用于描述以鸟为研究对象而非描述鸟本身的野外方法与研究设计","example":"Avian point counts were repeated at each plot for three mornings.","exampleCN":"每个样地连续三个早晨重复进行了鸟类定点计数。","why":"the adjective shifts from the animal to the practice: a count, a survey, or a model can be called avian because birds are what it measures.","whyCN":"形容词从动物转向做法：计数、调查或模型可以被称为 avian，因为它测量的对象是鸟。"},{"no":"07","title":"Of Flight Modelled on Birds","titleCN":"仿鸟飞行设计的","definition":"used of wings, aircraft, or robots whose motion is copied from bird flight","definitionCN":"用于描述动作模仿鸟类飞行的翼、飞行器或机器人","example":"The team tested an avian-inspired wing that folds on the downstroke.","exampleCN":"团队测试了一种在下扑时折拢的仿鸟机翼。","why":"engineering borrows the bird as a working model, so avian labels the source of a design rather than a biological fact.","whyCN":"工程学把鸟当作可用的模型来借用，因此 avian 标注的是设计来源，而非生物学事实。"},{"no":"08","title":"A Bird, in Technical Prose","titleCN":"（罕用名词）一只鸟","definition":"rare countable noun: a bird, used mostly in survey writing and museum catalogues","definitionCN":"罕用的可数名词：一只鸟，多见于调查记录与博物馆目录","example":"A single avian was recorded on the transect, a female warbler.","exampleCN":"样线上只记录到一只鸟，是雌性柳莺。","why":"the adjective was long ago turned into a noun by writers who wanted a neutral count word, and the usage survives in clipped field notes.","whyCN":"想用中性计数词的写作者早已把这个形容词名词化，这一用法在简省的野外记录里留存下来。"}],"etymology":{"intro":{"en":"Avian is Latin avis 'bird' plus the adjective suffix -an (Latin -anus). English took the word from scientific Latin in the nineteenth century; the deeper origin of avis is not settled.","cn":"avian 是拉丁 avis「鸟」加形容词后缀 -an（拉丁 -anus）。英语在 19 世纪从科学拉丁语引入这个词；avis 更早的来源尚无定论。"},"items":[{"era":"LATIN AVIS","en":"Avis, genitive avis, is a feminine noun of the third declension meaning 'bird'; it names any bird rather than a species, and its pre-Latin origin is uncertain.","cn":"avis 是阴性第三变格名词，属格同为 avis，意为「鸟」；它泛指任何鸟而非某一物种，其在拉丁语之前的来源不确定。"},{"era":"LATIN -ANUS","en":"The suffix -anus meant 'belonging to, pertaining to', and it regularly became -an in English adjectives such as mammalian and avian.","cn":"后缀 -anus 意为「属于……的、与……有关的」，在英语形容词中通常写作 -an，如 mammalian 与 avian。"},{"era":"ENGLISH AVIAN","en":"Avian is recorded in English from the nineteenth century, first in zoological description; the exact first citation is not firmly established.","cn":"avian 在英语中自 19 世纪有记录，最早见于动物学描述；确切的首次书证尚未定论。"},{"era":"VETERINARY USE","en":"The phrase avian influenza became standard in veterinary virology once fowl plague was shown to be caused by a virus, and the adjective then named the reservoir rather than the patient.","cn":"当鸡瘟被证明由病毒引起后，avian influenza 这一说法在兽医病毒学中成为标准，形容词由此指病原宿主而非患病者。"},{"era":"SAME ROOT ELSEWHERE","en":"Avis also underlies aviary and aviculture, and, through French, aviation; the link to aviation is generally accepted, though the French intermediate steps are thinly documented.","cn":"avis 也衍生出 aviary 与 aviculture，并经法语进入 aviation；与 aviation 的联系一般认为是正确的，但法语中介环节的书证较单薄。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: no agreed pre-Latin reconstruction for avis exists, and the first English date is only approximate; both the root's earlier history and the word's arrival date remain open.","cn":"来源不确定：avis 没有公认的前拉丁语重构形式，英语首见年代也只是约数；词根更早的历史与词进入英语的时间都仍无定论。"}]},"similar":{"note":{"en":"Group one separates the look-alike words: two share the Latin root avis, two merely resemble it in spelling. Group two holds the words that overlap with avian in meaning but differ in scope.","cn":"第一组区分形近词：两个与 avian 共享拉丁词根 avis，两个只是拼写相像。第二组是含义重叠但范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aviary","ipa":"/ˈeɪviəri/","tag":"same root, place noun","definition":"From Latin aviarium 'bird house', built on avis; it shares the root with avian but names a building rather than a quality.","definitionCN":"来自拉丁 aviarium「鸟舍」，由 avis 构成；与 avian 同根，但指的是建筑而非性质。"},{"word":"aviator","ipa":"/ˈeɪvieɪtə/","tag":"same root, different branch","definition":"From French aviation, from Latin avis 'bird'; the root is shared, but the word means a person who flies aircraft.","definitionCN":"来自法语 aviation，再上溯拉丁 avis「鸟」；词根相同，但词义指驾驶飞行器的人。"},{"word":"avarice","ipa":"/ˈævərɪs/","tag":"different root","definition":"From Latin avarus 'greedy', from avere 'to crave'; the opening letters match, but there is no link to avis.","definitionCN":"来自拉丁 avarus「贪财的」，再上溯 avere「渴求」；开头字母相同，但与 avis 无关。"},{"word":"avuncular","ipa":"/əˈvʌŋkjələ/","tag":"different root","definition":"From Latin avunculus 'maternal uncle'; the resemblance to avian is accidental and the roots are unrelated.","definitionCN":"来自拉丁 avunculus「舅父」；与 avian 的相像是偶然的，词根无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"birdlike","ipa":"/ˈbɜːdlaɪk/","tag":"everyday register","definition":"Resembling a bird; it covers the same ground as the figurative avian but carries no technical tone.","definitionCN":"像鸟的；与比喻义的 avian 覆盖相近范围，但不带技术语体。"},{"word":"ornithological","ipa":"/ˌɔːnɪθəˈlɒdʒɪkəl/","tag":"of the discipline","definition":"Relating to the scientific study of birds; it describes the research, while avian describes the animal.","definitionCN":"与鸟类科学研究有关的；描述的是研究，而 avian 描述的是动物。"},{"word":"volant","ipa":"/ˈvəʊlənt/","tag":"of flight only","definition":"Flying or able to fly; it is a functional term about locomotion, not about membership in the bird class.","definitionCN":"飞行的或能飞的；是描述运动方式的功能术语，不涉及是否属于鸟纲。"},{"word":"passerine","ipa":"/ˈpæsəraɪn/","tag":"narrow taxon","definition":"Of the order Passeriformes, the perching birds; far narrower than avian, which covers every bird.","definitionCN":"属于雀形目的；范围远比 avian 窄，后者覆盖所有鸟。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real zoological phrases and real relatives of the word.","cn":"正常联想：真实的构词成分、真实的动物学搭配与真实的同族词。"},"normal":[{"en":"avi- 'bird' + -an: the suffix turns the Latin noun into 'of birds'.","cn":"avi-「鸟」+ -an：后缀把拉丁名词变成「鸟的」。"},{"en":"Latin avis is the anchor: avi- appears again in avifauna, aviary and aviculture.","cn":"锚点是拉丁 avis：avi- 又出现在 avifauna、aviary 与 aviculture 中。"},{"en":"Avian influenza fixes the public-health sense: the pathogen's reservoir is birds.","cn":"禽流感这一固定搭配确立了公共卫生义：病原的宿主是鸟。"},{"en":"Mammalian is the same pattern for mammals, which shows how -ian attaches a class name.","cn":"表示哺乳类的形容词用的是同一模式，可见 -ian 如何接在类群名后。"},{"en":"The family runs avian, avifauna, aviary, aviculture, aviculturist.","cn":"同族词包括 avian、avifauna、aviary、aviculture、aviculturist。"}],"abstract":[{"en":"Picture a museum drawer of study skins, every tag written with one local place name.","cn":"想象博物馆抽屉里一排鸟皮标本，每张标签都写着一个本地地名。"},{"en":"Picture a poultry shed with a taped line at the gate and white suits beyond it.","cn":"想象鸡舍门口拉起一道胶带，胶带那侧站着穿白衣的人。"},{"en":"Picture a paper wing folding at the top of a stroke above an empty field.","cn":"想象一只纸翼在空野上空扑到最高点时折拢。"}]},"examples":[{"en":"Avian bones are hollow and braced by fine internal struts.","cn":"鸟类的骨骼中空，并有细小的内部支柱加固。"},{"en":"The reserve publishes an avian species list every spring.","cn":"保护区每年春天发布一份鸟类物种名录。"},{"en":"Avian flu led to a temporary ban on live-bird markets.","cn":"禽流感导致活禽市场被暂时关闭。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「诶维恩」——把开头的「诶维」记成「鸟」，后面的「恩」记成「的」→ 鸟的、鸟类的","word":"avian"},"root":"拉丁 avis「鸟」（阴性第三变格，属格 avis）+ -an（拉丁 -anus「属于……的」）。avis 更深来源不确定，无公认的前拉丁语重构形式；英语 avian 自 19 世纪科学文献起有记录，确切首见年代存疑。","sensesIntro":{"en":"The eight senses start from one plain move: attach the adjective 'of birds' to a noun. That noun may be a disease, a regional list, an organ, a research method, a machine or, rarely, the bird itself.","cn":"八个义项都从同一个简单动作出发：把「鸟的」这个形容词接到一个名词上。那个名词可以是疾病、地区名录、器官、研究方法、机器，偶尔也可以是一只鸟本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: one notebook that holds a bird's bones, feathers and song at once.","cn":"核心意象：一本同时收着鸟的骨骼、羽毛与鸣声的册子。"},"chain":["THE BIRD ITSELF","BORROWED SILHOUETTE","PATHOGEN RESERVOIR","REGIONAL BIRD LIST","ONE-WAY AIR FLOW","FLIGHT AS A MODEL"],"branches":[{"senses":"01 · 06","en":"THE CLASS: the adjective of the animal itself, and of the studies that count it.","cn":"类群本身：既是这种动物的形容词，也修饰以它为对象的调查。"},{"senses":"02 · 07","en":"BORROWED FORM: a silhouette and a wing stroke copied from birds.","cn":"借来的形态：从鸟那里借走的轮廓与一次扑翼。"},{"senses":"03","en":"RESERVOIR: the bird is where the pathogen lives, not who falls ill.","cn":"宿主：鸟是病原寄居之处，而不是发病者。"},{"senses":"04 · 05","en":"LIST AND ORGAN: a regional inventory, and the parts that make flight possible.","cn":"名录与器官：一份地区清单，以及使飞行成为可能的部件。"},{"senses":"08","en":"ONE BIRD: the adjective worn down into a count noun in field notes.","cn":"一只鸟：形容词在野外记录里被磨成了一个计数名词。"}]},"affixes":{"intro":{"en":"Avian is a two-piece word: a Latin noun for bird and a Latin adjective suffix. Every longer relative repeats that same stem.","cn":"avian 是两段式单词：一个表「鸟」的拉丁名词，加一个拉丁形容词后缀。所有更长的同族词都重复这同一词干。"},"latinIntro":{"en":"Latin avis 'bird' yields aviarius 'of birds' and aviarium 'bird house'; English builds aviary, aviculture and avifauna on the same stem.","cn":"拉丁 avis「鸟」衍生 aviarius「鸟的」与 aviarium「鸟舍」；英语用同一词干构成 aviary、aviculture 与 avifauna。"},"items":[{"word":"avi-","structure":"avis (Latin noun, third declension, genitive avis)","meaning":"bird","meaningCN":"鸟","example":"The stem avi- carries the meaning 'bird' in every relative.","exampleCN":"词干 avi- 在所有同族词里都带「鸟」的意思。"},{"word":"-an","structure":"-anus (Latin adjective suffix)","meaning":"belonging to, pertaining to","meaningCN":"属于……的；与……有关的","example":"Avian means pertaining to a bird.","exampleCN":"avian 意为与鸟有关的。"},{"word":"avian","structure":"avis + -anus","meaning":"of or relating to birds","meaningCN":"鸟类的","example":"The avian skeleton is built for lightness.","exampleCN":"鸟类的骨骼为轻盈而构造。"},{"word":"avifauna","structure":"avi- + fauna (Latin Fauna, a goddess name used for animal life)","meaning":"the bird fauna of a region","meaningCN":"某一地区的鸟类区系","example":"The island's avifauna includes three endemic warblers.","exampleCN":"该岛的鸟类区系包括三种特有柳莺。"},{"word":"avifaunal","structure":"avifauna + -al","meaning":"relating to a regional bird fauna","meaningCN":"鸟类区系的","example":"An avifaunal survey was run before the dam was built.","exampleCN":"大坝修建前进行了一次鸟类区系调查。"},{"word":"aviary","structure":"avi- + -arium (Latin place suffix)","meaning":"a place where birds are kept","meaningCN":"鸟舍；大鸟笼","example":"The aviary holds rescued hawks and owls.","exampleCN":"鸟舍里收容着获救的鹰与猫头鹰。"},{"word":"aviculture","structure":"avi- + culture (Latin cultura, 'cultivation')","meaning":"the keeping and breeding of birds","meaningCN":"养禽；鸟类饲养","example":"Aviculture of songbirds has a long history in this region.","exampleCN":"这一地区饲养鸣禽的历史悠久。"},{"word":"aviculturist","structure":"aviculture + -ist","meaning":"a person who keeps and breeds birds","meaningCN":"养禽者；鸟类饲养者","example":"The aviculturist raised the chicks by hand.","exampleCN":"养禽者亲手养大了这些雏鸟。"},{"word":"avian influenza","structure":"avian + influenza (compound term)","meaning":"influenza whose pathogen circulates in birds","meaningCN":"禽流感","example":"Avian influenza is monitored in both poultry and wild birds.","exampleCN":"禽流感在家禽与野生鸟中都被监测。"}],"latinEntries":[{"word":"avis","structure":"avis, avis (f., third declension)","meaning":"bird","meaningCN":"鸟"},{"word":"aviarius","structure":"aviarius, -a, -um (adjective, first and second declension)","meaning":"of birds, for birds","meaningCN":"鸟的；供鸟用的"},{"word":"aviarium","structure":"aviarium, -i (n., second declension)","meaning":"a place where birds are kept","meaningCN":"鸟舍"}]}},{"word":"ornithology","ipa_uk":"/ˌɔːnɪˈθɒlədʒi/","ipa_us":"/ˌɔːrnɪˈθɑːlədʒi/","definition_zh":"鸟类学；鸟类学论著；大学里的鸟类学课程；对鸟类的系统描述与分类研究","definition_en":"the scientific study of birds, and by extension the body of work, the course, or the specialised branch through which that study is pursued","core_image":"一张长桌上并排放着鸟皮标本、卡尺与一本翻旧了的鸟类名录","scene":"选课手册翻到生物系那几页，一门课注明每次上课都要在日出前到湿地集合。 She chose ornithology because the class met at a marsh before dawn.","sceneCN":"这里 ornithology 是「鸟类学课程」（第 3 个义项：大学课程与院系里开设的鸟类学）；句意为她选了鸟类学，因为这门课的上课地点是黎明前的湿地。","pos":[{"tag":"n.","zh":"鸟类学；不可数（指学科），可数（指论著或课程）"}],"collocations":[{"phrase":"field ornithology","zh":"野外鸟类学"},{"phrase":"systematic ornithology","zh":"系统鸟类学"},{"phrase":"economic ornithology","zh":"经济鸟类学"},{"phrase":"conservation ornithology","zh":"保护鸟类学"},{"phrase":"museum ornithology","zh":"博物馆鸟类学"},{"phrase":"applied ornithology","zh":"应用鸟类学"}],"forms":[{"label":"原形","form":"ornithology"},{"label":"复数（多部论著或多门分支）","form":"ornithologies"},{"label":"形容词","form":"ornithological（鸟类学的）"},{"label":"副词","form":"ornithologically（就鸟类学而言）"},{"label":"同根名词","form":"ornithologist（鸟类学家）"},{"label":"复合词","form":"palaeornithology（古鸟类学）"}],"derivatives":[{"word":"ornithological","pos":"adj.","zh":"鸟类学的；与鸟类研究有关的"},{"word":"ornithologically","pos":"adv.","zh":"从鸟类学角度；就鸟类学而言"},{"word":"ornithologist","pos":"n.","zh":"鸟类学家"},{"word":"palaeornithology","pos":"n.","zh":"古鸟类学（研究化石鸟类）"},{"word":"ornithosis","pos":"n.","zh":"鸟疫（鸟类中的一种衣原体感染）"}],"senses":[{"no":"01","title":"The Scientific Study of Birds","titleCN":"鸟类学（学科本身）","definition":"the branch of biology that studies birds: their anatomy, classification, behaviour, ecology and evolution","definitionCN":"研究鸟类的生物学分支，涵盖其解剖、分类、行为、生态与演化","example":"Ornithology began as a branch of natural history before it became a biology of its own.","exampleCN":"鸟类学起初是博物学的一支，后来才成为独立的生物学。","why":"ornis is Greek for 'bird' and -logia means 'the study of', so the word names a discipline before it names anything else.","whyCN":"ornis 在希腊语中意为「鸟」，-logia 意为「对……的研究」，因此这个词首先命名的是一门学科。"},{"no":"02","title":"A Published Work on Birds","titleCN":"一部鸟类学论著","definition":"a book or monograph that treats a region's or a group's birds in a systematic way","definitionCN":"系统论述某一地区或某一类群鸟类的书籍或专著","example":"His ornithology of the Punjab is still cited for its careful measurements.","exampleCN":"他那部旁遮普鸟类学著作仍因其细致的测量而被引用。","why":"a discipline's name can stand for a book that embodies it, so a single volume can be called an ornithology, used countably.","whyCN":"学科名可以代表体现该学科的一本书，因此单独一册也可称为一部鸟类学，此时可数。"},{"no":"03","title":"The Subject as Taught","titleCN":"大学课程与院系里的鸟类学","definition":"the subject as it appears in a curriculum, a lecture course or a department's teaching programme","definitionCN":"出现在课程表、讲座课程或院系教学计划中的这门学科","example":"Ornithology is offered in the biology department every other autumn.","exampleCN":"生物系每隔一个秋季开设鸟类学课程。","why":"once a discipline is taught, its name also labels the slot in the timetable, which is the sense students meet first.","whyCN":"一门学科一旦被教授，其名称也标注课程表上的那一格，这是学生最先遇到的义项。"},{"no":"04","title":"Describing and Naming Species","titleCN":"描述与命名的分类学分支","definition":"the taxonomic side of the field: describing new forms, fixing type specimens and revising classifications","definitionCN":"该领域的分类学侧面：描述新形态、确定模式标本、修订分类","example":"Descriptive ornithology still names several new species each year.","exampleCN":"描述性鸟类学每年仍会命名若干新物种。","why":"this is the oldest layer of the discipline, where a bird must first be described before anything else can be said about it.","whyCN":"这是该学科最古老的一层：必须先描述一只鸟，之后才能谈别的事情。"},{"no":"05","title":"Where Amateurs and Professionals Meet","titleCN":"业余观鸟与专业研究的交界","definition":"the shared field in which skilled volunteers and salaried researchers contribute records to the same datasets","definitionCN":"熟练的志愿观察者与受薪研究者把记录汇入同一批数据的共同领域","example":"The journal bridges amateur birding and academic ornithology.","exampleCN":"这份期刊把业余观鸟与学院鸟类学连接起来。","why":"much of what the discipline knows arrives as counts from non-professionals, so the name covers the whole collaborative practice, not only its paid core.","whyCN":"这门学科知道的许多事情来自非专业人士的计数，因此该名称覆盖整个协作实践，而不只是有薪的核心。"},{"no":"06","title":"Birds as Models for Behaviour and Ecology","titleCN":"以鸟为模型的行为生态研究","definition":"the strand that uses birds to test general questions about mating, foraging, migration and life history","definitionCN":"用鸟类来检验关于求偶、觅食、迁徙与生活史等普遍问题的研究方向","example":"Modern ornithology asks why clutch sizes vary with latitude.","exampleCN":"现代鸟类学追问窝卵数为何随纬度变化。","why":"birds are visible, countable and widely banded, so the discipline became a testing ground for ideas that apply far beyond birds.","whyCN":"鸟类可见、可计数且被广泛环志，这门学科因此成为检验那些远超鸟类本身的观念的试验场。"},{"no":"07","title":"The Museum and Literature Tradition","titleCN":"博物馆标本与文献传统","definition":"the tradition that works from study skins, egg sets, sound archives and old printed descriptions","definitionCN":"依托鸟皮标本、卵标本、声音档案与旧印刷描述开展工作的传统","example":"Museum ornithology depends on skins collected a century ago.","exampleCN":"博物馆鸟类学依赖一个世纪前采集的鸟皮标本。","why":"the discipline's evidence is stored rather than only seen alive, so its name also covers the cabinets and libraries that hold the record.","whyCN":"该学科的证据被储存起来，而不只是活体观察，因此名称也覆盖保存记录的那些标本柜与图书馆。"},{"no":"08","title":"Bird Study in the Service of Protection","titleCN":"应用于物种保护的研究","definition":"the applied form of the field, where surveys and population data are produced to guide conservation decisions","definitionCN":"该领域的应用形态，产出调查与种群数据以指导保护决策","example":"Conservation ornithology supplied the evidence behind the wind-farm ruling.","exampleCN":"保护鸟类学为风电场选址裁决提供了证据。","why":"when a discipline's counts start to decide where turbines may stand, its name naturally extends to that applied work.","whyCN":"当一门学科的计数开始决定风机可以立在何处，其名称自然延伸到这项应用工作。"}],"etymology":{"intro":{"en":"Ornithology is Greek ornis 'bird' (genitive ornithos) plus -logia 'the study or account of', from logos 'word, reason'. English took it through scientific Latin ornithologia; the deeper origin of ornis is not settled.","cn":"ornithology 是希腊 ornis「鸟」（属格 ornithos）加 -logia「对……的论述、研究」，后者源自 logos「言说、道理」。英语经科学拉丁 ornithologia 引入；ornis 更早的来源尚无定论。"},"items":[{"era":"GREEK ORNIS","en":"Ornis is a Greek noun of the third declension meaning 'bird', with the genitive ornithos; it covered birds generally and survives in the combining form ornitho-.","cn":"ornis 是希腊语第三变格名词，意为「鸟」，属格为 ornithos；它泛指鸟类，并以构词形式 ornitho- 留存至今。"},{"era":"GREEK LOGOS","en":"Logos meant 'word, account, reason'; the suffix -logia named a reasoned account of a subject, not merely a collection of facts.","cn":"logos 意为「言说、叙述、道理」；后缀 -logia 指对某一主题的成体系论述，而不只是事实的堆叠。"},{"era":"SCIENTIFIC LATIN","en":"Ornithologia was formed in early modern scientific Latin from the two Greek pieces; the coining is generally attributed to Aldrovandi's Ornithologiae (1599), though earlier uses may exist.","cn":"ornithologia 在近代早期科学拉丁语中由两个希腊成分构成；一般认为出自阿尔德罗万迪 1599 年的《鸟类学》，但可能另有更早的用例，此处不选定论。"},{"era":"ENGLISH ORNITHOLOGY","en":"English ornithology is recorded from the seventeenth century, at first for a descriptive catalogue of a region's birds rather than for a research programme.","cn":"英语 ornithology 自 17 世纪有记录，最初指某一地区鸟类的描述性名录，而非一项研究纲领。"},{"era":"SPECIALISATION","en":"In the eighteenth and nineteenth centuries the word narrowed into a recognised branch of zoology, with Linnaean naming, study skins and dedicated journals.","cn":"在 18、19 世纪，这个词收窄为动物学中一个被承认的分支，配有林奈式命名、鸟皮标本与专门期刊。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first English citation is not established, and the pre-Greek origin of ornis has no agreed reconstruction; only the general Greek derivation is secure.","cn":"来源不确定：确切的英语首见书证尚未确定，ornis 在希腊语之前的来源也没有公认的重构；可靠的只有其希腊语来源这一层。"}]},"similar":{"note":{"en":"Group one separates look-alikes: two carry the same Greek ornis stem in different compounds, two only resemble the spelling. Group two places the field beside its neighbours on a scale from narrow to broad.","cn":"第一组区分形近词：两个在不同复合词中带同一希腊词干 ornis，两个只是拼写相像。第二组把该学科放在由窄到宽的邻近学科之间。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ornithopod","ipa":"/ˈɔːnɪθəpɒd/","tag":"same Greek root, different second element","definition":"A dinosaur group named from Greek ornis 'bird' plus pous 'foot'; it shares the stem but refers to dinosaurs, not to the study of birds.","definitionCN":"鸟脚类恐龙，名称取自希腊 ornis「鸟」加 pous「脚」；词干相同，但指的是恐龙，而非鸟类研究。"},{"word":"ornithopter","ipa":"/ˈɔːnɪθəptə/","tag":"same Greek root, wing compound","definition":"From ornis plus pteron 'wing': a machine that flies by flapping wings; the stem is shared, the referent is an aircraft.","definitionCN":"由 ornis 加 pteron「翼」构成：靠扑翼飞行的机器；词干相同，所指却是飞行器。"},{"word":"ornery","ipa":"/ˈɔːnəri/","tag":"different root","definition":"An American dialect adjective from ordinary, meaning stubborn or bad-tempered; it has no Greek root and no link to ornis.","definitionCN":"美式方言形容词，源自 ordinary，意为脾气坏、固执；没有希腊词根，与 ornis 无关。"},{"word":"ornamental","ipa":"/ɔːˈneɪməntəl/","tag":"different root","definition":"From Latin ornamentum 'equipment, adornment', from ornare 'to fit out'; the shared opening is accidental.","definitionCN":"来自拉丁 ornamentum「装备、装饰」，再上溯 ornare「配备」；开头的相像出于偶然。"}]},{"heading":"NEAR MEANING","entries":[{"word":"birdwatching","ipa":"/ˈbɜːdwɒtʃɪŋ/","tag":"recreational","definition":"The leisure activity of watching and listing birds; ornithology is its scientific counterpart, though the two share field skills.","definitionCN":"观看并记录鸟类的休闲活动；ornithology 是其科学对应物，两者共享野外技能。"},{"word":"ethology","ipa":"/ɪˈθɒlədʒi/","tag":"broader, animal behaviour","definition":"The study of animal behaviour in general; bird behaviour is one of its strongest traditions but not its whole scope.","definitionCN":"对动物行为的总体研究；鸟类行为是其中最强的传统之一，但不是它的全部范围。"},{"word":"zoology","ipa":"/ˈzuːələdʒi/","tag":"the parent field","definition":"The study of animals as a whole; ornithology is a branch of it, restricted to one class.","definitionCN":"对整个动物的研究；ornithology 是它的一个分支，只限于一个纲。"},{"word":"oology","ipa":"/əʊˈɒlədʒi/","tag":"narrower, eggs only","definition":"The study of birds' eggs and nests; a small specialty inside ornithology rather than a rival to it.","definitionCN":"研究鸟卵与鸟巢的学问；是 ornithology 内部的一个小专门方向，而非与之并列。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real institutional usage and real relatives, not invented rhymes.","cn":"正常联想：真实的希腊构词成分、真实的机构用法与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ornith- 'bird' + -logy 'study of': the discipline's name is literally 'bird account'.","cn":"ornith-「鸟」+ -logy「对……的研究」：学科名直译就是「关于鸟的论述」。"},{"en":"The genitive ornithos explains why the stem is ornitho- and not orni- in longer words.","cn":"属格 ornithos 说明了为什么在更长的词里词干是 ornitho- 而不是 orni-。"},{"en":"Real phrases fix the branches: field, museum and conservation ornithology.","cn":"真实搭配固定了各分支：野外、博物馆与保护鸟类学。"},{"en":"The adjective is ornithological and the person is an ornithologist, with -ical and -ist added to the same base.","cn":"形容词是 ornithological，人称是 ornithologist，都是在同一词基上加 -ical 与 -ist。"},{"en":"Aldrovandi's Ornithologiae of 1599 is the usual anchor for the Latin term, though the attribution is not a proof.","cn":"阿尔德罗万迪 1599 年的《鸟类学》通常被当作拉丁术语的锚点，但这一归属并非证明。"}],"abstract":[{"en":"Picture a cabinet drawer pulled open, each skin tagged with a place and a date.","cn":"想象拉开一只标本柜抽屉，每张鸟皮都挂着地点与日期的标签。"},{"en":"Picture a seminar room where half the students carry binoculars instead of notebooks.","cn":"想象一间研讨室，一半学生拿的不是笔记本而是望远镜。"},{"en":"Picture a coastline map with turbine sites crossed out after a survey.","cn":"想象一张海岸地图，调查之后几处风机点位被划掉。"}]},"examples":[{"en":"He read an old ornithology from cover to cover before his first field trip.","cn":"第一次野外实习之前，他把一部旧鸟类学著作从头读到尾。"},{"en":"Bird study grew from cabinet collecting into modern ornithology.","cn":"鸟类研究从标本柜收藏发展为现代鸟类学。"},{"en":"The conference drew both academic ornithologists and weekend birders.","cn":"这次会议既吸引了学院里的鸟类学家，也吸引了周末观鸟者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「奥尼索罗吉」——「奥尼」听成清晨的一声鸟鸣，末尾的「罗吉」就是「学」→ 鸟类学","word":"ornithology"},"root":"希腊 ornis「鸟」（属格 ornithos，第三变格）+ -logia「对……的论述、研究」（源自 logos「言说、道理」）；经科学拉丁 ornithologia 进入英语，一般认为该拉丁词形出自阿尔德罗万迪 1599 年的著作。ornis 更深来源不确定。","sensesIntro":{"en":"The eight senses all descend from one phrase, 'the account of birds'. That account can be a discipline, a book, a course, a naming practice, a shared field culture, a research programme, a cabinet tradition, or an applied survey.","cn":"八个义项都源自同一个说法：「关于鸟的论述」。这份论述可以是一门学科、一部书、一门课、一套命名实践、一种共享的野外文化、一项研究纲领、一个标本柜传统，或一次应用调查。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table where skins, calipers and an old checklist lie side by side.","cn":"核心意象：一张长桌上，鸟皮标本、卡尺与一本旧名录并排放着。"},"chain":["BIRD","A REASONED ACCOUNT","A DISCIPLINE","A TAUGHT SUBJECT","CABINET AND LIBRARY","PROTECTIVE SURVEY"],"branches":[{"senses":"01 · 04","en":"THE DISCIPLINE: a branch of biology, and the naming work that began it.","cn":"学科：生物学的一个分支，以及开启它的命名工作。"},{"senses":"02 · 03","en":"EMBODIED FORMS: the account as a book, and as a slot in the timetable.","cn":"具体载体：作为一本书的论述，以及作为课程表一格的论述。"},{"senses":"05 · 06","en":"SHARED PRACTICE: volunteers and researchers feeding one dataset; birds as model organisms.","cn":"共享实践：志愿者与研究者供给同一批数据；鸟作为模式生物。"},{"senses":"07","en":"STORED EVIDENCE: the answer may be a skin in a drawer, not a bird in the bush.","cn":"储存的证据：答案可能是抽屉里的一张鸟皮，而不是枝头的一只鸟。"},{"senses":"08","en":"APPLIED SURVEY: counts that end up deciding where a turbine may stand.","cn":"应用调查：最终决定风机可以立在何处的那些计数。"}]},"affixes":{"intro":{"en":"Ornithology is three pieces: the Greek stem for bird, a linking vowel, and the suffix for a reasoned study. Longer relatives replace the last piece or add a prefix.","cn":"ornithology 是三段式：表「鸟」的希腊词干、连接元音，以及表示「成体系研究」的后缀。更长的同族词则替换末段或加前缀。"},"latinIntro":{"en":"The Greek forms behind the word are ornis (genitive ornithos), logos, pteron 'wing' and pous 'foot'; the compound ornithopod and ornithopter reuse two of them.","cn":"这个词背后的希腊词形是 ornis（属格 ornithos）、logos、pteron「翼」与 pous「脚」；复合词 ornithopod 与 ornithopter 各复用了其中两个。"},"items":[{"word":"ornith-","structure":"ornis (Greek noun, third declension, genitive ornithos)","meaning":"bird","meaningCN":"鸟","example":"The stem ornith- supplies 'bird' to every compound in the family.","exampleCN":"词干 ornith- 为这一词族的每个复合词提供「鸟」义。"},{"word":"-o-","structure":"linking vowel in Greek compounds","meaning":"a connector between two stems","meaningCN":"连接两个词干的元音","example":"The -o- lets ornith- join a second element smoothly.","exampleCN":"这个 -o- 让 ornith- 与第二个成分顺畅相接。"},{"word":"-logy","structure":"-logia (Greek noun suffix, from logos)","meaning":"the study or reasoned account of","meaningCN":"对……的研究或成体系论述","example":"Ornithology is the reasoned account of birds.","exampleCN":"鸟类学就是关于鸟的成体系论述。"},{"word":"ornithology","structure":"ornith- + -o- + -logy","meaning":"the scientific study of birds","meaningCN":"鸟类学","example":"Ornithology covers anatomy, behaviour and classification.","exampleCN":"鸟类学涵盖解剖、行为与分类。"},{"word":"ornithological","structure":"ornithology + -ical","meaning":"relating to the study of birds","meaningCN":"鸟类学的","example":"The library keeps an ornithological journal collection.","exampleCN":"图书馆收藏着一批鸟类学期刊。"},{"word":"ornithologist","structure":"ornithology + -ist","meaning":"a person who studies birds","meaningCN":"鸟类学家","example":"An ornithologist checked the identification of the specimen.","exampleCN":"一位鸟类学家核对了这份标本的鉴定。"},{"word":"ornithopod","structure":"ornith- + -pod (Greek pous, 'foot')","meaning":"a dinosaur with birdlike feet","meaningCN":"鸟脚类恐龙","example":"Ornithopods walked on three toes, like many birds.","exampleCN":"鸟脚类恐龙像许多鸟一样以三趾行走。"},{"word":"ornithopter","structure":"ornith- + -pter (Greek pteron, 'wing')","meaning":"an aircraft with flapping wings","meaningCN":"扑翼机","example":"The ornithopter flew for eleven minutes on its best trial.","exampleCN":"这架扑翼机最好的一次试飞持续了十一分钟。"},{"word":"palaeornithology","structure":"palaeo- (Greek palaios, 'old') + ornithology","meaning":"the study of fossil birds","meaningCN":"古鸟类学","example":"Palaeornithology relies on a handful of complete skeletons.","exampleCN":"古鸟类学依赖少数几具完整骨架。"}],"latinEntries":[{"word":"ornis","structure":"ornis, ornithos (Greek f., third declension)","meaning":"bird","meaningCN":"鸟"},{"word":"logos","structure":"logos, logou (Greek m., second declension)","meaning":"word, account, reason","meaningCN":"言说；论述；道理"},{"word":"pteron","structure":"pteron, pterou (Greek n., second declension)","meaning":"wing","meaningCN":"翼"},{"word":"pous","structure":"pous, podos (Greek m., third declension)","meaning":"foot","meaningCN":"脚"}]}},{"word":"ornithologist","ipa_uk":"/ˌɔːnɪˈθɒlədʒɪst/","ipa_us":"/ˌɔːrnɪˈθɑːlədʒɪst/","definition_zh":"鸟类学家；野外鸟类观察者；鸟类鉴定者；鸟类学著作的作者；鸟类标本与数据的整理者","definition_en":"a person who studies birds in a scientific or systematic way, or who works professionally at identifying, recording, curating or protecting them","core_image":"天没亮，一个人蹲在雾里的芦苇边，笔记本上写满鸟名、时间与方位","scene":"天还没亮，志愿者在塘边支起细网，把每只刚取下来的小鸟交给桌后的人。 The ornithologist fitted a numbered band to each captured bird before releasing it.","sceneCN":"这里 ornithologist 是「环志工作者」（第 6 个义项：给鸟套上编号环并记录回收数据的鸟类学工作者）；句意为这位鸟类学工作者给每只捕获的鸟套上编号环，然后把它放走。","pos":[{"tag":"n.","zh":"鸟类学家；鸟类研究工作者；可数"}],"collocations":[{"phrase":"field ornithologist","zh":"野外鸟类学家"},{"phrase":"amateur ornithologist","zh":"业余鸟类学家"},{"phrase":"museum ornithologist","zh":"博物馆鸟类学家"},{"phrase":"resident ornithologist","zh":"常驻鸟类学家"},{"phrase":"conservation ornithologist","zh":"保护鸟类学家"},{"phrase":"leading ornithologist","zh":"权威鸟类学家"}],"forms":[{"label":"原形","form":"ornithologist"},{"label":"复数","form":"ornithologists"},{"label":"形容词","form":"ornithological（鸟类学的）"},{"label":"学科名词","form":"ornithology（鸟类学）"},{"label":"副词","form":"ornithologically（就鸟类学而言）"}],"derivatives":[{"word":"ornithology","pos":"n.","zh":"鸟类学"},{"word":"ornithological","pos":"adj.","zh":"鸟类学的"},{"word":"ornithologically","pos":"adv.","zh":"从鸟类学角度"},{"word":"palaeornithologist","pos":"n.","zh":"古鸟类学家"}],"senses":[{"no":"01","title":"A Scientist Who Studies Birds","titleCN":"鸟类学家（以研究鸟为业的人）","definition":"a researcher whose professional work is the scientific study of birds","definitionCN":"以科学地研究鸟类为职业的研究者","example":"The ornithologist spent four years revising the classification of the genus.","exampleCN":"这位鸟类学家花了四年修订该属的分类。","why":"-ist marks the person who practices a -logy, so the word's first sense is simply 'one who does ornithology'.","whyCN":"-ist 标记从事某门 -logy 的人，因此这个词的第一义就是「做鸟类学的人」。"},{"no":"02","title":"A Field Observer and Recorder","titleCN":"野外观察者与记录者","definition":"a person whose work consists of walking set routes and writing down every bird seen or heard","definitionCN":"以沿固定路线行走、记录所见所闻的每一只鸟为工作的人","example":"An ornithologist walked the same transect twice a week and logged every contact.","exampleCN":"一位鸟类学工作者每周沿同一条样线走两次，记录下每一次接触。","why":"most bird evidence is gathered on foot at fixed hours, so the person's title attaches to the routine rather than to a laboratory.","whyCN":"多数鸟类证据是在固定时段徒步采集的，因此这个称谓附着于日常路线，而非实验室。"},{"no":"03","title":"A Skilled Amateur Identifier","titleCN":"业余但资深的鸟类鉴定者","definition":"a person with expert identification skill who is not employed as a researcher","definitionCN":"具备专家级鉴定能力、但并非受雇研究者的人","example":"Though unpaid, she was the ornithologist everyone consulted about gulls.","exampleCN":"虽然没有报酬，她却是大家遇到鸥类问题都要请教的鸟类学家。","why":"the title follows demonstrated skill rather than a salary, so a dedicated volunteer can wear it without a degree.","whyCN":"这个称谓跟的是已被证明的本领而非薪水，因此专注的志愿者没有学位也能担当。"},{"no":"04","title":"The Author of a Bird Study","titleCN":"鸟类学著作的作者","definition":"the person who writes a regional or systematic account of birds","definitionCN":"撰写某一地区或某一类群鸟类系统论述的人","example":"The ornithologist who wrote the 1922 volume never visited the island.","exampleCN":"写出 1922 年那卷书的鸟类学家从未到过这座岛。","why":"before the word named a profession it named the author of an ornithology, and that sense survives in bibliographic writing.","whyCN":"在这个词成为职业名之前，它先指一部鸟类学著作的作者，这一义项在书目写作中留存。"},{"no":"05","title":"A Curator of Study Skins","titleCN":"鸟类标本的管理者","definition":"a person responsible for the care, labelling and loan of preserved bird specimens","definitionCN":"负责保存鸟皮标本的养护、标注与外借的人","example":"The museum's ornithologist rehoused ten thousand study skins in new cabinets.","exampleCN":"博物馆的鸟类学家把一万件鸟皮标本移入新标本柜。","why":"a collection is only usable if someone keeps its labels honest, so the title also belongs to the keeper of the cabinet.","whyCN":"藏品只有靠人保证标签可靠才可用，因此这个称谓也属于看管标本柜的人。"},{"no":"06","title":"A Banding Worker","titleCN":"环志工作者","definition":"a person who catches birds, fits numbered rings or bands and files the recovery records","definitionCN":"捕捉鸟类、套上编号环或腿环并归档回收记录的人","example":"The ornithologist opened the mist net well before first light.","exampleCN":"这位鸟类学工作者在天亮前很久就张开了雾网。","why":"banding is the discipline's main way of following individual birds, and the person doing it is named by the field rather than by a degree.","whyCN":"环志是该学科追踪个体鸟的主要手段，做这件事的人是按工作领域而非学位来称呼的。"},{"no":"07","title":"A Conservation Scientist for Birds","titleCN":"保护鸟类学家","definition":"a researcher who turns bird survey data into advice on land use, turbines, or protected areas","definitionCN":"把鸟类调查数据转化为土地使用、风机选址或保护区建议的研究者","example":"The ornithologist advised the agency on where to reroute the pipeline.","exampleCN":"这位鸟类学家就管道改线位置向主管机构提供建议。","why":"when population counts are used to decide where things may be built, the researcher's title moves into applied work.","whyCN":"当种群计数被用来决定何处可以施工，研究者的称谓便进入了应用工作。"},{"no":"08","title":"An Expert on Bird Song","titleCN":"凭鸣声辨识鸟类的专家","definition":"a person able to identify species by call alone, without seeing the bird","definitionCN":"仅凭鸣叫就能识别物种、不必看到鸟的人","example":"A patient ornithologist can name a warbler from four notes.","exampleCN":"有耐心的鸟类学家凭四个音就能叫出一只柳莺的名字。","why":"in dense cover the ear replaces the eye, so a specialised skill becomes a recognised identity within the field.","whyCN":"在茂密灌丛里耳朵取代了眼睛，于是某种专门技能在业内成为一种被认可的身份。"}],"etymology":{"intro":{"en":"Ornithologist is ornithology plus -ist, the agent suffix that names a person who practices something; ornithology itself is Greek ornis 'bird' (genitive ornithos) plus -logia. The Greek agent suffix was -istēs, which reached English through Latin -ista and French -iste.","cn":"ornithologist 是 ornithology 加 -ist，这个施事后缀用来称呼从事某事的人；ornithology 本身是希腊 ornis「鸟」（属格 ornithos）加 -logia。希腊语中的施事后缀为 -istēs，经拉丁 -ista 与法语 -iste 进入英语。"},"items":[{"era":"GREEK ORNIS","en":"Ornis, genitive ornithos, is the Greek noun for 'bird'; it supplies the first element of both ornithology and ornithologist.","cn":"ornis 的属格为 ornithos，是希腊语中表「鸟」的名词；它同时提供 ornithology 与 ornithologist 的第一成分。"},{"era":"GREEK LOGOS","en":"Logos 'word, account, reason' produced -logia, the suffix for a reasoned study; the discipline's name therefore means 'account of birds'.","cn":"logos「言说、叙述、道理」产生后缀 -logia，表示成体系的研究；学科名因此意为「关于鸟的论述」。"},{"era":"GREEK -ISTES","en":"The Greek agent suffix -istēs named the person who does what the base word describes, and it passed into Latin as -ista and into English as -ist.","cn":"希腊施事后缀 -istēs 指从事词基所述之事的人，后经拉丁 -ista 进入英语作 -ist。"},{"era":"LATIN ORNITHOLOGIA","en":"Ornithologia was coined in early modern scientific Latin from the Greek pieces; its usual attribution to Aldrovandi's Ornithologiae (1599) is a general view, not a documented certainty.","cn":"ornithologia 由希腊成分在近代早期科学拉丁语中造出；通常归于阿尔德罗万迪 1599 年的《鸟类学》，这是一般看法，而非有文献确证的事实。"},{"era":"ENGLISH ORNITHOLOGIST","en":"English ornithologist is recorded from the eighteenth century, shortly after ornithology itself entered the language; the earliest citation is not firmly fixed.","cn":"英语 ornithologist 自 18 世纪有记录，晚于 ornithology 进入英语不久；最早的书证尚未确定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first date of ornithologist and the pre-Greek origin of ornis both remain open; only the Greek stem plus the agent suffix is securely established.","cn":"来源不确定：ornithologist 的确切首见年代与 ornis 在希腊语之前的来源都仍无定论；可以确定的是希腊词干加施事后缀这一层。"}]},"similar":{"note":{"en":"Group one separates look-alikes: two share the ornithology base, two merely carry a -ist ending. Group two sets the person beside the nearby roles, from hobbyist to general scientist.","cn":"第一组区分形近词：两个共享 ornithology 词基，两个只是同样带 -ist 结尾。第二组把这个身份放在从爱好者到通才科学家的邻近角色之间。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ornithology","ipa":"/ˌɔːnɪˈθɒlədʒi/","tag":"same base, the field","definition":"The discipline itself, built on the same two Greek pieces; it names the study, while ornithologist names the person.","definitionCN":"学科本身，由同样的两个希腊成分构成；它指这门研究，而 ornithologist 指人。"},{"word":"ornithological","ipa":"/ˌɔːnɪθəˈlɒdʒɪkəl/","tag":"same base, adjective","definition":"The adjective of the field, describing journals and methods rather than a worker; the base is shared with ornithologist.","definitionCN":"该领域的形容词，描述期刊与方法而非工作者；与 ornithologist 共享词基。"},{"word":"optometrist","ipa":"/ɒpˈtɒmətrɪst/","tag":"different root, -ist only","definition":"From Greek opsis 'sight' plus metron 'measure': a person who measures vision; the ending resembles -ologist but the root is unrelated.","definitionCN":"来自希腊 opsis「视觉」加 metron「测量」：测量视力的人；结尾像 -ologist，但词根无关。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"different root, same pattern","definition":"Geo- 'earth' plus -logist: a student of rocks; it shows that -ologist is a productive pattern, not evidence of a shared root.","definitionCN":"geo-「大地」加 -logist：研究岩石的人；这说明 -ologist 是能产模式，并不证明词根相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"birdwatcher","ipa":"/ˈbɜːdwɒtʃə/","tag":"leisure","definition":"A person who watches birds for pleasure; an ornithologist may do the same, but is expected to produce records or research.","definitionCN":"以观鸟为乐的人；ornithologist 也可能这样做，但被期待产出记录或研究成果。"},{"word":"birder","ipa":"/ˈbɜːdə/","tag":"American hobby term","definition":"An American word for an active birdwatcher who keeps lists; it marks a hobby identity rather than a profession.","definitionCN":"美式说法，指积极观鸟并记录名录的人；标记的是爱好身份而非职业。"},{"word":"naturalist","ipa":"/ˈnætʃərəlɪst/","tag":"broader","definition":"A person who studies living things in the field across groups; ornithologist narrows that role to one class.","definitionCN":"在野外研究各类生物的人；ornithologist 把这个角色收窄到一个纲。"},{"word":"ecologist","ipa":"/ɪˈkɒlədʒɪst/","tag":"broader method","definition":"A scientist who studies relationships between organisms and their surroundings; some ecologists work on birds without being ornithologists.","definitionCN":"研究生物与环境关系的科学家；有些生态学家研究鸟，但并非鸟类学家。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real agent suffix, the real Greek stem and the real institutional roles.","cn":"正常联想：真实的施事后缀、真实的希腊词干与真实的机构角色。"},"normal":[{"en":"ornith- 'bird' + -o- + -logy 'study' + -ist 'person': the whole word is a job description.","cn":"ornith-「鸟」+ -o- + -logy「学」+ -ist「人」：整个词就是一句职务说明。"},{"en":"-ist marks the doer, exactly as in biologist and geologist, so the ending is a pattern rather than a root.","cn":"-ist 标记执行者，正如 biologist 与 geologist，因此这个结尾是模式而非词根。"},{"en":"Real roles fix the senses: field, museum and conservation ornithologist.","cn":"真实角色固定了各义项：野外、博物馆与保护鸟类学家。"},{"en":"The base word is ornithology, so anyone called an ornithologist is assumed to know the discipline's literature.","cn":"词基是 ornithology，因此被称为 ornithologist 的人被假定熟悉该学科的文献。"},{"en":"Family: ornithology, ornithological, ornithologically, palaeornithologist.","cn":"同族词：ornithology、ornithological、ornithologically、palaeornithologist。"}],"abstract":[{"en":"Picture a knee-high notebook open in the dark, a headlamp angled down at the page.","cn":"想象天还黑着，一本齐膝高的笔记本摊开，头灯的光斜照在纸页上。"},{"en":"Picture a drawer of skins whose labels only one person can vouch for.","cn":"想象一柜鸟皮标本，只有一个人能为其标签作保。"},{"en":"Picture a hand holding a bird, a ring on the tarsus, a stopwatch running.","cn":"想象一只手托着鸟，跗跖上套着环，秒表在走。"}]},"examples":[{"en":"Two ornithologists independently described the same subspecies.","cn":"两位鸟类学家各自独立地描述了同一个亚种。"},{"en":"The park hired an ornithologist to run its breeding survey.","cn":"公园聘请了一位鸟类学家主持繁殖调查。"},{"en":"As an ornithologist, he was more at home in a marsh than in a lecture hall.","cn":"作为鸟类学家，他在沼泽里比在讲堂里更自在。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「奥尼索罗吉斯特」——「奥尼」是鸟，「罗吉」是学，「斯特」是人 → 研究鸟的人","word":"ornithologist"},"root":"ornithology + -ist（希腊施事后缀 -istēs，经拉丁 -ista、法语 -iste 进入英语）。ornithology 为希腊 ornis「鸟」（属格 ornithos）+ -logia「对……的论述、研究」。英语 ornithologist 自 18 世纪有记录，确切首见年代存疑。","sensesIntro":{"en":"All eight senses answer one question: who is doing the bird work? The answer may be a salaried researcher, a route walker, a gifted amateur, an author, a curator, a bander, an adviser or an ear-trained identifier.","cn":"八个义项都在回答同一个问题：是谁在做与鸟有关的工作？答案可以是受薪研究者、走样线的人、有天赋的业余者、作者、标本管理者、环志者、顾问，或靠耳朵辨鸟的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person crouching at dawn with a notebook open on one knee.","cn":"核心意象：黎明时分，一个人蹲着，笔记本摊在膝上。"},"chain":["BIRD","STUDY OF BIRDS","THE PRACTITIONER","FIELD ROUTE","SPECIMEN DRAWER","IDENTIFICATION BY EAR"],"branches":[{"senses":"01 · 04","en":"KNOWLEDGE AND ITS AUTHOR: the researcher, and the writer who sets the knowledge down.","cn":"知识及其作者：研究者，以及把知识写定的人。"},{"senses":"02 · 03","en":"SKILL WITHOUT A PAYSLIP: the route walker and the unpaid expert the others consult.","cn":"没有薪水的本领：走样线的人，以及众人请教的业余专家。"},{"senses":"05","en":"THE CABINET KEEPER: someone must vouch for every label in the drawer.","cn":"标本柜看守：抽屉里每张标签都必须有人作保。"},{"senses":"06 · 07","en":"FOLLOWING AND PROTECTING: a ring on the leg, then advice on where to build.","cn":"追踪与保护：腿上的环，随后是关于施工地点的建议。"},{"senses":"08","en":"THE EAR AS INSTRUMENT: in cover, hearing replaces sight.","cn":"耳朵作仪器：在灌丛里，听觉取代视觉。"}]},"affixes":{"intro":{"en":"Ornithologist adds one more piece to the discipline's name: the agent suffix that says 'the person who'. Everything else is shared with ornithology.","cn":"ornithologist 在学科名之后再接一段：表示「做这件事的人」的施事后缀。其余部分与 ornithology 共用。"},"latinIntro":{"en":"Greek ornis (genitive ornithos) and logos supply the stem and the suffix -logia; the agent suffix -istēs came through Latin -ista and French -iste.","cn":"希腊 ornis（属格 ornithos）与 logos 提供词干与后缀 -logia；施事后缀 -istēs 经拉丁 -ista 与法语 -iste 传来。"},"items":[{"word":"ornith-","structure":"ornis (Greek noun, third declension, genitive ornithos)","meaning":"bird","meaningCN":"鸟","example":"The stem ornith- carries 'bird' through the whole family.","exampleCN":"词干 ornith- 在整个词族中承载「鸟」义。"},{"word":"-o-","structure":"linking vowel in Greek compounds","meaning":"a connector between stems","meaningCN":"词干之间的连接元音","example":"The -o- joins ornith- to the suffix that follows.","exampleCN":"这个 -o- 把 ornith- 与后面的后缀连接起来。"},{"word":"-logy","structure":"-logia (Greek noun suffix, from logos)","meaning":"the study or reasoned account of","meaningCN":"对……的研究或成体系论述","example":"Ornithology is the study of birds.","exampleCN":"鸟类学就是对鸟的研究。"},{"word":"-ist","structure":"-istēs (Greek agent suffix, via Latin -ista and French -iste)","meaning":"a person who practices or studies something","meaningCN":"从事或研究某事的人","example":"The suffix turns the field into the person.","exampleCN":"这个后缀把学科变成从事该学科的人。"},{"word":"ornithology","structure":"ornith- + -o- + -logy","meaning":"the scientific study of birds","meaningCN":"鸟类学","example":"She trained in ornithology before moving into conservation.","exampleCN":"她在转入保护工作之前受过鸟类学训练。"},{"word":"ornithologist","structure":"ornithology + -ist","meaning":"a person who studies birds","meaningCN":"鸟类学家","example":"The ornithologist checked the ageing of the specimen.","exampleCN":"这位鸟类学家核对了标本的年龄鉴定。"},{"word":"ornithological","structure":"ornithology + -ical","meaning":"relating to the study of birds","meaningCN":"鸟类学的","example":"The ornithological record goes back to 1870.","exampleCN":"这份鸟类学记录可追溯至 1870 年。"},{"word":"palaeornithologist","structure":"palaeo- (Greek palaios, 'old') + ornithologist","meaning":"a specialist in fossil birds","meaningCN":"古鸟类学家","example":"The palaeornithologist measured the fossil humerus.","exampleCN":"古鸟类学家测量了这块化石肱骨。"}],"latinEntries":[{"word":"ornis","structure":"ornis, ornithos (Greek f., third declension)","meaning":"bird","meaningCN":"鸟"},{"word":"logos","structure":"logos, logou (Greek m., second declension)","meaning":"word, account, reason","meaningCN":"言说；论述；道理"},{"word":"ornithologia","structure":"ornithologia, -ae (scientific Latin f., first declension)","meaning":"the account of birds","meaningCN":"鸟类论述；鸟类学"}]}},{"word":"feather","ipa_uk":"/ˈfeðə/","ipa_us":"/ˈfeðər/","definition_zh":"羽毛（单根或鸟的全身羽衣）；羽饰；羽毛笔；可夸耀的荣誉；同类人；中饱私囊","definition_en":"a single plume or the whole coat of a bird, and by extension an ornament, a quill pen, a mark of honour, or a sign of belonging to the same kind","core_image":"一柄中空的羽轴两侧排开细密的羽枝，像一把可以随身携带的轻扇","scene":"老图书馆的玻璃柜里，一支削好的鹅羽斜插在墨水瓶旁，笔尖还留着旧墨。 A curator lifted the feather that had written three centuries of parish records.","sceneCN":"这里 feather 是「羽毛笔」（第 4 个义项：削制后蘸墨书写的羽管笔）；句意为一位馆员拿起了那支曾书写三百年教区记录的羽毛笔。","pos":[{"tag":"n.","zh":"羽毛；羽饰；羽毛笔（可数，复数 feathers）"},{"tag":"vt.","zh":"给……装上羽毛；把桨叶放平（feathered, feathering）"}],"collocations":[{"phrase":"feather duster","zh":"羽毛掸子"},{"phrase":"feather boa","zh":"羽毛长围巾"},{"phrase":"feather pillow","zh":"羽绒枕"},{"phrase":"tail feather","zh":"尾羽"},{"phrase":"a feather in one's cap","zh":"值得夸耀的成就"},{"phrase":"birds of a feather","zh":"同类人；一丘之貉"},{"phrase":"feather one's nest","zh":"中饱私囊；为自己捞好处"}],"forms":[{"label":"复数","form":"feathers"},{"label":"第三人称单数","form":"feathers"},{"label":"过去式","form":"feathered"},{"label":"过去分词","form":"feathered"},{"label":"现在分词","form":"feathering"},{"label":"形容词（有羽毛的）","form":"feathered"},{"label":"形容词（羽毛般的）","form":"feathery"}],"derivatives":[{"word":"feathered","pos":"adj.","zh":"有羽毛的；饰以羽毛的"},{"word":"feathery","pos":"adj.","zh":"羽毛般的；轻软蓬松的"},{"word":"featherless","pos":"adj.","zh":"无羽毛的"},{"word":"feathering","pos":"n.","zh":"羽饰；桨叶放平的动作"},{"word":"featherweight","pos":"n.","zh":"羽量级（拳击等按体重划分的级别）"}],"senses":[{"no":"01","title":"One Single Plume","titleCN":"一根羽毛（结构单位）","definition":"one of the light, flat growths that cover a bird, consisting of a central shaft with soft branches on either side","definitionCN":"覆盖鸟类体表的一枚轻而扁的生成物，由中央羽轴与两侧柔软的羽枝构成","example":"A single feather lay on the gravel path, its shaft still unbroken.","exampleCN":"一根羽毛落在碎石小径上，羽轴还没有折断。","why":"feather begins as a countable object: one shaft, one unit that can be picked up and examined by itself.","whyCN":"feather 的起点是一个可数物件：一根羽轴就是一个单位，能被单独拾起、单独观察。"},{"no":"02","title":"The Whole Body Coat","titleCN":"鸟的全身羽衣（羽毛总称）","definition":"the entire covering of plumes on a bird, considered as one coat that keeps it warm, dry and able to fly","definitionCN":"鸟体表全部羽毛的总和，被看作一件保暖、防水并支持飞行的外衣","example":"By October the young swan's feathers had turned from grey to white.","exampleCN":"到了十月，小天鹅的羽毛已由灰色转为白色。","why":"many single plumes overlap into one surface, so the same word names the collective coat rather than any one piece of it.","whyCN":"许多单根羽毛彼此叠合成一个表面，于是同一个词也指这件集体的外衣，而不是其中某一根。"},{"no":"03","title":"Worn as an Ornament","titleCN":"羽饰；帽饰上的羽毛","definition":"a plume worn on a hat, helmet or garment as decoration or as a badge of rank","definitionCN":"插在帽子、头盔或衣物上作装饰或表示身份的羽毛","example":"The dancer wore a scarlet feather in her hair on the opening night.","exampleCN":"首演之夜，舞者在发间插了一根猩红色的羽毛。","why":"a plume taken off the bird and pinned to a person stops being covering and becomes display, which is the ornamental sense.","whyCN":"从鸟身上取下、别在人身上的羽毛不再是覆盖物，而成为展示，这就是羽饰义。"},{"no":"04","title":"The Writing Quill","titleCN":"羽毛笔（历史义）","definition":"a large flight feather trimmed and cut into a pen for writing with ink","definitionCN":"把大型飞羽修削成笔尖、用来蘸墨书写的笔","example":"He sharpened the feather with a small knife before dipping it in ink.","exampleCN":"他先用小刀修削那根羽毛，然后才蘸墨。","why":"the hollow shaft of a goose feather holds ink and has a natural nib, so the object itself became the tool and kept its name.","whyCN":"鹅羽中空的羽轴能蓄墨，尖端又天然形成笔锋，物件本身成了工具，名字也就沿用了下来。"},{"no":"05","title":"A Feather in One's Cap","titleCN":"可夸耀的荣誉；值得炫耀的成就","definition":"an achievement or distinction that a person can be proud of and display publicly","definitionCN":"一个人可以引以为荣、并公开展示的成就或殊荣","example":"Winning the county prize was a feather in the young baker's cap.","exampleCN":"赢得郡里的奖项，是这位年轻面包师帽上的一根羽毛。","why":"the idiom keeps the ornamental sense: a plume on a hat is exactly a visible badge that says look at what I have done.","whyCN":"这个习语保留了羽饰义：帽上的一根羽毛正是看得见的徽章，说的是「看我做成了什么」。"},{"no":"06","title":"Birds of a Feather","titleCN":"同类人；一丘之貉","definition":"people of the same kind or character, who naturally keep company with one another","definitionCN":"种类或性情相同、自然愿意聚在一起的人","example":"The two collectors were birds of a feather and met at the same auction every Sunday.","exampleCN":"这两位收藏家是同一类人，每个星期天都在同一场拍卖会上碰面。","why":"the proverb borrows the barnyard fact that birds of one plumage flock together, and applies the sameness to people.","whyCN":"这条谚语借用了农家院里的常识：羽色相同的鸟会聚成一群，再把这种相同性套到人身上。"},{"no":"07","title":"Feather One's Nest","titleCN":"中饱私囊；为自己捞好处","definition":"to enrich oneself, often dishonestly, especially by taking money entrusted to one","definitionCN":"尤指以不诚实的方式、拿取托付给自己的钱财来中饱私囊","example":"The treasurer had feathered his nest for years before the audit began.","exampleCN":"审计开始之前，那位财务主管已经中饱私囊多年。","why":"a bird lines its own nest with soft feathers for comfort, and the idiom darkens that private comfort into private gain at others' expense.","whyCN":"鸟用柔软的羽毛铺自己的窝求舒适，这个习语把这层私人的舒适转成损公肥私的私利。"},{"no":"08","title":"Laying the Oar Flat","titleCN":"划船时把桨叶放平（动词义）","definition":"to turn an oar blade flat to the water at the end of a stroke, so that it moves back without catching the water","definitionCN":"每一桨结束时把桨叶转平贴向水面，使回桨时不兜水","example":"The rower feathered the oar at the end of each stroke to reduce drag.","exampleCN":"划手在每桨结束时把桨叶放平，以减小阻力。","why":"the blade is turned as flat and light as a feather on the recovery, and the verb borrows that feather-like flatness.","whyCN":"回桨时桨叶被转得又平又轻，像一根羽毛，动词正是借了这种「如羽之平」。"}],"etymology":{"intro":{"en":"Feather goes back to Old English feðer, a Germanic word for a plume and also for a wing; the modern spelling settled after the Middle English period. Dates are approximate.","cn":"feather 可上溯到古英语 feðer，是日耳曼语中表示羽毛、也兼指翼的词；现代拼写在英语中古期之后才固定下来。年代均为约数。"},"items":[{"era":"OLD ENGLISH FETHER","en":"Feðer named both a single plume and the wing that the plumes form, which is why the older word served where English later uses wing.","cn":"feðer 既指单根羽毛，也指羽毛构成的翼，因此这个更古老的词曾承担后来表示「翼」的那个词的功能。"},{"era":"GERMANIC KIN","en":"The same word survives in German Feder and Dutch veder, both meaning feather, which confirms a Germanic family rather than a Latin borrowing.","cn":"同一个词在德语 Feder 与荷兰语 veder 中留存，二者都指羽毛，这证明它属于日耳曼语族，而非拉丁语借词。"},{"era":"PIE *PET-","en":"Feather is generally thought to derive from a reconstructed root *pet- 'to rush, to fly'; Greek pteron 'wing' and Latin penna 'feather' are often grouped with it under that root.","cn":"feather 一般认为是重构词根 *pet-「冲、飞」的派生；希腊语 pteron「翼」与拉丁语 penna「羽」常被归入同一词根之下。"},{"era":"MIDDLE ENGLISH FETHER","en":"Middle English fether kept the meaning and later lost the voiced ending in spelling, while the ornamental and writing senses grew in the same period.","cn":"中古英语 fether 保留了原义，后来拼写上失去词尾的浊音；羽饰义与书写义也在同一时期发展出来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the *pet- grouping is a generally accepted hypothesis, not a settled fact, and the exact first date of the pen and ornament senses is not firmly recorded.","cn":"来源不确定：*pet- 的归组属一般认为是正确的假说，而非定论；羽毛笔义与羽饰义的最早出现年代也没有可靠记录。"}]},"similar":{"note":{"en":"Group one holds words that look close to feather but come from unrelated roots; group two holds the real bird-covering and writing words that overlap with it.","cn":"第一组是外形接近但词根无关的词；第二组是在鸟类覆盖物与书写工具上与之真正重叠的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fetter","ipa":"/ˈfetə/","tag":"different root","definition":"A chain for the feet, from Old English feter; despite the shared -etter shape it has nothing to do with plumes.","definitionCN":"脚镣，来自古英语 feter；尽管同样带 -etter 的形状，它与羽毛毫无关系。"},{"word":"feat","ipa":"/fiːt/","tag":"different root","definition":"A notable deed, from Latin factum 'something done'; the resemblance to feather is only in the first letters.","definitionCN":"功绩，来自拉丁 factum「做成之事」；与 feather 的相似只在开头几个字母。"},{"word":"leather","ipa":"/ˈleðə/","tag":"different root","definition":"Prepared animal skin, from Old English leþer; it shares the -ther ending but belongs to the hide family, not the plume family.","definitionCN":"鞣制过的兽皮，来自古英语 leþer；同样以 -ther 收尾，却属于「皮」的家族而非「羽」的家族。"},{"word":"weather","ipa":"/ˈweðə/","tag":"different root","definition":"The state of the atmosphere, from Old English weder; the ending matches, the root does not.","definitionCN":"天气状况，来自古英语 weder；词尾相同，词根不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"plume","ipa":"/pluːm/","tag":"single large feather","definition":"A large or showy feather, especially one used as an ornament; narrower than feather, which also names the whole coat.","definitionCN":"大而显眼的羽毛，尤指用作装饰的一根；比 feather 窄，后者还指整件羽衣。"},{"word":"down","ipa":"/daʊn/","tag":"soft underlayer","definition":"The fine soft feathers beneath the outer coat, valued for insulation; it is a layer of the coat, not a whole plume.","definitionCN":"外层羽毛之下细软的绒毛，以保暖见长；它是羽衣的一层，而不是一整根羽毛。"},{"word":"quill","ipa":"/kwɪl/","tag":"shaft used as a pen","definition":"The hollow shaft of a large feather, or a pen cut from it; it stresses the writing tube where feather stresses the whole plume.","definitionCN":"大羽的中空羽轴，或由其削成的笔；它强调书写用的管子，而 feather 强调整根羽毛。"},{"word":"plumage","ipa":"/ˈpluːmɪdʒ/","tag":"collective noun","definition":"The whole feather covering of a bird seen as one unit of colour and pattern; it is the collective counterpart of feather.","definitionCN":"把鸟的整身羽毛视为一个色彩与图案单位；它是 feather 的集合名词对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real structure of a plume, the real phrases it appears in, and the real family of derivatives.","cn":"正常联想：羽毛的真实结构、它所在的真实搭配，以及真实的派生词家族。"},"normal":[{"en":"A feather is one shaft with two soft fans, light enough to be carried by the wind.","cn":"一根羽毛就是一根羽轴加两片柔软的羽片，轻到能被风带走。"},{"en":"The same word covers one plume and the whole coat, just as hair can mean one strand or all of it.","cn":"同一个词既指一根羽毛也指整身羽衣，正如「头发」一词既可指一根头发也可指全部头发。"},{"en":"Fixed phrases fix the idioms: a feather in one's cap, birds of a feather, feather one's nest.","cn":"固定搭配锁定习语义：帽上之羽、同羽之鸟、为窝铺羽。"},{"en":"The family runs feathered, feathery, featherless, feathering, featherweight.","cn":"同族词包括 feathered、feathery、featherless、feathering、featherweight。"},{"en":"Rowers feather the oar because a flat blade, like a feather, slips back through the air.","cn":"划手把桨叶放平，因为平贴的桨叶像羽毛一样能轻巧地回撤。"}],"abstract":[{"en":"Picture a hat with one bright plume: everyone can read the achievement without being told.","cn":"想象帽子上插着一根鲜艳的羽毛：不用开口，人人都读得出那份成就。"},{"en":"Picture a nest lined with soft plumes taken from elsewhere: comfort paid for by someone else.","cn":"想象一个用别处取来的软羽铺成的窝：舒适由别人买单。"},{"en":"Picture a flock where every bird has the same markings, so no outsider is welcome.","cn":"想象一群鸟羽色完全相同，外来者一眼就被排除在外。"}]},"examples":[{"en":"The museum's oldest exhibit is a single feather from a bird that no longer exists.","cn":"博物馆最古老的展品是一根来自已灭绝鸟类的羽毛。"},{"en":"Feathers keep a bird warm and dry, but they also make it easy for a predator to spot.","cn":"羽毛让鸟保暖、防水，却也让捕食者更容易发现它。"},{"en":"After the storm, feathers were stuck to the wire fence along the shore.","cn":"风暴过后，羽毛粘在岸边的铁丝围栏上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「费德」——费尽心机才得到一根羽毛，赶快插在帽子上到处炫耀","word":"feather"},"root":"古英语 feðer「羽毛、翼」，属日耳曼语族（德语 Feder、荷兰语 veder 同源）；一般认为是原始印欧语 *pet-「冲、飞」的派生，希腊 pteron「翼」、拉丁 penna「羽」常被归入同一组，但这一归组属「一般认为是」的假说而非定论，*pet- 本身为重构形式。羽饰、羽毛笔、习语诸义均为英语后期引申。","sensesIntro":{"en":"The eight senses of feather follow one object outward: a single plume, then the whole coat it builds, then the uses people found for it as ornament, pen, badge, password and lining.","cn":"feather 的八个义项沿着同一个物件向外展开：先是一根羽毛，再是它构成的整身羽衣，然后是人为它找到的用途——装饰、书写、徽章、暗号与铺窝。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hollow shaft carrying two soft fans of barbs, light enough to ride the air.","cn":"核心意象：一根中空的羽轴托着两片柔软的羽片，轻得可以乘风。"},"chain":["SINGLE PLUME","WHOLE COAT","WORN FOR DISPLAY","SHAFT AS PEN","VISIBLE HONOUR","PRIVATE GAIN"],"branches":[{"senses":"01 · 02","en":"BODY: one unit and the entire covering built from many such units.","cn":"身体：一个单位，以及由许多单位构成的整件覆盖物。"},{"senses":"03 · 04","en":"HAND USE: the plume is detached and put to work, on a hat or in ink.","cn":"人手之用：羽毛被取下派用场，插在帽上或蘸墨书写。"},{"senses":"05","en":"BADGE: a worn plume becomes a public sign of achievement.","cn":"徽章：被佩戴的羽毛成为公开的成就标志。"},{"senses":"06","en":"KINDRED: identical plumage marks the same kind and the same company.","cn":"同类：相同的羽色标记相同的种类与相同的伙伴。"},{"senses":"07 · 08","en":"VERB EDGE: to line one's nest, or to flatten the oar like a plume.","cn":"动词边缘：为自己的窝铺垫，或把桨叶放平如羽毛。"}]},"affixes":{"intro":{"en":"Feather is a Germanic base that English has built on with its own suffixes and compounds rather than with Latin affixes.","cn":"feather 是一个日耳曼语词基，英语用自身的后缀与复合方式在上面造词，而不是借助拉丁词缀。"},"latinIntro":{"en":"There is no reliably attested Latin derivative of this Germanic word; Latin penna and pluma are cognate hypotheses, not sources of the English family.","cn":"这个日耳曼词没有可靠的拉丁派生词；拉丁 penna 与 pluma 只是同源假说中的对应词，并非英语这个词族的来源。"},"items":[{"word":"feather","structure":"feðer (Old English noun, strong feminine)","meaning":"plume; wing","meaningCN":"羽毛；翼","example":"The base word already covered both the plume and the wing.","exampleCN":"这个词基原本同时涵盖羽毛与翼。"},{"word":"-ed","structure":"-ed (English participial suffix)","meaning":"having, provided with","meaningCN":"具有……的；配备……的","example":"Feathered means provided with feathers.","exampleCN":"feathered 意为配有羽毛的。"},{"word":"feathered","structure":"feather + -ed","meaning":"covered or decorated with feathers","meaningCN":"覆有羽毛的；饰以羽毛的","example":"The feathered headdress belonged to a tribal chief.","exampleCN":"那顶饰羽头饰属于一位部落首领。"},{"word":"-y","structure":"-y (English adjective suffix)","meaning":"like, characterized by","meaningCN":"像……的；具有……特征的","example":"Feathery turns the noun into a description of texture.","exampleCN":"feathery 把名词变成对质地的描述。"},{"word":"feathery","structure":"feather + -y","meaning":"soft and light like a plume","meaningCN":"如羽毛般轻软的","example":"The fern has feathery fronds.","exampleCN":"这种蕨类长着羽毛般的叶状体。"},{"word":"-less","structure":"-lēas (Old English suffix)","meaning":"without, lacking","meaningCN":"没有……的；缺乏……的","example":"The suffix marks the absence of the covering.","exampleCN":"这个后缀表示覆盖物的缺失。"},{"word":"featherless","structure":"feather + -less","meaning":"having no feathers","meaningCN":"无羽毛的","example":"A newly hatched chick is almost featherless.","exampleCN":"刚孵出的雏鸟几乎全身无羽。"},{"word":"feathering","structure":"feather + -ing","meaning":"the act of fitting feathers, or of flattening an oar","meaningCN":"装羽；桨叶放平","example":"The feathering of the oar smooths the recovery.","exampleCN":"桨叶放平使回桨更顺畅。"},{"word":"featherweight","structure":"feather + weight","meaning":"a light boxing class, or a very light person","meaningCN":"羽量级；极轻的人或物","example":"He fought at featherweight for most of his career.","exampleCN":"他职业生涯的大部分时间都在羽量级比赛。"}],"latinEntries":[]}},{"word":"plumage","ipa_uk":"/ˈpluːmɪdʒ/","ipa_us":"/ˈpluːmɪdʒ/","definition_zh":"鸟的全身羽毛（集合名词）；换羽后的羽色状态；繁殖羽；幼羽与绒羽；羽色识别特征；华服（书面比喻）","definition_en":"the entire feather covering of a bird, especially considered as a pattern of colour that changes with age, season and species","core_image":"一只鸟从头到脚披着一件由无数羽片拼成的外衣，花纹随季节换色","scene":"园里的孔雀把尾屏完全展开，金属般的眼斑在午后阳光里连成一片。 The male spreads his plumage into a fan of bronze and blue whenever a visitor comes near.","sceneCN":"这里 plumage 是「装饰性的整身羽衣」（第 6 个义项：孔雀等用于展示的华丽羽毛）；句意为每当有人靠近，雄鸟就把羽衣展开成一把青铜与蓝色相间的扇子。","pos":[{"tag":"n.","zh":"鸟的全身羽毛；羽衣；羽色（不可数，无复数）"}],"collocations":[{"phrase":"breeding plumage","zh":"繁殖羽；婚羽"},{"phrase":"winter plumage","zh":"冬羽"},{"phrase":"juvenile plumage","zh":"幼鸟羽衣"},{"phrase":"bright plumage","zh":"鲜艳的羽色"},{"phrase":"plumage colour","zh":"羽色"},{"phrase":"moult into plumage","zh":"换羽进入某种羽色"}],"forms":[{"label":"原形（不可数名词）","form":"plumage"},{"label":"形容词（有……羽衣的）","form":"plumaged"},{"label":"形容词（羽毛状的）","form":"plumy"},{"label":"同根名词","form":"plume"},{"label":"同根形容词","form":"plumose"}],"derivatives":[{"word":"plume","pos":"n.","zh":"羽毛；大羽（尤指装饰用）"},{"word":"plumaged","pos":"adj.","zh":"具有某种羽衣的（多用于复合词）"},{"word":"plumy","pos":"adj.","zh":"羽毛状的；覆有羽毛的"},{"word":"plumose","pos":"adj.","zh":"羽状的；长有细密分枝的"},{"word":"plumule","pos":"n.","zh":"绒羽；胚芽"}],"senses":[{"no":"01","title":"The Whole Feather Coat","titleCN":"鸟的全身羽毛（集合名词）","definition":"the complete covering of feathers on a bird, treated as a single garment rather than as separate plumes","definitionCN":"鸟体表全部羽毛的总和，被当作一件完整的外衣而不是一根根分开的羽毛","example":"The plumage of the adult heron is a soft grey from crown to tail.","exampleCN":"成年苍鹭的羽衣从头顶到尾端都是柔和的灰色。","why":"plumage is a collective noun built from plume, so it never counts single feathers; it names the coat they make together.","whyCN":"plumage 是由 plume 构成的集合名词，因此从不数单根羽毛，而指它们合成的那件外衣。"},{"no":"02","title":"The Colour State After Moulting","titleCN":"换羽后的羽色状态","definition":"the particular colour and condition of a bird's feathers at a given stage of its annual moult","definitionCN":"鸟在一年一度换羽的某一阶段所呈现的具体颜色与状态","example":"After the autumn moult its plumage was noticeably duller than in spring.","exampleCN":"秋季换羽之后，它的羽色明显比春天黯淡。","why":"because the old feathers drop out and new ones grow in, the word comes to describe a temporary state of the coat and not just its existence.","whyCN":"旧羽脱落、新羽长出，于是这个词也用来描述羽衣的阶段性状态，而不只是它存在与否。"},{"no":"03","title":"Breeding Plumage","titleCN":"繁殖羽；婚羽","definition":"the brighter, often more elaborate feathers that many birds grow before the breeding season","definitionCN":"许多鸟在繁殖季前长出的更鲜亮、往往更繁复的羽毛","example":"The male godwit arrives on the marsh in rusty breeding plumage.","exampleCN":"雄性的塍鹬披着锈红色的繁殖羽来到沼泽。","why":"the coat itself becomes a seasonal signal, so plumage can stand for the breeding dress that advertises readiness to mate.","whyCN":"羽衣本身成了季节信号，因此 plumage 可以指那身宣告繁殖状态的婚羽。"},{"no":"04","title":"Juvenile or Downy Plumage","titleCN":"幼羽；绒羽","definition":"the soft, often streaky feathers of a young bird before it acquires adult colours","definitionCN":"幼鸟在获得成鸟羽色之前那身柔软、常带条纹的羽毛","example":"Its juvenile plumage was streaked brown, hiding it among the reeds.","exampleCN":"它的幼鸟羽衣带褐色条纹，使它隐身在芦苇之间。","why":"age is one of the strongest dividers of plumage, and the young coat is so different that it earns its own name.","whyCN":"年龄是羽衣最强的分界之一，幼鸟那身羽毛差异极大，因此有了自己的名称。"},{"no":"05","title":"A Field Mark for Identification","titleCN":"作为物种识别特征的羽色","definition":"the colour pattern of a bird's feathers used by observers to tell one species from another","definitionCN":"观鸟者用来区分物种的羽毛颜色图案","example":"The rufous belly and barred wings make its plumage unmistakable.","exampleCN":"红褐色的腹部与横斑的翅膀使它的羽色绝不会认错。","why":"in the field the coat is the first and often the only feature visible, so plumage becomes a diagnostic label.","whyCN":"在野外，羽衣是最先、往往也是唯一能看见的特征，于是 plumage 成了鉴别标签。"},{"no":"06","title":"Display Plumage","titleCN":"装饰性羽毛（孔雀等）","definition":"showy feathers evolved to be displayed in courtship or threat, such as a peacock's train","definitionCN":"为求偶或威吓而演化出的华丽羽毛，如孔雀的尾屏","example":"The peacock's plumage is a handicap in flight but an advantage in display.","exampleCN":"孔雀的羽衣在飞行时是累赘，在展示时却是优势。","why":"when feathers are grown beyond the needs of warmth and flight, the coat turns into an ornament, and the word follows that excess.","whyCN":"当羽毛的生长超出保暖与飞行的需要，羽衣就变成装饰，词义也随之转向这份多余。"},{"no":"07","title":"Worn Plumage","titleCN":"磨损的羽衣状态","definition":"the frayed, faded condition of a bird's feathers late in the season, before they are replaced","definitionCN":"季末、换羽之前羽毛磨损褪色的状态","example":"By August the adults showed worn plumage and ragged wingtips.","exampleCN":"到八月，成鸟已显出磨损的羽衣和参差的翼尖。","why":"the same collective noun also measures wear, because a coat that cannot be repaired until the moult records every month of use.","whyCN":"同一个集合名词也用来衡量磨损，因为这件外衣要等到换羽才能修补，会记录下每一个使用月份。"},{"no":"08","title":"Literary Finery","titleCN":"书面引申：华服、盛装","definition":"figurative and literary, a splendid outfit or array of decoration worn by a person or a scene","definitionCN":"书面与文学用法，指人或场景所披的华丽服饰与装饰","example":"The hall opened in full plumage, gold on every pillar.","exampleCN":"大厅盛装开启，每一根柱子都镀着金色。","why":"a bird's coat is its display, so the word transfers naturally to human finery put on for an occasion.","whyCN":"鸟的羽衣就是它的展示，这个词于是自然转到人为了场合而披上的华服。"}],"etymology":{"intro":{"en":"Plumage is Old French plume 'feather, down' plus the noun suffix -age, and plume itself comes from Latin pluma 'soft feather, down'. Dates are approximate.","cn":"plumage 是古法语 plume「羽毛、绒」加名词后缀 -age 构成，而 plume 又来自拉丁 pluma「软羽、绒毛」。年代均为约数。"},"items":[{"era":"LATIN PLUMA","en":"Pluma meant soft feather or down, the light covering rather than a stiff quill; the word named texture as much as the object.","cn":"pluma 指柔软的羽毛或绒毛，是轻软覆盖物而非硬羽管；这个词既指物件，也指质地。"},{"era":"OLD FRENCH PLUME","en":"Old French plume carried the Latin word into French with the same soft-feather sense, and also developed the meaning of a decorative plume.","cn":"古法语 plume 把拉丁词带入法语，保留了软羽义，并发展出「装饰用羽毛」的意思。"},{"era":"SUFFIX -AGE","en":"The suffix -age, from Latin -aticum, forms collective and abstract nouns, so plume plus -age means a body of plumes taken together.","cn":"后缀 -age 源自拉丁 -aticum，构成集合名词与抽象名词，因此 plume 加 -age 指「羽毛的整体」。"},{"era":"FRENCH PLUMAGE","en":"French plumage is recorded as a collective term for a bird's feathers; English borrowed it in the sixteenth century.","cn":"法语 plumage 有记录地用作鸟羽的集合称谓；英语于 16 世纪借入。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the deeper origin of Latin pluma is not settled, and its link to Greek pteron is a hypothesis rather than a demonstrated derivation.","cn":"来源不确定：拉丁 pluma 的更早来源尚无定论，它与希腊 pteron 的联系只是假说，并非已证成的派生。"}]},"similar":{"note":{"en":"Group one holds words that look like plumage but belong to other roots; group two holds the real words for bird covering and for body coats.","cn":"第一组是外形近似而属别的词根的词；第二组是真正指鸟类覆盖物与体表外衣的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"plum","ipa":"/plʌm/","tag":"different root","definition":"The fruit, from Latin prunum and Greek proumnon; the shared plum- shape is chance, since plumage rests on pluma, not prunum.","definitionCN":"李子，来自拉丁 prunum 与希腊 proumnon；相同的 plum- 外形纯属巧合，因为 plumage 的词根是 pluma 而非 prunum。"},{"word":"plumber","ipa":"/ˈplʌmə/","tag":"different root","definition":"A worker in pipes, from Latin plumbum 'lead'; the look is close but the metal has nothing to do with feathers.","definitionCN":"水管工，来自拉丁 plumbum「铅」；外形接近，但这种金属与羽毛无关。"},{"word":"plummet","ipa":"/ˈplʌmɪt/","tag":"different root","definition":"A weighted line for measuring depth, also from plumbum; it shares the letters but not the root.","definitionCN":"测深的铅锤，同样来自 plumbum；共享字母而不共享词根。"},{"word":"plump","ipa":"/plʌmp/","tag":"different root","definition":"Round and full in build; its origin is not securely traced, and it is unrelated to Latin pluma.","definitionCN":"体形圆胖的；其来源未能确考，与拉丁 pluma 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"feather","ipa":"/ˈfeðə/","tag":"countable base word","definition":"One plume, or the coat in general; countable where plumage is collective, and used far more widely outside ornithology.","definitionCN":"一根羽毛，或泛指羽衣；可数，而 plumage 为集合名词，且 feather 在鸟类学之外用法远更广。"},{"word":"down","ipa":"/daʊn/","tag":"soft underlayer","definition":"The fine fluffy feathers under the contour feathers; it names one layer of the plumage, not the whole pattern.","definitionCN":"正羽之下细软的绒羽；它指羽衣的一层，而非整体图案。"},{"word":"quill","ipa":"/kwɪl/","tag":"single shaft","definition":"The stiff hollow shaft of a large feather; it picks out one part of the coat rather than the coat as a whole.","definitionCN":"大羽坚硬中空的羽轴；它取羽衣的一个部件，而非整件羽衣。"},{"word":"coat","ipa":"/kəʊt/","tag":"general animal covering","definition":"The fur or hair covering a mammal, or any outer layer; broader than plumage, which is strictly avian.","definitionCN":"哺乳动物的毛皮或任何外层；比 plumage 宽，后者严格限于鸟类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the French suffix that makes a collective noun, the real birding phrases, and the real feather family.","cn":"正常联想：把词变成集合名词的法语后缀、真实的观鸟搭配，以及真实的羽毛词族。"},"normal":[{"en":"Plume plus -age: an -age noun gathers things into one mass, as leafage gathers leaves.","cn":"plume 加 -age：带 -age 的名词把事物聚成一体，正如表示「叶丛」的词由叶加同一后缀聚成一体。"},{"en":"The word never takes a plural in ordinary use, because a bird has one coat, not many plumage.","cn":"这个词在日常用法中没有复数，因为一只鸟只有一件羽衣，而不是许多件。"},{"en":"Birding phrases sort the senses: breeding plumage, winter plumage, juvenile plumage, worn plumage.","cn":"观鸟搭配把义项分门别类：繁殖羽、冬羽、幼羽、磨损羽衣。"},{"en":"Colour is the point: plumage is what a field guide paints and what a mate or a rival reads.","cn":"重点在颜色：plumage 是图鉴上画出的东西，也是配偶或对手读出的信息。"},{"en":"The family runs plume, plumaged, plumy, plumose, plumule.","cn":"同族词包括 plume、plumaged、plumy、plumose、plumule。"}],"abstract":[{"en":"Picture a bird as a person wearing one tailored coat whose pattern changes with the season.","cn":"把鸟想象成一个穿着同一件定制外衣的人，只是花纹随季节更换。"},{"en":"Picture a peacock's train as a coat grown far beyond what warmth requires.","cn":"把孔雀尾屏想象成一件远远超出保暖所需而长出的外衣。"},{"en":"Picture a hall dressed in gold for one night, then stripped bare the next morning.","cn":"想象一座大厅为了一夜披上金装，次日清晨又被拆得精光。"}]},"examples":[{"en":"Museum drawers hold hundreds of study skins, each labelled with its plumage and collection date.","cn":"博物馆的抽屉里存放着数百张研究用鸟皮标本，每一张都标注羽色与采集日期。"},{"en":"Young birds often keep their dull plumage until their first full moult.","cn":"幼鸟往往保留暗淡的羽衣，直到第一次完整换羽。"},{"en":"In the old portrait the queen appears in gorgeous plumage, ermine at her throat.","cn":"在那幅旧肖像里，女王身着华服，喉间围着貂皮。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「普卢米奇」——孔雀一开屏，满身羽衣美得出奇","word":"plumage"},"root":"古法语 plume「羽毛、绒」+ 名词后缀 -age（源自拉丁 -aticum，构成集合名词）；plume 来自拉丁 pluma「软羽、绒毛」。pluma 的更早来源不确定，与希腊 pteron「翼」的联系属假说而非定论。英语 plumage 于 16 世纪借入，专指鸟的整身羽毛及其羽色。","sensesIntro":{"en":"The eight senses of plumage all view one coat from a different angle: as a whole, as a season, as breeding dress, as youth, as identity, as display, as wear, and finally as human finery.","cn":"plumage 的八个义项都是从不同角度看待同一件羽衣：作为整体、作为季节、作为婚装、作为幼年、作为身份、作为展示、作为磨损，最后作为人的华服。"},"semanticMap":{"core":{"en":"CORE IMAGE: one bird wrapped in a single coat of overlapping plumes, its pattern read as colour.","cn":"核心意象：一只鸟裹在一件由重叠羽片拼成的外衣里，花纹被读成颜色。"},"chain":["COLLECTIVE PLUMES","MOULT AND RENEW","BREEDING DRESS","JUVENILE DOWN","SPECIES SIGNATURE","LITERARY FINERY"],"branches":[{"senses":"01 · 02","en":"COAT AND STATE: the whole covering, and the condition it happens to be in.","cn":"外衣与状态：整件覆盖物，以及它当下所处的状况。"},{"senses":"03 · 04","en":"SEASON AND AGE: the coat changes for mating and changes again with youth.","cn":"季节与年龄：羽衣为繁殖而换，也因年幼而不同。"},{"senses":"05","en":"IDENTITY: the pattern is read as the name of a species.","cn":"身份：花纹被读成一个物种的名字。"},{"senses":"06","en":"DISPLAY: feathers grown beyond need become ornament.","cn":"展示：超出需要的羽毛成为装饰。"},{"senses":"07 · 08","en":"WEAR AND TRANSFER: a coat can fray with use, and human dress borrows the image.","cn":"磨损与转移：外衣会因使用而残破，人的衣装也借用了这个意象。"}]},"affixes":{"intro":{"en":"Plumage is a French-built collective: a Latin-derived noun stem plus a productive suffix, which is why it behaves as a mass noun.","cn":"plumage 是法语构成的集合名词：拉丁来源的词干加一个能产后缀，这也是它作不可数名词的原因。"},"latinIntro":{"en":"Latin pluma gives French plume; the suffix -age continues Latin -aticum. Plumosus and plumula show the same stem inside Latin itself.","cn":"拉丁 pluma 产生法语 plume；后缀 -age 延续拉丁 -aticum。plumosus 与 plumula 说明同一词干在拉丁语内部已有派生。"},"items":[{"word":"plume","structure":"plume (Old French noun, from Latin pluma)","meaning":"feather; down","meaningCN":"羽毛；绒毛","example":"The stem names the soft feather itself.","exampleCN":"这个词干指柔软的羽毛本身。"},{"word":"-age","structure":"-age (French noun suffix, from Latin -aticum)","meaning":"collective body, action or state","meaningCN":"集合体；动作或状态","example":"The suffix turns a single plume into a whole body of plumes.","exampleCN":"这个后缀把一根羽毛变成羽毛的整体。"},{"word":"plumage","structure":"plume + -age","meaning":"the whole feather covering of a bird","meaningCN":"鸟的整身羽毛","example":"Plumage is the collective counterpart of feather.","exampleCN":"plumage 是 feather 的集合对应词。"},{"word":"plumaged","structure":"plumage + -ed","meaning":"having plumage of a stated kind","meaningCN":"具有某种羽衣的","example":"The bright-plumaged male was easy to follow.","exampleCN":"羽色鲜亮的雄鸟很容易跟踪。"},{"word":"plumy","structure":"plume + -y","meaning":"feather-like, covered with plumes","meaningCN":"羽毛状的；覆有羽毛的","example":"The plume of smoke had a plumy edge.","exampleCN":"那道烟柱边缘如羽毛般松散。"},{"word":"plumose","structure":"pluma + -osus (Latin adjective suffix)","meaning":"feathery, bearing fine branches","meaningCN":"羽状的；长有细密分枝的","example":"The antennae are plumose in the male mosquito.","exampleCN":"雄蚊的触角呈羽状。"},{"word":"plumule","structure":"pluma + -ula (Latin diminutive)","meaning":"a tiny feather, or the embryonic shoot","meaningCN":"小绒羽；胚芽","example":"Each plumule will open into a first leaf.","exampleCN":"每一个胚芽都会展开成第一片叶。"},{"word":"pluma","structure":"pluma, plumae (Latin noun, first declension)","meaning":"soft feather, down","meaningCN":"软羽；绒毛","example":"Latin pluma is the stem behind the whole French family.","exampleCN":"拉丁 pluma 是整个法语词族背后的词干。"}],"latinEntries":[{"word":"pluma","structure":"pluma, plumae (f., first declension)","meaning":"soft feather, down","meaningCN":"软羽；绒毛"},{"word":"plumosus","structure":"plumosus, plumosa, plumosum (adjective, first and second declension)","meaning":"feathered, feathery","meaningCN":"有羽毛的；羽状的"},{"word":"plumula","structure":"plumula, plumulae (f., first declension, diminutive of pluma)","meaning":"a small soft feather","meaningCN":"小绒羽"}]}},{"word":"beak","ipa_uk":"/biːk/","ipa_us":"/biːk/","definition_zh":"鸟喙（上下颌与角质鞘）；钩状喙；喙状突起与器皿尖嘴；古船尖锐的船首；鼻子（英式俚语）；法官或校长（英式俚语）","definition_en":"the horny projecting jaws of a bird, and by extension any sharp projecting point, a ship's prow, or a slang term for a nose, a judge or a headmaster","core_image":"一张向前伸出的硬质尖嘴，上下两片扣合，像一把天生的钳子","scene":"野生动物救助站的桌上，一只受伤的红隼侧躺着，弯钩状的嘴尖包着纱布。 The falcon's beak is curved like a hook, built for tearing rather than for pecking seeds.","sceneCN":"这里 beak 是「钩状喙」（第 2 个义项：猛禽弯曲如钩的喙）；句意为这只隼的喙弯得像钩子，天生用于撕扯而非啄食种子。","pos":[{"tag":"n.","zh":"鸟喙；喙状物；尖嘴（可数，复数 beaks）"}],"collocations":[{"phrase":"hooked beak","zh":"钩状喙"},{"phrase":"sharp beak","zh":"尖喙"},{"phrase":"upper beak","zh":"上喙"},{"phrase":"beak trimming","zh":"喙部修整（养殖中防止啄伤）"},{"phrase":"beak-shaped","zh":"喙状的"},{"phrase":"beak and claw","zh":"喙与爪（猛禽的武器）"}],"forms":[{"label":"复数","form":"beaks"},{"label":"形容词（有喙的）","form":"beaked"},{"label":"形容词（喙状的）","form":"beaky"},{"label":"形容词（无喙的）","form":"beakless"}],"derivatives":[{"word":"beaked","pos":"adj.","zh":"有喙的；具喙状突起的"},{"word":"beaky","pos":"adj.","zh":"喙状的；鼻子高尖的"},{"word":"beakless","pos":"adj.","zh":"无喙的"},{"word":"beakhead","pos":"n.","zh":"船首喙状雕饰（古船建筑用语）"}],"senses":[{"no":"01","title":"The Horny Jaws of a Bird","titleCN":"鸟喙（上下颌及角质鞘）","definition":"the projecting upper and lower jaws of a bird, covered by a hard keratinous sheath and used for eating, grooming and carrying","definitionCN":"鸟向前突出的上下颌，外覆坚硬的角质鞘，用于取食、理羽与搬运","example":"The finch uses its short beak to crack seeds one by one.","exampleCN":"这只雀用短喙把种子一颗颗啄开。","why":"beak is first of all the anatomical tool itself: two jaws wrapped in horn, projecting from the face.","whyCN":"beak 首先指解剖上的工具本身：两片颌骨包着角质，从面部向前伸出。"},{"no":"02","title":"The Hooked Beak of a Raptor","titleCN":"钩状喙；猛禽喙","definition":"a beak whose upper half curves down over the lower, as in hawks, falcons and owls, adapted for tearing flesh","definitionCN":"上喙向下弯曲盖过下喙的喙型，见于鹰、隼与猫头鹰，适于撕肉","example":"The hawk's beak is short and hooked, made for holding a carcass.","exampleCN":"鹰的喙短而带钩，适于固定猎物尸体。","why":"a beak gains its shape from its diet, so the curved raptor form becomes a named type rather than just a bird part.","whyCN":"喙的形状由食性决定，因此猛禽的弯钩形成为一种被命名的类型，而不只是鸟身上的一个部件。"},{"no":"03","title":"British Slang for the Nose","titleCN":"英式俚语：鼻子","definition":"informal British, a person's nose, especially a large or prominent one","definitionCN":"英式非正式用语，指人的鼻子，尤指大而突出的鼻子","example":"He stuck his beak through the doorway and asked if we were ready.","exampleCN":"他把鼻子探进门框，问我们准备好了没有。","why":"a nose sticks out from the face and points forward exactly as a beak does, so the bird part supplies a joking human name.","whyCN":"鼻子从脸上突出、朝前指，形状正如鸟喙，于是鸟的部件成了人的戏称。"},{"no":"04","title":"Slang for a Judge","titleCN":"英式俚语：法官；治安法官","definition":"old British slang, a magistrate or judge, from the beak-like solemnity and sharpness of the bench","definitionCN":"旧时英式俚语，指治安法官或法官，取法官席上那种如喙般严肃尖利的形象","example":"The old beak fined him two shillings and sent him home.","exampleCN":"那位老法官罚了他两先令，就让他回家了。","why":"the transferred sense fastens on authority and sharpness: a judge looks down, beaked and severe, and the slang does the rest.","whyCN":"这一转义抓住了权威与尖利：法官居高临下、如喙般严厉，俚语便把两者接上。"},{"no":"05","title":"School Slang for the Headmaster","titleCN":"学生俚语：校长","definition":"dated British school slang, the headmaster or head teacher of a school","definitionCN":"旧时英国学校俚语，指学校的校长或教务负责人","example":"The beak caught them smoking behind the gym and wrote to their parents.","exampleCN":"校长抓住他们在体育馆后面吸烟，并写信给他们的父母。","why":"it is the same authority transfer as the judge: the one who watches and punishes gets the sharp, watching bird name.","whyCN":"这与指法官的转义同出一路：负责监视与惩罚的人，被安上那种尖利、警觉的鸟名。"},{"no":"06","title":"The Prow of an Old Ship","titleCN":"古船尖锐的船首","definition":"the sharp projecting prow or forward point of an old warship, often strengthened with a beak-like ram","definitionCN":"旧式战船向前突出的尖船首，常装有喙状撞角加固","example":"The galley lowered its beak into the enemy's oars and splintered them.","exampleCN":"那艘桨帆船把尖船首压向敌船的桨，将其撞碎。","why":"a ship's front end cuts the water like a bird's beak cuts the air, and the nautical name records that likeness.","whyCN":"船首破水正如鸟喙破空，航海用语把这一相似记录下来。"},{"no":"07","title":"The Spout of a Vessel","titleCN":"壶嘴；器皿的尖嘴","definition":"the projecting lip or spout of a jug, teapot or similar vessel, from which liquid is poured","definitionCN":"壶、茶壶等器皿向外突出的嘴状口沿，液体由此倒出","example":"The beak of the old teapot had chipped, so the pour wandered.","exampleCN":"旧茶壶的壶嘴崩了口，倒出的水流便歪斜。","why":"the spout is the vessel's own small projecting jaw, and English reuses the bird word for that shape.","whyCN":"壶嘴就是器皿自己小小的突出之颌，英语便把这个鸟的词挪用来指这种形状。"},{"no":"08","title":"Any Beak-Shaped Projection","titleCN":"任何喙状突起（机械或解剖）","definition":"a pointed projecting part on a machine, tool or anatomical structure, named for its resemblance to a beak","definitionCN":"机器、工具或解剖结构上因形似鸟喙而得名的尖状突出部分","example":"A small steel beak on the drill grips the pipe before the cut begins.","exampleCN":"钻头上的一个小钢喙在切割开始前咬住管壁。","why":"once beak means any forward-pointing hard tip, engineers and anatomists can name their own projections with the same shape word.","whyCN":"一旦 beak 指任何前伸的硬尖端，工程师与解剖学家就能用同一个形状词来命名各自的突出物。"}],"etymology":{"intro":{"en":"Beak comes into English from Old French bec, which continues Latin beccus; beccus itself is generally thought to be a borrowing from Gaulish. Dates are approximate.","cn":"beak 经古法语 bec 进入英语，bec 又延续拉丁 beccus；beccus 本身一般认为是高卢语借词。年代均为约数。"},"items":[{"era":"GAULISH ORIGIN","en":"Beccus is generally considered a Gaulish loan into Latin, since the bird-part word is not native Latin vocabulary; the Gaulish source form is not attested.","cn":"beccus 一般被认为是拉丁语从高卢语借入的词，因为这个指鸟嘴的词并非拉丁本土词汇；高卢语的源词形式没有书证。"},{"era":"LATIN BECCVS","en":"Latin beccus meant a bird's beak, a rare word beside the usual rostrum; its spelling with double c is the form recorded.","cn":"拉丁 beccus 指鸟喙，是常见词 rostrum 之外的罕见词；带双 c 的拼写是有记录的形式。"},{"era":"OLD FRENCH BEC","en":"Old French bec carried the word into everyday French for a bird's bill and later for a person's nose.","cn":"古法语 bec 把这个词带入日常法语，先指鸟喙，后来也指人的鼻子。"},{"era":"ENGLISH BEAK","en":"English beak appears in the fourteenth century, first of birds and later of ships, vessels and noses.","cn":"英语 beak 于 14 世纪出现，先指鸟，后及船只、器皿与鼻子。"},{"era":"PEAK IS UNRELATED","en":"Peak, the pointed top of a hill, is not related to beak: it has a separate and itself uncertain history, and the two words must not be merged.","cn":"peak 指山峰的尖顶，与 beak 无关：它有独立且同样不确定的历史，两个词不可合并。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the Gaulish origin of beccus is a widely held view rather than a documented derivation, and the first date of the slang senses is not firmly fixed.","cn":"来源不确定：beccus 源自高卢语是广泛持有的看法，而非有文献证成的派生；俚语义最早出现的年代也无定论。"}]},"similar":{"note":{"en":"Group one holds words that look like beak but come from other roots, including the peak that is often wrongly linked; group two holds the real words for the same projecting mouth.","cn":"第一组是外形近似而词根不同的词，其中包括常被误认为同源的 peak；第二组是真正指同一类突出之口的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"peak","ipa":"/piːk/","tag":"different root, often confused","definition":"The pointed top of a hill or a maximum point; it is not related to beak and does not come from Latin beccus.","definitionCN":"山峰的尖顶或最高点；与 beak 无关，也不来自拉丁 beccus。"},{"word":"beaker","ipa":"/ˈbiːkə/","tag":"different root","definition":"A tall laboratory cup, from Medieval Latin bicarium, probably from Greek bikos; the -eaker shape is accidental.","definitionCN":"实验室用的高杯，来自中世纪拉丁 bicarium，或更早来自希腊 bikos；-eaker 的外形属巧合。"},{"word":"beck","ipa":"/bek/","tag":"different root","definition":"A small stream, from Old Norse bekkr; a separate Northern word with no link to the bird's bill.","definitionCN":"小溪，来自古诺斯语 bekkr；这是独立的北方方言词，与鸟喙毫无联系。"},{"word":"bead","ipa":"/biːd/","tag":"different root","definition":"A small pierced ornament, from Old English gebed 'prayer'; it shares the opening letters only.","definitionCN":"穿孔的小饰珠，来自古英语 gebed「祈祷」；只共享开头的字母。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bill","ipa":"/bɪl/","tag":"everyday synonym","definition":"The everyday word for a bird's beak, from Old English bile; softer and less technical than beak, and common in compound names.","definitionCN":"鸟喙的日常说法，来自古英语 bile；比 beak 柔和、少技术味，常见于复合鸟名。"},{"word":"snout","ipa":"/snaʊt/","tag":"mammal counterpart","definition":"The projecting nose and mouth of an animal such as a pig or dog; it is the mammal's version of the same forward tool.","definitionCN":"猪、狗等动物突出的口鼻部；是哺乳动物版的同类前伸工具。"},{"word":"muzzle","ipa":"/ˈmʌzəl/","tag":"animal face part","definition":"The front of an animal's head including nose and jaws, or a guard over it; broader and blunter than beak.","definitionCN":"动物头部的前端，含鼻与颌，或指套在其上的护具；比 beak 更宽、更钝。"},{"word":"mandible","ipa":"/ˈmændɪbl/","tag":"technical anatomy","definition":"The lower jaw of a vertebrate or either jaw of a bird; the clinical term for the bony part that the beak sheathes.","definitionCN":"脊椎动物的下颌，或鸟的任一颌；是喙所包裹的骨质部分的临床术语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real anatomy of a bill, the real transferred shapes, and the real derivatives built on beak.","cn":"正常联想：鸟喙的真实解剖、真实的形状转移，以及由 beak 构成的真实派生词。"},"normal":[{"en":"A beak is two jaws in a horn sheath, projecting forward like a built-in pair of pliers.","cn":"鸟喙是包在角质鞘里的两片颌，像自带的钳子向前伸出。"},{"en":"Shape follows diet: hooked for tearing, straight and stout for cracking, long and thin for probing mud.","cn":"形状随食性：钩形用于撕扯，粗直用于破壳，细长用于探泥。"},{"en":"The same shape word moves outward: ship's prow, teapot spout, drill tip.","cn":"同一个形状词向外延伸：船首、壶嘴、钻头尖。"},{"en":"The slang senses all turn on authority or prominence: nose, judge, headmaster.","cn":"俚语义都围绕「突出」或「权威」：鼻子、法官、校长。"},{"en":"The family runs beaked, beaky, beakless, beakhead.","cn":"同族词包括 beaked、beaky、beakless、beakhead。"}],"abstract":[{"en":"Picture a hard pointed tool that never needs to be picked up, because it grows on the face.","cn":"想象一件永不必拿起的小尖工具，因为它长在脸上。"},{"en":"Picture a judge on a high bench, chin thrust forward like a beak over the court.","cn":"想象法官高坐堂上，下巴前伸如喙，俯瞰整个法庭。"},{"en":"Picture a teapot pouring through its own small hard jaw.","cn":"想象茶壶通过自己那只小小的硬颌倒出茶水。"}]},"examples":[{"en":"A bird's beak never stops growing, so it is worn down by use instead of being replaced.","cn":"鸟喙从不停生长，因此靠使用磨短，而不是被替换。"},{"en":"The heron stood motionless, beak poised above the shallow water.","cn":"苍鹭一动不动地站着，喙悬在浅水上方。"},{"en":"In the old dockyard, the ship's beak was carved into a snarling animal head.","cn":"在旧船厂里，那艘船的尖船首被雕成一只咆哮的兽头。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「必克」——鸟喙一出，必定克敌；尖嘴既是餐具也是武器","word":"beak"},"root":"古法语 bec「鸟喙、鼻」，来自拉丁 beccus；beccus 一般认为是高卢语借词，属来源不确定，高卢语源词形式无书证，不得与 peak「山峰」混为同源。英语 beak 于 14 世纪出现，由鸟喙扩展至船首、壶嘴、鼻子与法官、校长等俚语义。","sensesIntro":{"en":"The eight senses of beak all project from one shape: a hard pointed jaw in front of a face, first on a bird, then on ships, vessels, noses and machines, and finally on men of authority.","cn":"beak 的八个义项都从同一个形状伸出：脸前一片硬而尖的颌，先在鸟身上，再移到船、器皿、鼻子与机器上，最后落到掌权的人身上。"},"semanticMap":{"core":{"en":"CORE IMAGE: two horny jaws meeting at a point, thrust forward from the face.","cn":"核心意象：两片角质颌在一点扣合，从面部向前探出。"},"chain":["HORNY BILL","HOOKED RAPTOR FORM","PROJECTING SHAPE","SHIP PROW","VESSEL SPOUT","AUTHORITY NICKNAME"],"branches":[{"senses":"01 · 02","en":"ANATOMY: the general bill, and the hooked variant shaped by a tearing diet.","cn":"解剖：一般的鸟喙，以及由撕食习性塑成的钩形变体。"},{"senses":"03 · 05","en":"PROMINENCE: a nose sticks out, and a headmaster watches from the front.","cn":"突出：鼻子向外伸，校长则在前方监视。"},{"senses":"04","en":"AUTHORITY: the judge on the bench gains the sharp, watching name.","cn":"权威：法官高坐堂上，得到这个尖利而警觉的称呼。"},{"senses":"06 · 07","en":"CRAFTED POINTS: ship prows and teapot spouts copy the same forward jaw.","cn":"人造尖端：船首与壶嘴复制同一个前伸之颌。"},{"senses":"08","en":"GENERIC PROJECTION: any hard pointed part may be called a beak.","cn":"泛指突起：任何硬而尖的部件都可称作喙。"}]},"affixes":{"intro":{"en":"Beak is a borrowed monosyllable with almost no derivational machinery of its own; English builds a small family with -ed, -y and -less, plus one nautical compound.","cn":"beak 是一个借入的单音节词，自身几乎没有派生机制；英语用 -ed、-y 与 -less 加一个航海复合词，构成一个小词族。"},"latinIntro":{"en":"Latin beccus is a rare loanword, not a productive root; it gave French bec and English beak, but no Latin verb or suffix family.","cn":"拉丁 beccus 是罕见的借词，不是能产的词根；它产生法语 bec 与英语 beak，却没有拉丁动词或后缀词族。"},"items":[{"word":"bec","structure":"bec (Old French noun, from Latin beccus)","meaning":"bird's bill; nose","meaningCN":"鸟喙；鼻子","example":"French bec already had both the bird and the nose sense.","exampleCN":"法语 bec 已兼有鸟喙与鼻子两义。"},{"word":"beccus","structure":"beccus, becci (Latin noun, second declension, rare)","meaning":"beak","meaningCN":"鸟喙","example":"Beccus is the recorded Latin form behind the French word.","exampleCN":"beccus 是法语词背后有记录的拉丁形式。"},{"word":"beak","structure":"beak (English noun, from Old French bec)","meaning":"bird's bill; any pointed projection","meaningCN":"鸟喙；任何尖状突出物","example":"The English word widened from the bill to ships and vessels.","exampleCN":"英语这个词从鸟喙扩展到船只与器皿。"},{"word":"-ed","structure":"-ed (English participial suffix)","meaning":"having, provided with","meaningCN":"具有……的；配备……的","example":"Beaked means provided with a beak.","exampleCN":"beaked 意为长有喙的。"},{"word":"beaked","structure":"beak + -ed","meaning":"having a beak of a stated kind","meaningCN":"具有某种喙的","example":"The long-beaked wader probes deep mud.","exampleCN":"长喙的涉禽在深泥中探食。"},{"word":"-y","structure":"-y (English adjective suffix)","meaning":"like, characterized by","meaningCN":"像……的；具有……特征的","example":"The suffix turns the shape into a descriptive adjective.","exampleCN":"这个后缀把形状变成描述性形容词。"},{"word":"beaky","structure":"beak + -y","meaning":"beak-like, or having a prominent nose","meaningCN":"喙状的；鼻子高尖的","example":"His beaky profile made him easy to draw.","exampleCN":"他高尖的侧脸很好画。"},{"word":"beakless","structure":"beak + -less","meaning":"having no beak","meaningCN":"无喙的","example":"A beakless bird could not feed itself.","exampleCN":"一只无喙的鸟无法自己进食。"},{"word":"beakhead","structure":"beak + head","meaning":"a carved beak-like ornament at a ship's prow","meaningCN":"船首的喙状雕饰","example":"The beakhead was both decoration and a boarding platform.","exampleCN":"船首喙饰既是装饰，也是登船平台。"}],"latinEntries":[{"word":"beccus","structure":"beccus, becci (m., second declension, rare)","meaning":"beak","meaningCN":"鸟喙"}]}},{"word":"beaked","ipa_uk":"/biːkt/","ipa_us":"/biːkt/","definition_zh":"有喙的；尖端弯如鸟喙的；船首作喙形的；果实带喙状残留的；壶嘴作喙形的","definition_en":"having a beak, or ending in a hard point shaped like one, as said of birds, fruits, ships and vessels","core_image":"一只鸟的头部侧影：角质喙从额前伸出，向前收成一个坚硬的尖，凡照此形者皆可称之","scene":"标本室里，管理员掀开一层防尘布，露出一排鸟头骨标本。 Each beaked skull in the drawer belonged to a wading bird.","sceneCN":"这里 beaked 是「有喙的」（第 1 个义项：生有鸟喙，喙部形态可辨）；句意：抽屉里每一具带喙的头骨都属于一种涉禽。","pos":[{"tag":"adj.","zh":"有喙的；喙状的；具喙形部件的（多用于复合形容词与学术描述）"}],"collocations":[{"phrase":"beaked whale","zh":"剑吻鲸；喙鲸（喙鲸科）"},{"phrase":"beaked hazelnut","zh":"喙状榛"},{"phrase":"beaked fruit","zh":"具喙果实"},{"phrase":"beaked ship","zh":"尖嘴船（船首作喙形）"},{"phrase":"beaked mask","zh":"鸟嘴面具"},{"phrase":"beaked spout","zh":"喙形壶嘴"},{"phrase":"long-beaked","zh":"长喙的"}],"forms":[{"label":"原级","form":"beaked"},{"label":"比较级","form":"more beaked"},{"label":"最高级","form":"most beaked"},{"label":"同根名词","form":"beak"},{"label":"同根形容词（口语）","form":"beaky（喙状的；鹰钩鼻的）"},{"label":"否定派生形容词","form":"beakless（无喙的）"}],"derivatives":[{"word":"beak","pos":"n.","zh":"喙；鸟嘴"},{"word":"beaky","pos":"adj.","zh":"喙状的；鼻子鹰钩的"},{"word":"beakless","pos":"adj.","zh":"无喙的"},{"word":"beak-like","pos":"adj.","zh":"喙状的；形似鸟喙的"},{"word":"debeak","pos":"v.","zh":"去喙（家禽处理）"}],"senses":[{"no":"01","title":"Having a Beak","titleCN":"有喙的（鸟类）","definition":"having a beak, especially a beak of a stated kind","definitionCN":"长有鸟喙，尤指喙形可辨的","example":"The beaked bird pried open the seed with a single twist.","exampleCN":"那只带喙的鸟一拧就把种子撬开了。","why":"the suffix -ed turns a noun into a possessor, so beaked simply means equipped with the beak that the noun names.","whyCN":"后缀 -ed 把名词变成「具有者」，因此 beaked 就是「带着名词所指的那个喙」。"},{"no":"02","title":"Shaped Like a Beak","titleCN":"喙状尖端的","definition":"ending in a narrow, often down-curved point that resembles a beak","definitionCN":"末端收成狭窄、常向下弯的尖，形似鸟喙","example":"The handle ends in a beaked hook that catches the rope.","exampleCN":"把手末端是一个喙状的钩，能勾住绳索。","why":"once the beak is detached from the bird it becomes a shape, and any tip that curves to a point can borrow it.","whyCN":"喙一旦脱离鸟的身体就变成一个形状，任何弯成尖的末端都可以借用它。"},{"no":"03","title":"With a Beak-Shaped Prow","titleCN":"尖嘴船首的","definition":"having a prow built or carved to a sharp beak-like point, as old galleys were","definitionCN":"船首建成或雕成尖锐的喙形，如古代桨帆船","example":"The beaked prow of the old galley still shows above the sand.","exampleCN":"旧桨帆船的尖嘴船首仍露在沙面之上。","why":"a warship's prow was built as a beak, and the whole vessel was named by that single forward feature.","whyCN":"战船的船首被做成喙形，整条船便由这一个向前的特征得名。"},{"no":"04","title":"Bearing a Beaked Fruit","titleCN":"具喙果实的（植物学）","definition":"botanical, of a fruit or nut that keeps a hard, beak-like point at its tip","definitionCN":"植物学术语，指果实或坚果顶端保留坚硬的喙状尖","example":"The beaked hazelnut hides its nut inside a long papery sheath.","exampleCN":"喙状榛把坚果藏在一层长长的纸质总苞里。","why":"botany keeps the bird's word for a hardened point left on a fruit, because the outline is the same.","whyCN":"植物学沿用了鸟的这个词，指果实上残留的硬尖，因为轮廓完全相同。"},{"no":"05","title":"Of the Beaked Whale Family","titleCN":"剑吻鲸类的（固定名称）","definition":"used in the fixed name of the whale family whose snout narrows to a beak-like rostrum","definitionCN":"用于喙鲸科的固定名称，这一类鲸的吻部收窄成喙状","example":"Beaked whales can hold their breath for more than an hour.","exampleCN":"喙鲸能屏住呼吸一个多小时。","why":"taxonomy fixes a common noun into a family label, and the whale is named for its narrow, beak-like snout.","whyCN":"分类学把一个普通名词固定为科名，这种鲸因狭窄如喙的吻部而得名。"},{"no":"06","title":"With a Beak-Formed Spout","titleCN":"喙形壶嘴的（器皿）","definition":"describing a jug or vessel whose spout projects and narrows like a beak","definitionCN":"指壶或器皿的嘴向前伸出、收窄如喙","example":"The potter shaped a beaked jug for pouring oil.","exampleCN":"陶工做了一把喙形嘴的壶用来倒油。","why":"a vessel pours through a narrow projecting mouth, and potters named that mouth after the bird's beak.","whyCN":"器皿经由一个向前伸出的窄口倒出液体，陶工便按鸟喙给这个口命名。"},{"no":"07","title":"Wearing the Beaked Mask","titleCN":"戴鸟嘴面具的","definition":"describing a figure wearing the long beak-shaped mask associated with plague doctors","definitionCN":"描述戴着与瘟疫医生相关的长喙状面具的形象","example":"The beaked physician in the woodcut carried a cane, not a scalpel.","exampleCN":"版画里那位戴鸟嘴面具的医生拿的是手杖，不是手术刀。","why":"the mask actually encloses a beak-shaped chamber for herbs, so the wearer is described by the object on his face.","whyCN":"面具内部本就是一个喙形药草腔，因此戴它的人被脸上那件器物来指称。"},{"no":"08","title":"A Beaked Evolutionary Form","titleCN":"喙部特化的演化形态","definition":"used in morphology for a variant whose beak is enlarged or specialised as an evolved trait","definitionCN":"形态学中描述喙部增大或特化、作为演化性状的变型","example":"The beaked morphotype appeared only after the lake lost its open water.","exampleCN":"喙部特化的形态型在湖泊失去开阔水域之后才出现。","why":"in morphology the beak is a trait that can appear or disappear, so beaked names a form rather than an individual.","whyCN":"在形态学中喙是一项可出现也可消失的性状，因此 beaked 命名的是一个形态，而非一只个体。"}],"etymology":{"intro":{"en":"Beaked is beak plus the adjectival -ed. Beak comes from Old French bec, from Latin beccus, a word generally taken as a Gaulish loan whose deeper source is uncertain. Dates are approximate.","cn":"beaked 是 beak 加形容词后缀 -ed。beak 来自古法语 bec，再上溯拉丁 beccus；beccus 一般认为是高卢语借词，更早来源不确定。年代均为约数。"},"items":[{"era":"LATIN BECCUS","en":"Latin beccus meant 'beak'; it is generally taken to be a Gaulish loanword, and its deeper origin is uncertain.","cn":"拉丁 beccus 意为「喙」；一般认为是高卢语借词，其更早来源不确定。"},{"era":"OLD FRENCH BEC","en":"Old French bec, recorded from the twelfth century, is the form English borrowed and the direct source of English beak.","cn":"古法语 bec 自 12 世纪有记录，是英语借入的形式，也是英语 beak 的直接来源。"},{"era":"MIDDLE ENGLISH BEK","en":"Middle English bek or bec appears in the thirteenth century, first in falconry and hunting descriptions.","cn":"中古英语 bek 或 bec 见于 13 世纪，最早出现在鹰猎与狩猎的描述中。"},{"era":"SUFFIX -ED","en":"The past participle ending -ed, from Old English -ed, was used adjectivally with the sense 'provided with', giving beaked 'having a beak'.","cn":"过去分词后缀 -ed 来自古英语 -ed，作形容词时表示「具有……的」，于是 beaked 即「长着喙的」。"},{"era":"NAMED COMPOUNDS","en":"Beaked whale and beaked hazelnut fixed the word in zoology and botany, where the beak is a diagnostic feature.","cn":"beaked whale 与 beaked hazelnut 把该词固定在动物学与植物学中，那里的「喙」是鉴别特征。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (beccus): the Gaulish loan is a common view rather than a proven fact; the first date of beaked as an adjective is approximate.","cn":"来源不确定（beccus）：高卢语借词是通行看法而非已证事实；beaked 作形容词的首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds words that resemble beaked in form but not in root; group two holds the anatomical words that overlap with it in meaning.","cn":"第一组是外形相近但词根不同的词；第二组是在含义上与之重叠的解剖学术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"peak","ipa":"/piːk/","tag":"not related","definition":"The pointed top of a mountain; its origin is uncertain and it is not connected with beak, despite the near-identical sound.","definitionCN":"山峰的尖顶；来源不确定，尽管读音几乎相同，与 beak 并无同源关系。"},{"word":"beaker","ipa":"/ˈbiːkə/","tag":"different root","definition":"A tall drinking cup; it comes through Medieval Latin bicarium from Greek bikos 'a vessel', not from Latin beccus.","definitionCN":"高杯；经中世纪拉丁 bicarium 上溯希腊 bikos「容器」，并非来自拉丁 beccus，属不同词根。"},{"word":"beck","ipa":"/bek/","tag":"not related","definition":"A northern English word for a small stream, from Old Norse bekkr; it shares spelling shape with beak but no ancestry.","definitionCN":"英格兰北部指小溪的词，来自古诺斯 bekkr；与 beak 只有拼写相近，没有共同来源。"},{"word":"beak","ipa":"/biːk/","tag":"same root, base noun","definition":"The noun that beaked is built on; the adjective adds only the idea of possession.","definitionCN":"beaked 所依附的名词；形容词只是在它之上加了「具有」的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rostrate","ipa":"/ˈrɒstreɪt/","tag":"technical synonym","definition":"The formal zoological and botanical adjective for 'having a beak', built on Latin rostrum 'beak'; beaked is its plainer English twin.","definitionCN":"动物学与植物学中「有喙的」正式形容词，建立在拉丁 rostrum「喙」之上；beaked 是它更朴素的英语对应词。"},{"word":"bill","ipa":"/bɪl/","tag":"bird's beak, narrower","definition":"The beak of a bird, especially a flat or soft one; it names the organ itself, while beaked describes something as possessing or resembling it.","definitionCN":"鸟的嘴，尤指扁平或柔软的喙；它命名器官本身，而 beaked 描述某物具有或形似该器官。"},{"word":"snout","ipa":"/snaʊt/","tag":"nose and jaw","definition":"The projecting nose and mouth of an animal; broader and fleshier than a beak, which is hard and keratinous.","definitionCN":"动物突出的鼻口部；比喙更宽、更有肉，而喙是坚硬角质的。"},{"word":"proboscis","ipa":"/prəˈbɒskɪs/","tag":"elongated feeding organ","definition":"A long tubular organ of the mouth, as in a butterfly or an elephant; it is flexible where a beak is rigid.","definitionCN":"口部细长的管状器官，如蝴蝶或大象的；它柔韧，而喙坚硬。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real zoological and botanical names, and real relatives.","cn":"正常联想：真实的构词成分、真实的动物学与植物学名称以及真实同族词。"},"normal":[{"en":"beak + -ed: a bird equipped with the one hard point it feeds with.","cn":"beak + -ed：一只鸟被配上它用来取食的那一个硬尖。"},{"en":"The noun travelled Old French bec to Latin beccus, and beccus is probably a Gaulish loan.","cn":"这个名词经古法语 bec 上溯拉丁 beccus，而 beccus 很可能是高卢语借词。"},{"en":"Fixed names carry the sense: beaked whale, beaked hazelnut, beaked mask.","cn":"固定名称承载词义：喙鲸、喙状榛、鸟嘴面具。"},{"en":"Keep it apart from peak, which looks close but has a different and uncertain history.","cn":"要与 peak 分开，后者外形相近，但来源不同且本身不确定。"},{"en":"The family runs beak, beaky, beakless, beak-like, beaked.","cn":"同族词包括 beak、beaky、beakless、beak-like、beaked。"}],"abstract":[{"en":"Picture a single hard point growing from a rounded head, then imagine it reappearing on a prow, a nut and a jug.","cn":"想象一个从圆钝头部长出的硬尖，再想象它依次出现在船首、坚果与壶上。"},{"en":"Picture a ship whose whole identity is one forward beak.","cn":"想象一条船，它的全部身份就是向前伸出的那一只喙。"},{"en":"Picture a masked figure whose face is a beak filled with herbs.","cn":"想象一个面具人，他的脸就是一只装满药草的喙。"}]},"examples":[{"en":"Ornithologists measure the beaked skull to separate the two species.","cn":"鸟类学家测量带喙的头骨以区分这两个物种。"},{"en":"A beaked figure stood at the door of the plague house.","cn":"一个戴鸟嘴面具的人站在疫病收容所门口。"},{"en":"Each beaked achene ends in a stiff point.","cn":"每一枚具喙瘦果都以一个硬尖收尾。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「beak（喙）+ ed」——头上带着一只尖喙 → 有喙的、喙状的","word":"beaked"},"root":"古法语 bec「喙」← 拉丁 beccus；beccus 一般认为是高卢语借词，更早来源不确定，与 peak 无同源关系。英语 beaked = beak + -ed（古英语 -ed，过去分词后缀作形容词）。","sensesIntro":{"en":"Eight senses of beaked all start from one shape: a hard point growing out of a rounded head, which then reappears on prows, fruits, spouts and masks.","cn":"beaked 的八个义项都从一个形状出发：圆钝头部伸出的硬尖，随后再现在船首、果实、壶嘴与面具上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hard pointed beak projecting from a rounded head.","cn":"核心意象：圆钝头部前端伸出的坚硬尖喙。"},"chain":["BEAK","POINTED TIP","SHIP PROW","FRUIT BEAK","MASKED FIGURE","SPECIALISED FORM"],"branches":[{"senses":"01 · 08","en":"BIRD BODY: possession of a beak, and the beak as an evolved trait.","cn":"鸟的身体：拥有喙，以及喙作为演化性状。"},{"senses":"02 · 06","en":"SHAPED END: any object ending in a beak-like point, including a vessel's spout.","cn":"成形的末端：任何收成喙状尖的物体，包括器皿的嘴。"},{"senses":"03","en":"SHIP: the prow itself takes the shape of a beak.","cn":"船：船首本身化作喙形。"},{"senses":"04","en":"PLANT: a fruit keeps a beak-like remnant at its tip.","cn":"植物：果实顶端保留喙状残留。"},{"senses":"05 · 07","en":"NAMED FIGURES: a whale family and the masked physician are both named by the beak.","cn":"被命名的形象：鲸类一科与蒙面医生都由喙得名。"}]},"affixes":{"intro":{"en":"Beaked can be read as two pieces: a borrowed noun for a bird's mouth, and an adjectival ending meaning 'provided with'.","cn":"beaked 可以拆成两段读：一个借来的「鸟嘴」名词，以及表示「具有」的形容词后缀。"},"latinIntro":{"en":"Latin beccus is the earliest recoverable form; it is usually explained as a Gaulish loan, so the trail stops there rather than at a Latin root.","cn":"拉丁 beccus 是今可追溯的最早形式；它通常被解释为高卢语借词，因此线索到此为止，而不是停在某个拉丁词根上。"},"items":[{"word":"beak","structure":"bec (Old French noun) → English beak","meaning":"the hard mouth parts of a bird","meaningCN":"鸟的角质嘴部","example":"The hawk cleaned its beak on the branch.","exampleCN":"鹰在树枝上清理自己的喙。"},{"word":"beccus","structure":"beccus (Latin noun, second declension, probably Gaulish loan)","meaning":"beak","meaningCN":"喙","example":"Beccus is the form behind French bec and English beak.","exampleCN":"beccus 是法语 bec 与英语 beak 背后的形式。"},{"word":"-ed","structure":"-ed (Old English past participle suffix used adjectivally)","meaning":"provided with, having","meaningCN":"具有……的","example":"Beaked means provided with a beak.","exampleCN":"beaked 意为长有喙的。"},{"word":"beaked","structure":"beak + -ed","meaning":"having or resembling a beak","meaningCN":"有喙的；喙状的","example":"The beaked bird is adapted to cracking shells.","exampleCN":"这种带喙的鸟适应了咬碎贝壳。"},{"word":"beaky","structure":"beak + -y","meaning":"resembling a beak; having a hooked nose","meaningCN":"喙状的；鹰钩鼻的","example":"He had a beaky profile in the photograph.","exampleCN":"照片里他的侧影呈鹰钩鼻状。"},{"word":"beakless","structure":"beak + -less (Old English -lēas 'lacking')","meaning":"without a beak","meaningCN":"无喙的","example":"The beakless chick must be fed by hand.","exampleCN":"无喙的雏鸟必须人工喂养。"},{"word":"beaked whale","structure":"beaked + whale (fixed taxonomic name)","meaning":"a whale of the family Ziphiidae","meaningCN":"喙鲸科的鲸","example":"Beaked whales produce clicks too high for human hearing.","exampleCN":"喙鲸发出的咔嗒声高到人耳听不见。"},{"word":"beaked hazelnut","structure":"beaked + hazelnut (fixed botanical name)","meaning":"a hazel whose nut ends in a beak-like point","meaningCN":"坚果端部呈喙状的榛","example":"Beaked hazelnut grows along the northern edge of the forest.","exampleCN":"喙状榛生长在森林北缘。"},{"word":"beaked mask","structure":"beaked + mask (compound term)","meaning":"the long beak-shaped mask of plague doctors","meaningCN":"瘟疫医生所戴的长喙状面具","example":"Museums still display a beaked mask stuffed with dried herbs.","exampleCN":"博物馆仍陈列着一只塞满干药草的鸟嘴面具。"}],"latinEntries":[{"word":"beccus","structure":"beccus, becci (m., second declension)","meaning":"beak, bird's bill","meaningCN":"喙；鸟嘴"}]}},{"word":"wing","ipa_uk":"/wɪŋ/","ipa_us":"/wɪŋ/","definition_zh":"翅膀；飞行（能力或行为）；建筑物的侧翼；政党或军团的派系与侧翼；舞台侧幕与英式挡泥板","definition_en":"a paired organ of flight in birds and insects, or a part that extends sideways from a main body, as of a building, an army or a party","core_image":"一只鸟在气流中展开双翼，翼尖划出弧线，把身体两侧向外延伸出去","scene":"医院主楼旁的老楼在火灾后重新翻修，走廊比原先长了一倍。 The east wing of the hospital was rebuilt after the fire.","sceneCN":"这里 wing 是「侧翼、耳房」（第 3 个义项：主建筑两侧向外延伸的部分）；句意：医院东侧翼楼在火灾后重建。","pos":[{"tag":"n.","zh":"翅膀；机翼；侧翼；派系；（英）挡泥板（可数，复数 wings）"},{"tag":"vi./vt.","zh":"飞；乘翼而行；给……装上翅膀；伤其翼；即兴应付（wing it）"}],"collocations":[{"phrase":"left wing","zh":"左翼；左派"},{"phrase":"right wing","zh":"右翼；右派"},{"phrase":"take wing","zh":"起飞；飞走"},{"phrase":"under one's wing","zh":"在某人的庇护与照管下"},{"phrase":"wing it","zh":"即兴应付；临场发挥"},{"phrase":"chicken wing","zh":"鸡翅"},{"phrase":"on the wing","zh":"在飞行中"}],"forms":[{"label":"原形","form":"wing"},{"label":"复数","form":"wings"},{"label":"第三人称单数","form":"wings"},{"label":"现在分词","form":"winging"},{"label":"过去式","form":"winged"},{"label":"过去分词","form":"winged"}],"derivatives":[{"word":"winged","pos":"adj.","zh":"有翅膀的；能飞的"},{"word":"wingless","pos":"adj.","zh":"无翅的"},{"word":"winger","pos":"n.","zh":"边锋；侧翼成员"},{"word":"winglet","pos":"n.","zh":"小翼；翼梢小翼"},{"word":"wingbeat","pos":"n.","zh":"一次振翅"}],"senses":[{"no":"01","title":"One of the Paired Organs of Flight","titleCN":"鸟或昆虫的翅","definition":"one of the paired limbs or membranes that birds and insects use to fly","definitionCN":"鸟类与昆虫用于飞行的成对肢体或膜","example":"A heron spread each wing to dry in the sun.","exampleCN":"一只鹭展开双翅在阳光下晾干。","why":"wing names the paired organ itself; every other sense in this entry is a lateral thing measured against it.","whyCN":"wing 指的就是这对器官本身；本词条其余义项都是与它相较而言的「侧向之物」。"},{"no":"02","title":"The Act of Flying","titleCN":"飞行这一行为或能力","definition":"the act or power of flight, especially in the phrase take wing","definitionCN":"飞行的动作或能力，尤用于 take wing 这一短语","example":"The geese took wing at the first sound of the shot.","exampleCN":"枪声一响，大雁便振翅起飞。","why":"the organ becomes the act: to take wing is to leave the ground by means of wings.","whyCN":"器官转成了动作：take wing 就是凭借翅膀离开地面。"},{"no":"03","title":"A Side Part of a Building","titleCN":"建筑物的侧翼、耳房","definition":"a part of a large building that stands out from the main block","definitionCN":"大型建筑中从主体向外突出的部分","example":"A new laboratory occupies the west wing of the college.","exampleCN":"一座新实验室占据了学院的西翼楼。","why":"a building grows a part that stands out from the main block, exactly as a wing stands out from a body.","whyCN":"建筑长出一部分，从主体向外突出，正如翅膀从身体向外伸出。"},{"no":"04","title":"A Faction Within a Party","titleCN":"政党或组织的派系","definition":"one of the grouped sides into which a political party or organisation is divided","definitionCN":"政党或组织内部划分出的成组一方","example":"The left wing of the party pressed for land reform.","exampleCN":"该党左翼力主土地改革。","why":"a party splits into sides, and each side is imagined as a wing of one body.","whyCN":"政党分裂成若干侧，每一侧都被想象为同一身体的一只翅膀。"},{"no":"05","title":"The Side Scenes of a Stage","titleCN":"舞台侧幕","definition":"the hidden side areas of a stage, usually in the plural, where performers wait","definitionCN":"舞台两侧隐蔽的区域，通常用复数，演员在此候场","example":"She waited in the stage wing until her cue came.","exampleCN":"她在舞台侧幕里一直等到上场提示。","why":"the stage's side spaces are hidden from the audience, like wings folded against the body.","whyCN":"舞台两侧的空间对观众隐藏，正如收拢在身体两侧的翅膀。"},{"no":"06","title":"The Flank of an Army","titleCN":"军事侧翼","definition":"the left or right end of a line of troops, the part most open to attack","definitionCN":"军队战线左右两端，也是最易受攻击的部分","example":"Two companies were sent to turn the enemy's wing.","exampleCN":"两个连被派去包抄敌军侧翼。","why":"an army deploys in a line whose ends project outward, so those ends are its wings.","whyCN":"军队展开成一条线，两端向外突出，于是这两端就是它的翅膀。"},{"no":"07","title":"British Word for a Mudguard","titleCN":"英式：汽车挡泥板","definition":"British, the panel over a wheel that catches mud and stones","definitionCN":"英式用法，指车轮上方挡泥挡石的板","example":"A stone cracked the near-side wing of the car.","exampleCN":"一块石头砸裂了汽车左侧的挡泥板。","why":"British usage names the panel over the wheel after the wing that shelters the wheel.","whyCN":"英式用法用「翼」来称呼车轮上方的护板，因为它为车轮提供遮蔽。"},{"no":"08","title":"Under Someone's Protection","titleCN":"受某人庇护","definition":"in the phrase under one's wing, meaning cared for and guided by someone","definitionCN":"用于 under one's wing，意为受某人照料与引导","example":"The senior nurse took the new intern under her wing.","exampleCN":"资深护士把新来的实习生收在自己的羽翼之下。","why":"the sheltering gesture of a bird covering its young gives the idiom its meaning.","whyCN":"鸟以翅膀覆护幼鸟的动作，给了这个习语以含义。"}],"etymology":{"intro":{"en":"Wing is a Middle English borrowing from Old Norse vængr; it is not a native Old English word, where feðer 'feather' covered the sense. The pre-Germanic origin of vængr is uncertain.","cn":"wing 是中古英语借自古诺斯 vængr 的词；它不是古英语本土词，古英语用 feðer「羽毛」表达此义。vængr 在日耳曼语之前的来源不确定。"},"items":[{"era":"OLD NORSE VÆNGR","en":"Old Norse vængr meant 'wing'; Middle English borrowed it, which is why wing has no native Old English ancestry.","cn":"古诺斯语 vængr 意为「翼」；中古英语借入该词，因此 wing 没有古英语本土来源。"},{"era":"GERMANIC COGNATES","en":"The same noun appears in Danish vinge and Swedish vinge, so the word belongs to the Germanic stock rather than to Latin.","cn":"同一名词见于丹麦语 vinge 与瑞典语 vinge，可见它属于日耳曼语汇而非拉丁语汇。"},{"era":"OLD ENGLISH FEÐER","en":"Old English used feðer 'feather' for a bird's wing; wing enters English only in the Middle English period.","cn":"古英语用 feðer「羽毛」指鸟翼；wing 直到中古英语时期才进入英语。"},{"era":"DEEP ORIGIN UNCERTAIN","en":"The pre-Germanic source of vængr is uncertain; no single Indo-European root is agreed, and the competing reconstructions differ.","cn":"vængr 在日耳曼语之前的来源不确定；学界未就单一印欧词根达成一致，各种重构形式互不相同。"},{"era":"LATERAL EXTENSION","en":"From the bird's limb the word extended to anything projecting sideways: a building wing, an army flank, a party faction.","cn":"从鸟的肢体出发，该词延伸到一切向侧方伸出的部分：建筑的侧翼、军队的侧翼、政党的派系。"},{"era":"MODERN SPREAD","en":"Theatre wings, the verb wing it, and the British car wing all belong to the modern spread of the same lateral idea.","cn":"舞台侧幕、动词 wing it 以及英式汽车的挡泥板，都属于同一「侧向」观念在现代的扩散。"}]},"similar":{"note":{"en":"Group one holds words that look like wing but come from different roots; group two holds words that cover parts of its meaning.","cn":"第一组是外形相近但词根不同的词；第二组是覆盖其部分含义的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"swing","ipa":"/swɪŋ/","tag":"different root","definition":"From Old English swingan 'to beat, flog'; it is a Germanic verb of motion and is not related to the noun wing.","definitionCN":"来自古英语 swingan「击打、抽打」；是日耳曼语的运动动词，与名词 wing 没有同源关系。"},{"word":"wink","ipa":"/wɪŋk/","tag":"different root","definition":"From Old English wincian 'to close the eyes'; its deeper origin is uncertain and it has no link to wing.","definitionCN":"来自古英语 wincian「闭眼」；更早来源不确定，与 wing 没有关联。"},{"word":"winch","ipa":"/wɪntʃ/","tag":"different root","definition":"From Old English wince 'a pulley', probably Germanic; it shares the initial sound but not the root.","definitionCN":"来自古英语 wince「滑轮」，可能属日耳曼语；只有起首音相同，词根不同。"},{"word":"wind","ipa":"/wɪnd/","tag":"different root","definition":"From Old English wind 'moving air'; it is unrelated to wing, and the verb wind 'to coil' is a separate word as well.","definitionCN":"来自古英语 wind「流动的空气」；与 wing 无关，动词 wind「缠绕」也是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pinion","ipa":"/ˈpɪnjən/","tag":"literary or technical","definition":"A bird's wing, especially the outer part with the flight feathers; it is poetic or technical where wing is neutral.","definitionCN":"鸟翼，尤指带飞羽的外侧部分；-wing 中性通用，而 pinion 偏诗语或技术语。"},{"word":"limb","ipa":"/lɪm/","tag":"broader","definition":"Any projecting appendage of a body; wing is the specialised flight limb, while limb covers arms, legs and branches.","definitionCN":"身体任何突出的附肢；wing 是专司飞行的肢，而 limb 涵盖臂、腿与枝。"},{"word":"annex","ipa":"/ˈæneks/","tag":"building side part","definition":"A building added to or attached to a larger one; it stresses addition, while a wing stresses lateral position.","definitionCN":"增建或附属于较大建筑的楼；它强调「附加」，而 wing 强调「侧向位置」。"},{"word":"faction","ipa":"/ˈfækʃən/","tag":"political side","definition":"A self-interested group inside a larger body; it is the political sense of wing seen from the inside.","definitionCN":"较大团体内部自成一体的一群；它是 wing 政治义的内侧视角。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real borrowed Norse noun, a real Old English alternative, and the real lateral metaphors in architecture, politics and theatre.","cn":"正常联想：真实借入的古诺斯名词、真实的古英语替代词，以及建筑、政治与戏剧中真实的「侧向」比喻。"},"normal":[{"en":"wing came from Old Norse vængr; Old English said feðer for the same thing.","cn":"wing 来自古诺斯 vængr；古英语用 feðer 表示同一事物。"},{"en":"One shape, many sides: a bird's wing, a building wing, an army wing, a party wing.","cn":"一个形状，多处侧向：鸟的翼、建筑的翼、军队的翼、政党的翼。"},{"en":"The theatre hides its wings, so waiting in the wings means waiting out of sight.","cn":"剧院把侧幕藏起来，所以 in the wings 意为在看不见的地方等候。"},{"en":"British drivers keep their spare wheel under the wing, the panel over the wheel.","cn":"英国司机把备胎放在挡泥板下，也就是车轮上方那块板。"},{"en":"The family runs wing, winged, wingless, winger, winglet.","cn":"同族词包括 wing、winged、wingless、winger、winglet。"}],"abstract":[{"en":"Picture a body growing one arm sideways, and that arm is a wing.","cn":"想象一个身体向侧边长出一条臂，这条臂就是翼。"},{"en":"Picture a house with an arm reaching out from its main block.","cn":"想象一座房子从主体伸出一条臂。"},{"en":"Picture a party splitting into two sides, each calling itself a wing.","cn":"想象一个政党裂成两侧，每一侧都自称是一只翼。"}]},"examples":[{"en":"The aircraft's left wing was damaged by hail.","cn":"飞机的左翼被冰雹打伤。"},{"en":"The right wing of the party opposed the new tax.","cn":"该党右翼反对这项新税。"},{"en":"A young technician learned the job under the chief engineer's wing.","cn":"一名年轻技术员在总工程师的庇护下学会了这门工作。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「wing（翁）」——鸟一振翅，耳边风声嗡嗡 → 翅膀、侧翼","word":"wing"},"root":"中古英语 wing 借自古诺斯 vængr「翼」，属日耳曼语族（丹麦语 vinge、瑞典语 vinge 同源）；更早来源不确定，无公认的印欧词根；不是古英语本土词，古英语以 feðer「羽毛」表翼。","sensesIntro":{"en":"Eight senses of wing follow one geometry: a part that projects sideways from a body, whether that body is a bird, a building, an army or a party.","cn":"wing 的八个义项沿同一个几何关系展开：从某个主体向侧方突出的部分，无论主体是鸟、建筑、军队还是政党。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pair of wings extending sideways from a body and lifting it.","cn":"核心意象：从身体两侧伸出、把身体托起的一对翅膀。"},"chain":["PAIRED LIMB","FLIGHT","SIDE EXTENSION","BUILDING ANNEX","POLITICAL FACTION","SHELTER"],"branches":[{"senses":"01 · 02","en":"FLIGHT: the organ itself and the act of using it.","cn":"飞行：器官本身以及使用它的动作。"},{"senses":"03","en":"BUILDING: a side part attached to the main block.","cn":"建筑：附着于主体的侧向部分。"},{"senses":"04 · 06","en":"SIDES OF A BODY: a party faction and an army flank are both lateral ends.","cn":"主体的两侧：政党派系与军队侧翼都是侧向的末端。"},{"senses":"05 · 07","en":"EVERYDAY SIDES: stage side scenes and the British panel over a wheel.","cn":"日常的侧向：舞台侧幕与英式车轮上方的护板。"},{"senses":"08","en":"SHELTER: the wing becomes an arm that covers and protects.","cn":"庇护：翼变成一条覆盖、保护的臂。"}]},"affixes":{"intro":{"en":"Wing is a borrowed noun that English also uses as a verb and builds a small family on.","cn":"wing 是一个借入的名词，英语也把它用作动词，并在它之上构建了一个小词族。"},"latinIntro":{"en":"No Latin cognate of wing is recoverable; the Latin word for wing is ala, an unrelated form.","cn":"wing 没有可追溯的拉丁同源词；拉丁语表「翼」的词是 ala，属无关形式。"},"items":[{"word":"wing","structure":"vængr (Old Norse noun, masculine) → Middle English wing","meaning":"the paired organ of flight","meaningCN":"成对的飞行器官","example":"The wing was broken but the bird survived.","exampleCN":"翅膀断了，但那只鸟活了下来。"},{"word":"wings","structure":"wing + -s (plural and third person singular)","meaning":"more than one wing, or he, she, it flies","meaningCN":"多只翅膀；或他、她、它飞行","example":"The moth's wings are dusted with scales.","exampleCN":"蛾的翅膀上覆满鳞粉。"},{"word":"winged","structure":"wing + -ed","meaning":"having wings","meaningCN":"有翅膀的","example":"A winged ant left the nest at dusk.","exampleCN":"一只带翅的蚂蚁在黄昏离巢。"},{"word":"wingless","structure":"wing + -less (Old English -lēas 'lacking')","meaning":"without wings","meaningCN":"无翅的","example":"The wingless female never leaves the colony.","exampleCN":"无翅的雌虫从不离开群体。"},{"word":"winger","structure":"wing + -er","meaning":"a player on the side, or a member of a party wing","meaningCN":"边锋；某派系成员","example":"The winger crossed the ball from the touchline.","exampleCN":"边锋从边线把球传中。"},{"word":"winglet","structure":"wing + -let (diminutive suffix)","meaning":"a small wing, or a small fin at a wingtip","meaningCN":"小翼；翼梢小翼","example":"The winglet reduces drag at cruising speed.","exampleCN":"翼梢小翼在巡航速度下减小阻力。"},{"word":"wing it","structure":"wing (verb) + it (idiomatic phrase)","meaning":"to perform without preparation","meaningCN":"即兴应付；无准备上阵","example":"She had forgotten her notes and had to wing it.","exampleCN":"她忘了带讲稿，只好临场发挥。"},{"word":"take wing","structure":"take + wing (fixed phrase)","meaning":"to fly off","meaningCN":"起飞；飞走","example":"The flock took wing before the storm arrived.","exampleCN":"鸟群在暴风雨来临前起飞。"},{"word":"left wing","structure":"left + wing (political and military compound)","meaning":"the left side of a party or a line","meaningCN":"左翼；左派","example":"The left wing of the movement demanded rent control.","exampleCN":"这场运动的左翼要求租金管制。"}],"latinEntries":[]}},{"word":"winged","ipa_uk":"/wɪŋd/","ipa_us":"/wɪŋd/","definition_zh":"有翅膀的；能飞的；飞快的；具翅状附属物的；带翼纹饰的","definition_en":"having wings, able to fly, or shaped and decorated with something that resembles a wing, often used figuratively of speed and of words","core_image":"一副展开的翅膀被凝固在雕像、种子与眼线上，凡是添上这对侧翼的东西都获得向上的动势","scene":"电报站里，值班员把刚收到的消息递出去，一刻也不耽搁。 The news spread at winged speed through every harbor town.","sceneCN":"这里 winged 是「飞快的」（第 3 个义项：比喻速度极快，如添翼一般）；句意：消息以飞快的速度传遍每一个港口城镇。","pos":[{"tag":"adj.","zh":"有翅膀的；能飞的；飞快的；带翼形装饰的（多作定语，也可作表语）"}],"collocations":[{"phrase":"winged words","zh":"有翼的话语（荷马式套语，指迅速传开的话）"},{"phrase":"winged victory","zh":"带翼的胜利女神；带翼胜利像"},{"phrase":"winged helmet","zh":"带翼头盔"},{"phrase":"winged eyeliner","zh":"带翼眼线；上扬眼线"},{"phrase":"winged seed","zh":"有翅种子"},{"phrase":"winged insect","zh":"有翅昆虫"},{"phrase":"at winged speed","zh":"以飞快的速度"}],"forms":[{"label":"原级","form":"winged"},{"label":"比较级","form":"more winged"},{"label":"最高级","form":"most winged"},{"label":"诗体异读","form":"winged（/ˈwɪŋɪd/，诗中作两音节）"},{"label":"同根名词","form":"wing"},{"label":"同根否定形容词","form":"wingless（无翅的）"}],"derivatives":[{"word":"wing","pos":"n.","zh":"翅膀；侧翼"},{"word":"wingless","pos":"adj.","zh":"无翅的"},{"word":"winglet","pos":"n.","zh":"小翼；翼梢小翼"},{"word":"winger","pos":"n.","zh":"边锋；派系成员"},{"word":"winglike","pos":"adj.","zh":"翼状的"}],"senses":[{"no":"01","title":"Having Wings","titleCN":"有翅膀的","definition":"having wings, especially as a visible physical feature","definitionCN":"长有翅膀，尤指作为可见的身体特征","example":"Every winged specimen in the collection is pinned above its label.","exampleCN":"收藏中每一件有翅标本都钉在标签上方。","why":"winged is wing plus -ed, and the suffix says the wings are present as a feature.","whyCN":"winged 是 wing 加 -ed，后缀表明翅膀作为特征存在于其上。"},{"no":"02","title":"Able to Fly","titleCN":"能飞的","definition":"capable of flight, as opposed to a wingless or flightless form","definitionCN":"具备飞行能力，与无翅或不能飞的形态相对","example":"No winged animal crosses the strait in winter.","exampleCN":"冬季没有能飞的动物越过这道海峡。","why":"possession implies capacity: what has wings can fly, so the adjective shifts from part to power.","whyCN":"拥有意味着能力：有翅膀就能飞，形容词于是从「部件」转向「能力」。"},{"no":"03","title":"Moving at Winged Speed","titleCN":"迅速的、飞快的","definition":"figurative and literary, moving or spreading with great speed","definitionCN":"比喻与书面用法，指以极快速度移动或传播","example":"Rumour spread at winged speed through the camp.","exampleCN":"谣言以飞快的速度传遍营地。","why":"speed is borrowed from flight; anything that arrives as if on wings is winged.","whyCN":"速度借自飞行；任何仿佛乘翼而至的东西都可称作 winged。"},{"no":"04","title":"Winged Words That Travel","titleCN":"有翼的话语（荷马式套语）","definition":"in the Homeric formula 'winged words', speech that flies from speaker to listener","definitionCN":"荷马式套语「有翼的话语」，指从说者飞向听者的话语","example":"Homer's winged words outlive the speakers who utter them.","exampleCN":"荷马那些有翼的话语，比说出它们的人活得更久。","why":"Homer's formula calls speech epea pteroenta, 'winged words', because words fly from mouth to ear.","whyCN":"荷马的套语把言语称为 epea pteroenta「有翼的话语」，因为话语从口飞到耳。"},{"no":"05","title":"Wearing a Winged Helmet","titleCN":"带翼头盔的（赫尔墨斯形象）","definition":"describing a figure or object fitted with wings as an attribute, as the helmet of Hermes","definitionCN":"描述装有翅膀作为标志的人物或器物，如赫尔墨斯的头盔","example":"The bronze god wears a winged helmet and holds a staff.","exampleCN":"那尊青铜神像戴着带翼头盔，手持权杖。","why":"myth gives Hermes a helmet with wings, and the adjective describes any figure wearing that attribute.","whyCN":"神话给赫尔墨斯一顶带翼头盔，形容词便描述任何佩戴这一标志的形象。"},{"no":"06","title":"Bearing Winged Seeds","titleCN":"具翅果实或种子的（植物学）","definition":"botanical, of a fruit or seed with a thin flat extension that acts like a wing in the air","definitionCN":"植物学术语，指果实或种子带有在空气中起翼作用的薄平延伸物","example":"A winged seed spins as it falls from the maple.","exampleCN":"一颗有翅种子从枫树上落下时旋转而下。","why":"a seed's thin flat edge works like a wing in the air, so botanists call the fruit winged.","whyCN":"种子的薄平边缘在空气中起翅膀的作用，植物学家因此称这种果实为有翅的。"},{"no":"07","title":"Of Winged Eyeliner","titleCN":"带翼眼线的（化妆义）","definition":"describing a cosmetic line that flicks upward at the outer corner of the eye like a small wing","definitionCN":"描述在外眼角向上挑出、形如小翼的化妆线条","example":"She wore winged eyeliner to the opening night.","exampleCN":"她在首演之夜画了带翼眼线。","why":"the drawn line flicks upward at the outer corner like a small wing.","whyCN":"画出的线在外眼角向上挑，形如一只小翼。"},{"no":"08","title":"In the Posture of Winged Victory","titleCN":"带翼胜利女神式的（雕像与比喻）","definition":"describing a statue, pose or image modelled on the winged figure of Victory","definitionCN":"描述以带翼胜利女神为原型的雕像、姿态或形象","example":"A winged victory crowns the marble arch.","exampleCN":"一座带翼胜利像立在大理石拱门顶端。","why":"the Nike of Samothrace is shown with wings, and any pose or image echoing her is called winged victory.","whyCN":"萨莫色雷斯的胜利女神像带翼，任何呼应她的姿态或形象都被称为带翼的胜利。"}],"etymology":{"intro":{"en":"Winged is wing plus -ed. Wing itself is a Middle English borrowing from Old Norse vængr, not a native Old English word; the suffix -ed goes back to Old English -ed. Dates are approximate.","cn":"winged 是 wing 加 -ed。wing 本身是中古英语借自古诺斯 vængr 的词，并非古英语本土词；后缀 -ed 可上溯古英语 -ed。年代均为约数。"},"items":[{"era":"OLD NORSE VÆNGR","en":"Old Norse vængr 'wing' supplied the noun; its pre-Germanic origin is uncertain and no single Indo-European root is agreed.","cn":"古诺斯语 vængr「翼」提供了这个名词；它在日耳曼语之前的来源不确定，学界未就单一印欧词根达成一致。"},{"era":"MIDDLE ENGLISH WING","en":"Middle English borrowed the noun as wing, displacing the older native feðer in the sense 'wing'.","cn":"中古英语借入该名词作 wing，并在「翼」这一义上取代了本土旧词 feðer。"},{"era":"SUFFIX -ED","en":"Old English -ed marked the past participle; used adjectivally it means 'furnished with', so winged means furnished with wings.","cn":"古英语 -ed 标记过去分词；作形容词时意为「配备有」，因此 winged 即「配备翅膀的」。"},{"era":"HOMERIC FORMULA","en":"Greek epea pteroenta 'winged words' is a fixed Homeric phrase; English translators rendered it literally, fixing the phrase in literary English.","cn":"希腊 epea pteroenta「有翼的话语」是荷马固定套语；英语译者逐字译出，使该短语固定于文学英语。"},{"era":"MODERN EXTENSIONS","en":"Winged helmet, winged victory, winged eyeliner and winged seed extend the adjective to myth, art, cosmetics and botany.","cn":"winged helmet、winged victory、winged eyeliner 与 winged seed 把这形容词延伸到神话、艺术、化妆与植物学。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest use of winged as an adjective is not firmly dated, and the history of vængr before Old Norse remains a reconstruction.","cn":"来源不确定（首见年代）：winged 作形容词的最早用例没有可靠年代，vængr 在古诺斯语之前的历史仍属重构。"}]},"similar":{"note":{"en":"Group one holds words that look like winged but have unrelated roots; group two holds words that describe flight, wings or speed from another angle.","cn":"第一组是外形相近但词根无关的词；第二组是从另一角度描述飞行、翅膀或速度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"wingding","ipa":"/ˈwɪŋdɪŋ/","tag":"not related, slang","definition":"American slang for a lively party; its origin is uncertain and it is not built on wing 'a bird's limb'.","definitionCN":"美式俚语，指热闹的聚会；来源不确定，并非由表「鸟翼」的 wing 构成。"},{"word":"winded","ipa":"/ˈwɪndɪd/","tag":"different root","definition":"Out of breath, from wind 'breath'; the ending looks the same but the base noun is a different word.","definitionCN":"喘不过气的，来自 wind「呼吸」；词尾相同，但基础名词是另一个词。"},{"word":"wedding","ipa":"/ˈwedɪŋ/","tag":"not related","definition":"From Old English weddian 'to pledge'; it merely rhymes and looks close to winged.","definitionCN":"来自古英语 weddian「立誓」；只是押韵、外形相近，与 winged 无关。"},{"word":"wring","ipa":"/rɪŋ/","tag":"different root","definition":"From Old English wringan 'to twist'; it is a Germanic verb of squeezing, with no link to wing or winged.","definitionCN":"来自古英语 wringan「扭」；是日耳曼语的挤压动词，与 wing 或 winged 无关联。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flighted","ipa":"/ˈflaɪtɪd/","tag":"ornithological","definition":"Having functional flight feathers, used in zoology as the opposite of flightless; winged is the plainer word and can also mean merely decorated with wings.","definitionCN":"具备可用的飞羽，动物学中与「不能飞」相对；winged 更朴素，也可仅指装饰有翅膀。"},{"word":"alate","ipa":"/əˈleɪt/","tag":"technical, winged form","definition":"Entomological and botanical term for 'winged', especially of the winged reproductive form of an insect.","definitionCN":"昆虫学与植物学中「有翅的」术语，尤指昆虫的有翅繁殖型。"},{"word":"feathered","ipa":"/ˈfeðəd/","tag":"covered with feathers","definition":"Covered with feathers, not necessarily able to fly; it names plumage, while winged names the wing.","definitionCN":"覆有羽毛，未必能飞；它命名的是羽衣，而 winged 命名的是翼。"},{"word":"swift","ipa":"/swɪft/","tag":"plain synonym of the speed sense","definition":"Fast in movement; the everyday adjective for speed, whereas winged speed is literary and implies flight.","definitionCN":"移动迅速的日常形容词；而 winged speed 属书面语，含有「如飞」的意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real -ed suffix, the real Homeric formula, and the real decorative and botanical uses of wings.","cn":"正常联想：真实的 -ed 后缀、真实的荷马套语，以及翅膀在装饰与植物学中的真实用法。"},"normal":[{"en":"wing + -ed: wings attached, therefore able to fly.","cn":"wing + -ed：翅膀被装上，因此能够飞。"},{"en":"The noun came from Old Norse vængr; Old English had feðer instead.","cn":"名词来自古诺斯 vængr；古英语本来用的是 feðer。"},{"en":"The formula winged words translates Greek epea pteroenta and belongs to Homer.","cn":"winged words 译自希腊 epea pteroenta，出自荷马。"},{"en":"Fixed phrases spread the senses: winged helmet, winged victory, winged eyeliner, winged seed.","cn":"固定搭配把义项铺开：带翼头盔、带翼胜利像、带翼眼线、有翅种子。"},{"en":"The family runs wing, winged, wingless, winglet, winger.","cn":"同族词包括 wing、winged、wingless、winglet、winger。"}],"abstract":[{"en":"Picture a small wing added to a head, a foot or a drawn line, and the whole thing seems about to lift.","cn":"想象给头、脚或一条线添上一只小翼，整个东西便仿佛要升起。"},{"en":"Picture words sprouting wings and leaving the mouth before the speaker can call them back.","cn":"想象话语长出翅膀，在说者来得及收回之前就已离口。"},{"en":"Picture a marble figure whose wings are the only reason it seems to hover.","cn":"想象一尊大理石像，它之所以像悬在空中，全靠那对翅膀。"}]},"examples":[{"en":"Winged insects were the first animals to take to the air.","cn":"有翅昆虫是最早飞上天空的动物。"},{"en":"The courier brought the treaty at winged speed.","cn":"信使以飞快的速度送来了条约。"},{"en":"A winged figure watches over the gate.","cn":"一个带翼的形象守护着大门。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「wing（翅膀）+ ed」——装上翅膀，便能飞、便飞快 → 有翅膀的、飞快的","word":"winged"},"root":"wing（中古英语借自古诺斯 vængr「翼」，更早来源不确定）+ -ed（古英语 -ed，过去分词后缀作形容词，义为「配备有」）；希腊荷马套语 epea pteroenta「有翼的话语」是独立的固定译法来源。","sensesIntro":{"en":"Eight senses of winged grow from one addition: wings attached to a body, a seed or a line, and everything that follows from having them, from flight and speed to myth and makeup.","cn":"winged 的八个义项都从一个「添加」长出：给身体、种子或线条装上翅膀，以及由此而来的一切，从飞行与速度到神话与妆容。"},"semanticMap":{"core":{"en":"CORE IMAGE: wings added to a body, a seed or a line, lending lift and speed.","cn":"核心意象：给身体、种子或线条添上翅膀，带来升力与速度。"},"chain":["WINGS ATTACHED","FLIGHT","SWIFT PASSAGE","HOMERIC SPEECH","DECORATED FORM","VICTORY"],"branches":[{"senses":"01 · 02","en":"OWNING FLIGHT: wings are present, and therefore flight is possible.","cn":"拥有飞行：翅膀在场，因此飞行成为可能。"},{"senses":"03 · 04","en":"SPEED AND SPEECH: what moves fast is news, rumour or the words of Homer.","cn":"速度与言语：快速移动的是消息、谣言或荷马的话语。"},{"senses":"05 · 08","en":"ICONIC WINGS: the helmet of Hermes and the statue of Victory.","cn":"标志性的翼：赫尔墨斯的头盔与胜利女神像。"},{"senses":"06","en":"PLANT: a seed or fruit fitted with a wing-like edge.","cn":"植物：种子或果实带有翼状边缘。"},{"senses":"07","en":"COSMETIC: a line drawn upward like a wing.","cn":"妆容：向上挑出如翼的一条线。"}]},"affixes":{"intro":{"en":"Winged is a two-piece word: a borrowed noun for the organ of flight, and an ending that says the organ is present.","cn":"winged 是一个两段式词：借入的「飞行器官」名词，加上表示该器官在场的后缀。"},"latinIntro":{"en":"Latin has no cognate of wing; its word for wing is ala, which English never borrowed into this family. The Greek pteron 'wing' belongs to the Homeric phrase only.","cn":"拉丁语没有与 wing 同源的词；拉丁语表「翼」的是 ala，英语并未把它借入这个词族。希腊语 pteron「翼」只属于荷马短语。"},"items":[{"word":"wing","structure":"vængr (Old Norse noun, masculine) → Middle English wing","meaning":"wing","meaningCN":"翅膀","example":"The wing healed within a month.","exampleCN":"那只翅膀一个月内痊愈了。"},{"word":"-ed","structure":"-ed (Old English past participle suffix, adjectival use)","meaning":"furnished with, having","meaningCN":"配备有；具有","example":"Winged means furnished with wings.","exampleCN":"winged 意为配备有翅膀的。"},{"word":"winged","structure":"wing + -ed","meaning":"having wings or moving as if on wings","meaningCN":"有翅膀的；如乘翼般移动的","example":"A winged seed travels farther than a heavy one.","exampleCN":"有翅种子比沉重的种子传播得更远。"},{"word":"wingless","structure":"wing + -less (Old English -lēas 'lacking')","meaning":"without wings","meaningCN":"无翅的","example":"The wingless worker never leaves the nest.","exampleCN":"无翅的工蚁从不离开巢穴。"},{"word":"winger","structure":"wing + -er (agent suffix)","meaning":"one who plays on a wing, or belongs to a wing","meaningCN":"边锋；属于某一翼者","example":"The winger scored from the edge of the box.","exampleCN":"边锋在禁区边缘得分。"},{"word":"winglet","structure":"wing + -let (diminutive suffix)","meaning":"a small wing-like surface","meaningCN":"小翼；翼状小面","example":"The winglet is angled to cut drag.","exampleCN":"小翼以一定角度安装以减小阻力。"},{"word":"winged words","structure":"winged + words (translation of Greek epea pteroenta)","meaning":"speech that flies straight to the listener","meaningCN":"直飞听者的话语","example":"The translator kept the Homeric phrase winged words.","exampleCN":"译者保留了荷马式的「有翼的话语」。"},{"word":"winged eyeliner","structure":"winged + eyeliner (cosmetic compound)","meaning":"an eyeliner line flicked up at the outer corner","meaningCN":"在外眼角上挑的眼线","example":"Winged eyeliner takes a steady hand.","exampleCN":"画带翼眼线需要手很稳。"},{"word":"at winged speed","structure":"at + winged + speed (literary phrase)","meaning":"extremely fast","meaningCN":"以极快的速度","example":"The report travelled at winged speed through the ministry.","exampleCN":"这份报告以极快的速度传遍部里。"}],"latinEntries":[]}},{"word":"flight","ipa_uk":"/flaɪt/","ipa_us":"/flaɪt/","definition_zh":"飞行，飞行的动作；航班，一次空中旅程；飞行的鸟群；一段楼梯；逃跑；飞行轨迹与箭羽","definition_en":"the act of moving through the air, and any single instance, group, or path of such movement, including a set of stairs and the feathers that steady an arrow","core_image":"一只鸟从石阶底部掠起，沿着一道弧线飞过屋顶，翅尖的羽毛在光里闪了一下","scene":"清晨的山脊上，一群候鸟被光线的变化惊起，贴着坡面滑向另一侧谷地。 The flock rose into flight as the sun broke over the ridge.","sceneCN":"这里 flight 是「飞行」（第 1 个义项：在空中移动这一动作本身）；句意为太阳越过山脊时，鸟群起飞了。","pos":[{"tag":"n.","zh":"飞行；航班；鸟群；一段楼梯；逃跑（可数，复数 flights）"},{"tag":"vi.","zh":"（鸟类）成群飞；给箭装尾羽（较少用，多作专业动词）"}],"collocations":[{"phrase":"take flight","zh":"起飞；逃走"},{"phrase":"in flight","zh":"在飞行中"},{"phrase":"flight path","zh":"飞行路线；弹道"},{"phrase":"flight deck","zh":"驾驶舱；航母飞行甲板"},{"phrase":"flight attendant","zh":"空中乘务员"},{"phrase":"a flight of stairs","zh":"一段楼梯"},{"phrase":"put to flight","zh":"使溃逃；赶跑"}],"forms":[{"label":"原形","form":"flight"},{"label":"复数","form":"flights"},{"label":"形容词（装有箭羽的）","form":"flighted（饰有尾羽的）"},{"label":"派生形容词（不能飞的）","form":"flightless（不能飞的）"},{"label":"派生形容词（轻浮的）","form":"flighty（轻浮的）"},{"label":"复合名词","form":"flight path（飞行路线）"}],"derivatives":[{"word":"flighty","pos":"adj.","zh":"轻浮的；易变的"},{"word":"flightless","pos":"adj.","zh":"不能飞的"},{"word":"flighted","pos":"adj.","zh":"装有箭羽的；能飞的"},{"word":"flightiness","pos":"n.","zh":"轻浮；反复无常"}],"senses":[{"no":"01","title":"The Act of Flying","titleCN":"飞行（动作本身）","definition":"the action or process of moving through the air on wings or in an aircraft","definitionCN":"凭借翅膀或飞行器在空中移动的动作或过程","example":"The gulls' flight over the harbour lasted only a few seconds.","exampleCN":"海鸥掠过港湾的飞行只持续了几秒钟。","why":"flyht is the bare action noun built on the verb fleogan 'to fly'; the suffix -t turns the doing into a thing you can name.","whyCN":"flyht 是由动词 fleogan「飞」直接构成的动作名词，后缀 -t 把「做」变成可以命名的「事」。"},{"no":"02","title":"A Scheduled Air Journey","titleCN":"航班；一次空中旅程","definition":"a trip made by air, especially one operated on a regular service between two places","definitionCN":"乘飞机的一次行程，尤指两地间按班期运营的航次","example":"Our flight to Denver leaves before dawn.","exampleCN":"我们飞往丹佛的航班在黎明前起飞。","why":"a scheduled service is one completed act of flying, so the uncountable action is counted out into separate items.","whyCN":"一次班期服务就是一整次完成的飞行，于是不可数的动作被切分成一个个可数的班次。"},{"no":"03","title":"A Flock on the Wing","titleCN":"飞行的鸟群","definition":"a group of birds or aircraft moving through the air together","definitionCN":"一起在空中移动的一群鸟或飞行器","example":"A flight of geese crossed the marsh at dusk.","exampleCN":"一群大雁在黄昏时飞越沼泽。","why":"the collective noun applies the action to the whole body that performs it at one time, so the group is named after its flight.","whyCN":"这个集合名词把动作归给同时做出它的整个群体，于是这一群就以「飞行」命名。"},{"no":"04","title":"A Set of Stairs","titleCN":"一段楼梯","definition":"a continuous run of steps between one floor or landing and the next","definitionCN":"两层楼或两个平台之间连续的一串台阶","example":"She carried the box up the last flight of stairs.","exampleCN":"她把箱子搬上了最后一段楼梯。","why":"a run of steps rises step after step like a body climbing through air, so English lent the word for flying to this rising series.","whyCN":"一串台阶一级接一级地上升，像身体在空中爬升，英语于是把「飞行」这个词借给了这道上升的序列。"},{"no":"05","title":"Escape by Running","titleCN":"逃跑；溃逃","definition":"the act of fleeing or being driven away from danger","definitionCN":"逃离危险或被赶离现场的行为","example":"The intruders were put to flight by a single shout.","exampleCN":"一声喊叫就把闯入者赶跑了。","why":"fleeing is the oldest figurative use of flying: the body takes off as if on wings, so the same noun covers panic movement on the ground.","whyCN":"逃跑是「飞」最古老的比喻用法：身体仿佛长了翅膀般离开，同一个名词因此也指地面上的仓皇移动。"},{"no":"06","title":"Path of a Projectile","titleCN":"抛射体的飞行轨迹","definition":"the curved course followed by an arrow, bullet or ball through the air","definitionCN":"箭、子弹或球在空中划出的弧线路径","example":"The arrow's flight flattened as it lost speed.","exampleCN":"箭在速度衰减时，飞行弧线变得平缓。","why":"a projectile repeats the core action without wings: it too crosses the air along a line, and the line is named after the crossing.","whyCN":"抛射体没有翅膀却重复了核心动作：它也沿一条线穿过空气，这条线就以「穿越」命名。"},{"no":"07","title":"Flight of Fancy","titleCN":"想入非非；异想天开","definition":"a burst of imaginative invention that has little grounding in fact","definitionCN":"一段缺少事实依据的想象性发挥","example":"The plan was a flight of fancy that no budget could support.","exampleCN":"那项计划纯属异想天开，没有哪份预算支撑得起。","why":"the mind is pictured as taking off and leaving the ground of fact, exactly the movement the word already names.","whyCN":"这里把心智想象成起飞、离开事实的地面，正是这个词本已命名的那个动作。"},{"no":"08","title":"Feathers on an Arrow","titleCN":"箭羽（箭尾的羽毛）","definition":"the feathers fitted near the head of an arrow shaft to keep it steady in flight","definitionCN":"装在箭杆尾端附近、使箭飞行稳定的羽毛","example":"He replaced the torn flight on the arrow before the match.","exampleCN":"比赛前他换掉了箭上破损的箭羽。","why":"the feather is the part that makes the arrow fly straight, so the effect is named by the very act it serves.","whyCN":"羽毛正是让箭飞得笔直的那一部分，于是这一部件用它服务的那个动作来命名。"}],"etymology":{"intro":{"en":"Flight comes straight from Old English flyht, an action noun made from the strong verb fleogan 'to fly' plus the suffix -t. The family is Germanic, not Latin.","cn":"flight 直接来自古英语 flyht，是由强动词 fleogan「飞」加后缀 -t 构成的动作名词；整个词族属日耳曼语，与拉丁语无关。"},"items":[{"era":"OLD ENGLISH FLEOGAN","en":"Fleogan was the everyday verb 'to fly', a strong verb of the second class, and it is the direct ancestor of modern fly.","cn":"fleogan 是日常表示「飞」的动词，属第二类强动词，是现代 fly 的直接祖先。"},{"era":"SUFFIX -T","en":"Old English formed action nouns by adding -t to a verb stem, as in gift from giefan and weight from wegan; flyht follows the same pattern.","cn":"古英语在动词词干后加 -t 构成动作名词，如 gift 来自 giefan、weight 来自 wegan；flyht 遵循同一模式。"},{"era":"OLD ENGLISH FLYHT","en":"Flyht meant both the act of flying and a flying group, and it already carried the sense of fleeing from an enemy.","cn":"flyht 既指飞行的动作，也指飞行的群体，并且已经带有「逃避敌人」的意思。"},{"era":"MIDDLE ENGLISH","en":"Middle English flight kept the noun while the verb became fly; the staircase sense appears in the record later, formed on the image of a rising run of steps.","cn":"中古英语保留了名词 flight，动词则演变为 fly；楼梯义在文献中出现较晚，建立在「一级级上升」的意象上。"},{"era":"GERMANIC COGNATES","en":"German Flug 'flight' and Dutch vlucht are built from the same verb with the same suffix, which confirms the pattern rather than any Latin source.","cn":"德语 Flug「飞行」与荷兰语 vlucht 由同一动词加同一后缀构成，这证实了该构词模式，而非任何拉丁来源。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertain (pre-Germanic only): the deeper Indo-European root behind fleogan is a reconstruction, and the arrow-feather sense has no firm first date.","cn":"来源不确定（仅限日耳曼语之前）：fleogan 背后更早的印欧词根属重构形式，箭羽义的可靠首见年代亦不可考。"}]},"similar":{"note":{"en":"Group one holds words that resemble flight in spelling or sound but mostly belong to other roots; group two holds the travel and airborne words that overlap with one or another of its senses.","cn":"第一组是拼写或读音近似、但多数属于其他词根的词；第二组是在某个义项上与 flight 重叠的旅行与空中词汇。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fright","ipa":"/fraɪt/","tag":"different root","definition":"Sudden fear; from Old English fyrhto, a noun of fear, with no connection to flying and no shared root with flight.","definitionCN":"指突如其来的恐惧；来自古英语 fyrhto「恐惧」，与飞行无关，也与 flight 不同词根。"},{"word":"fleet","ipa":"/fliːt/","tag":"different root","definition":"A group of ships, from Old English flēot, tied to flēotan 'to float'; the adjective fleet 'fast' is a separate Norse borrowing, so neither is kin to flight.","definitionCN":"指船队，来自古英语 flēot，与 flēotan「漂浮」相关；形容词 fleet「快速」另从古诺斯语借入，二者都不是 flight 的同源词。"},{"word":"flighty","ipa":"/ˈflaɪti/","tag":"same root, different branch","definition":"Built on flight plus -y, originally 'given to flight', hence fickle or frivolous; it shares the root but describes temperament.","definitionCN":"由 flight 加 -y 构成，本义为「爱飞的」，引申为轻浮善变；词根相同，但描述的是性情。"},{"word":"fledge","ipa":"/fledʒ/","tag":"related, uncertain detail","definition":"To grow feathers fit for flight, from Old English -flycge 'fit to fly'; it belongs to the same flying family, though the exact link to fleogan is not settled.","definitionCN":"指长出适合飞行的羽毛，来自古英语 -flycge「适合飞的」；属于同一「飞」词族，但它与 fleogan 的确切关系尚无定论。"}]},{"heading":"NEAR MEANING","entries":[{"word":"journey","ipa":"/ˈdʒɜːni/","tag":"general trip","definition":"A travel from one place to another by any means; flight is one kind of journey, limited to the air and to a single scheduled leg.","definitionCN":"指以任何方式从一地到另一地的旅行；flight 是其中一种，限于空中且指单个航段。"},{"word":"voyage","ipa":"/ˈvɔɪɪdʒ/","tag":"long sea travel","definition":"A long journey, especially by sea or into space; it stresses distance and endurance rather than the act of flying.","definitionCN":"指长途旅行，尤指海上或太空航行；强调距离与耐力，而非飞行动作。"},{"word":"soar","ipa":"/sɔː/","tag":"verb of gliding high","definition":"To fly without flapping, riding rising air; it names one style of flight rather than flight as a category.","definitionCN":"指不扇翅、借上升气流滑翔高飞；它命名的是飞行的一种方式，而非飞行这个类别。"},{"word":"escape","ipa":"/ɪˈskeɪp/","tag":"getting away","definition":"The act of getting free from confinement or danger; it overlaps with flight in the sense of fleeing but says nothing about wings.","definitionCN":"指摆脱拘禁或危险；在「逃跑」义上与 flight 重叠，但不含翅膀的意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real cognates and real idioms, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的同源词与真实习语，而非编造的顺口溜。"},"normal":[{"en":"fleogan 'to fly' + -t: the act noun is built straight from the verb, exactly as gift is built on give.","cn":"fleogan「飞」+ -t：动作名词直接从动词构成，正如 gift 由 give 构成。"},{"en":"German Flug and Dutch vlucht repeat the same verb-plus-suffix pattern, which fixes the shape of the word.","cn":"德语 Flug 与荷兰语 vlucht 重复了同一套「动词加后缀」的模式，固定了这个词的形状。"},{"en":"The staircase sense keeps the shape of the core image: a series climbing, step after step.","cn":"楼梯义保留了核心意象的形状：一级接一级地向上攀升。"},{"en":"put to flight means to make someone fly away, and take flight means to leave the ground or to run.","cn":"put to flight 意为使人飞逃，take flight 意为离地起飞或逃走。"},{"en":"The family runs fly, flight, flighty, flightless, flighted.","cn":"同族词包括 fly、flight、flighty、flightless、flighted。"}],"abstract":[{"en":"Picture a spiral staircase seen from above: each step is one beat of a wing.","cn":"想象从上方俯瞰一道螺旋楼梯：每一级台阶就是一次振翅。"},{"en":"Picture an arrow's feather slicing the air, correcting the shaft with every wobble.","cn":"想象箭尾的羽毛切开空气，每一次晃动都被它矫正。"},{"en":"Picture a line of geese at dusk, one continuous stroke drawn across the sky.","cn":"想象黄昏时一列大雁，在天幕上画出一道连续的笔画。"}]},"examples":[{"en":"The engineer traced the flight of the ball with a slow-motion camera.","cn":"工程师用慢动作摄影机追踪球的飞行轨迹。"},{"en":"Bad weather forced the airline to cancel every flight before noon.","cn":"恶劣天气迫使航空公司在中午前取消了所有航班。"},{"en":"A flight of swallows passed low over the harvested field.","cn":"一群燕子低低掠过收割后的田野。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「弗莱特」——像滑过天空的一道亮线，一掠而过 → 飞行；再想那段楼梯，也是一级级往上「飞」。","word":"flight"},"root":"古英语 flyht「飞行、飞行的群体」，由 fleogan「飞」（现代 fly 的祖先）+ 动作名词后缀 -t 构成，日耳曼语族，与德语 Flug、荷兰语 vlucht 同型；fleogan 更早的印欧词根属重构形式。","sensesIntro":{"en":"All eight senses hang on one movement: something leaves the ground and travels a line through air. Counting that movement gives a flight number, grouping it gives a flock, copying it on the ground gives stairs, fleeing gives escape, and the line it draws gives the trajectory and the feather that steadies it.","cn":"八个义项都挂在同一个动作上：某物离地，在空中走出一条线。把这一动作计数，就有航班号；把做出它的群体归拢，就有鸟群；让它在土地上复制，就有楼梯；用它来逃离，就有逃跑；把那条线取下来，就有弹道，也有让箭沿线的箭羽。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body leaving the ground and drawing a line through the air.","cn":"核心意象：一个身体离地，在空中划出一道线。"},"chain":["LEAVE THE GROUND","MOVE THROUGH AIR","COUNT ONE TRIP","GROUP ON THE WING","RUN FROM DANGER","TRACE THE LINE"],"branches":[{"senses":"01 · 02","en":"THE ACTION ITSELF: flying, then one finished act of it counted as a scheduled trip.","cn":"动作本身：先有飞行，再把一次完成的飞行计作一个班次。"},{"senses":"03 · 08","en":"WHAT CARRIES THE MOTION: the flock that flies and the feather that keeps the arrow flying true.","cn":"承载动作之物：飞行的鸟群，以及让箭飞直的羽毛。"},{"senses":"04","en":"RISING IN PLACE: a run of steps repeats the climb without any air.","cn":"原地上升：一串台阶在没有空气的地方重复了攀爬。"},{"senses":"05","en":"FLYING AWAY: panic turns the same noun into escape.","cn":"飞离：惊慌把同一个名词变成逃跑。"},{"senses":"06 · 07","en":"THE DRAWN LINE: a projectile follows it literally, a daydream follows it in the mind.","cn":"画出的线：抛射体在实处沿着它，白日梦在心上沿着它。"}]},"affixes":{"intro":{"en":"Flight reads as two pieces: the Germanic verb stem for flying, and an old action-noun suffix. Everything else in the family is built by adding English endings to this noun.","cn":"flight 可以拆成两段：表「飞」的日耳曼动词词干，以及一个古老的动作名词后缀；词族中其余的词都是在这个名词上再加英语词尾构成的。"},"latinIntro":{"en":"There is no Latin entry to give: flight is Germanic throughout, and its cognates are German Flug and Dutch vlucht, not any Latin noun.","cn":"这里没有拉丁词形可列：flight 全程属日耳曼语，同源词是德语 Flug 与荷兰语 vlucht，而非任何拉丁名词。"},"items":[{"word":"fly-","structure":"fleogan (Old English strong verb, class II)","meaning":"to move through the air on wings","meaningCN":"振翅在空中移动","example":"The stem supplies the bare act of flying.","exampleCN":"这个词干提供「飞」这一纯粹的动作。"},{"word":"-t","structure":"-t (Old English action-noun suffix, as in gift, weight)","meaning":"the act or result of doing the verb","meaningCN":"动词所指动作或其结果","example":"Add -t to the verb and the flying becomes a thing.","exampleCN":"在动词后加 -t，飞行就变成一件可以指称的事。"},{"word":"flight","structure":"fleogan + -t","meaning":"the act of flying; a flying group; a fleeing","meaningCN":"飞行；飞行的群体；逃跑","example":"Flight is recorded in Old English as flyht.","exampleCN":"flight 在古英语中写作 flyht。"},{"word":"flighty","structure":"flight + -y","meaning":"given to flight, hence fickle","meaningCN":"爱飞的，引申为轻浮善变的","example":"A flighty person is one whose attention keeps taking off.","exampleCN":"flighty 的人，注意力总在起飞。"},{"word":"flighted","structure":"flight + -ed","meaning":"fitted with feathers for flight","meaningCN":"装有飞行用羽毛的","example":"A flighted arrow carries its own stabiliser.","exampleCN":"装有箭羽的箭自带稳定器。"},{"word":"flightless","structure":"flight + -less (Old English -lēas)","meaning":"without the ability to fly","meaningCN":"没有飞行能力的","example":"The suffix removes exactly the capacity the noun names.","exampleCN":"这个后缀恰好去掉了名词所指的那种能力。"},{"word":"flight path","structure":"flight + path (compound noun)","meaning":"the route or line along which something flies","meaningCN":"飞行路线；弹道","example":"Controllers cleared the aircraft along a new flight path.","exampleCN":"管制员让这架飞机沿一条新飞行路线通行。"},{"word":"flight deck","structure":"flight + deck (compound noun)","meaning":"the cockpit, or the deck where aircraft take off","meaningCN":"驾驶舱；（航母）飞行甲板","example":"The flight deck is the part of the ship given to flying.","exampleCN":"飞行甲板是舰上专门交给飞行使用的那部分。"},{"word":"in flight","structure":"in + flight (prepositional phrase)","meaning":"while airborne, before landing","meaningCN":"在飞行途中","example":"The missile was destroyed in flight.","exampleCN":"导弹在飞行途中被摧毁。"}],"latinEntries":[]}},{"word":"flightless","ipa_uk":"/ˈflaɪtləs/","ipa_us":"/ˈflaɪtləs/","definition_zh":"不能飞的（鸟）；无翅或翅退化的（昆虫）；家养后不再飞的禽类；演化中失去飞行能力的；比喻无法起步的","definition_en":"lacking the ability to fly, whether because of anatomy, domestication, or evolutionary loss, and figuratively unable to get off the ground","core_image":"一只企鹅站在冰缘，鳍状的前肢垂在身侧，身后是它走不进去的天空","scene":"冰缘上，一群黑白相间的大鸟摇摇摆摆地朝繁殖群走去，它们的鳍肢只能划水，不能托起身体。 At the edge of the ice, the flightless birds shuffled inland toward their colony.","sceneCN":"这里 flightless 是「不能飞的」（第 1 个义项：身体结构上不具备飞行能力的鸟类）；句意为在冰缘，这些不能飞的鸟摇摇摆摆地朝内陆的繁殖群走去。","pos":[{"tag":"adj.","zh":"不能飞的；无翅的；（昆虫）无飞行阶段的"}],"collocations":[{"phrase":"flightless bird","zh":"不能飞的鸟"},{"phrase":"flightless insect","zh":"无翅或翅退化的昆虫"},{"phrase":"flightless species","zh":"不会飞的物种"},{"phrase":"flightless breed","zh":"不会飞的家养品种"},{"phrase":"flightless condition","zh":"无飞行能力的状态"},{"phrase":"flightless island bird","zh":"岛屿上的不会飞的鸟"}],"forms":[{"label":"原级","form":"flightless"},{"label":"比较级","form":"more flightless"},{"label":"最高级","form":"most flightless"},{"label":"派生名词","form":"flightlessness（不能飞的状态）"},{"label":"派生副词","form":"flightlessly（以不能飞的方式，罕用）"},{"label":"基词","form":"flight（飞行）"}],"derivatives":[{"word":"flightlessness","pos":"n.","zh":"不能飞的状态；无飞行能力"},{"word":"flightlessly","pos":"adv.","zh":"以不能飞的方式（罕用）"},{"word":"flight","pos":"n.","zh":"飞行；航班"},{"word":"fly","pos":"v.","zh":"飞；飞行"}],"senses":[{"no":"01","title":"Birds That Cannot Fly","titleCN":"不能飞的鸟（如企鹅）","definition":"describing birds whose wings or flippers cannot lift them into the air","definitionCN":"描述翅膀或鳍肢无法把身体托入空中的鸟类","example":"Penguins are flightless, but their flippers make them fast swimmers.","exampleCN":"企鹅不能飞，但它们的鳍肢使它们成为游泳好手。","why":"flight names the capacity, and -less removes it; the word simply says the bird has no flight, without saying why.","whyCN":"flight 命名这种能力，-less 把它拿走；这个词只是说这种鸟没有飞行能力，并不解释原因。"},{"no":"02","title":"Insects Without Working Wings","titleCN":"无翅或翅退化的昆虫","definition":"used of insects that have no wings at all or only reduced, useless ones","definitionCN":"用于完全没有翅膀、或只有退化无用翅膀的昆虫","example":"Many beetles living in caves are flightless and blind.","exampleCN":"许多生活在洞穴里的甲虫既不能飞，也看不见。","why":"the suffix states an absence, so it applies to any insect that lacks the organ the noun presupposes.","whyCN":"这个后缀表示的是一种缺失，因此可用来指任何缺少名词所预设之器官的昆虫。"},{"no":"03","title":"Domesticated Breeds That No Longer Fly","titleCN":"家养后不再飞的禽类品种","definition":"used of farm breeds whose bodies have grown too heavy or too stubby to fly","definitionCN":"用于因身体过重或翅膀过短而无法飞行的家养品种","example":"The farm keeps a flightless duck breed for its eggs.","exampleCN":"这家农场养一种不会飞的鸭品种，取用它的蛋。","why":"domestication removes the need and then the ability, so the adjective marks a loss produced by husbandry rather than by nature.","whyCN":"驯化先取消需要，再取消能力，形容词因此标记的是饲养造成的丧失，而非自然造成的。"},{"no":"04","title":"Flight Lost in Evolution","titleCN":"演化中失去飞行能力的（岛屿鸟类）","definition":"used of species whose ancestors flew but whose isolated populations lost that ability","definitionCN":"用于祖先会飞、但孤立种群后来失去这种能力的物种","example":"Island rails became flightless within a few thousand years.","exampleCN":"岛屿上的秧鸡在几千年内就失去了飞行能力。","why":"on islands without predators, wings cost more than they earn, and the adjective records the outcome of that trade.","whyCN":"在没有捕食者的岛上，翅膀的代价高于收益，这个形容词记录的正是这笔交易的结果。"},{"no":"05","title":"The Island Niche of Lost Flight","titleCN":"岛屿生态中「不能飞」的生态位","definition":"the ecological role filled by species that give up flight on predator-free islands","definitionCN":"在无捕食者岛屿上放弃飞行的物种所占据的生态角色","example":"Flightless grazers on remote islands often replace large herbivores.","exampleCN":"偏远岛屿上不能飞的食草动物常替代大型植食者。","why":"the adjective becomes a niche label because the loss of flight reshapes how a species feeds and breeds.","whyCN":"这个形容词之所以成为生态位标签，是因为失去飞行会重塑一个物种取食与繁殖的方式。"},{"no":"06","title":"Figurative: Unable to Take Off","titleCN":"比喻：无法起飞、被束缚的","definition":"figurative, describing a plan, career or person unable to get started or to move freely","definitionCN":"比喻用法，指计划、事业或人无法起步、无法自由行动","example":"The project was flightless from the start, short of funds and staff.","exampleCN":"这个项目从一开始就无法起飞，缺钱也缺人。","why":"the metaphor keeps the core image intact: wings may exist, but nothing lifts, and the ground holds.","whyCN":"这个比喻完整保留了核心意象：翅膀也许在，但没有东西能把它托起，地面牢牢拉住。"},{"no":"07","title":"The Wingless Stage of an Insect","titleCN":"昆虫的无翅阶段（若虫、工蚁）","definition":"used of a stage in an insect's life, or a caste, that never develops wings","definitionCN":"用于昆虫一生中某个从不长出翅膀的阶段或品级","example":"Worker ants are a flightless caste within a winged species.","exampleCN":"工蚁是一个会飞的物种内部不能飞的品级。","why":"the species may fly, yet the stage does not, and the adjective marks the stage rather than the whole animal.","whyCN":"物种会飞，这个阶段却不会；形容词标记的是阶段，而不是整个动物。"},{"no":"08","title":"Not Involving Flight at All","titleCN":"字面：无需飞行的（设备、训练语境）","definition":"used of equipment, drills or training that involve no flying at all","definitionCN":"用于完全不涉及飞行的设备、演练或训练","example":"Ground crews practise on a flightless simulator before touching a real aircraft.","exampleCN":"地勤人员在接触真机之前，先在不会飞的模拟器上练习。","why":"here the suffix negates the activity rather than a bird's anatomy, so the adjective simply means without any flying.","whyCN":"这里的后缀否定的是活动本身，而不是鸟的身体构造，因此形容词只表示「不涉及任何飞行」。"}],"etymology":{"intro":{"en":"Flightless is an English compound: flight, from Old English flyht, plus -less, from Old English -lēas 'free from, lacking'. It names a body that lacks the flight the base word presupposes.","cn":"flightless 是一个英语复合词：flight（来自古英语 flyht）加 -less（古英语 -lēas「没有、免于」）。它命名的是一个缺少基词所预设之飞行能力的身体。"},"items":[{"era":"OLD ENGLISH FLYHT","en":"Flyht is the action noun from fleogan 'to fly' plus -t; it names both the act and the group that performs it.","cn":"flyht 是由 fleogan「飞」加 -t 构成的动作名词，既指动作，也指做出该动作的群体。"},{"era":"SUFFIX -LĒAS","en":"Old English -lēas meant 'free from, without', and it already formed adjectives such as slǣplēas 'sleepless'.","cn":"古英语 -lēas 意为「没有、免于」，当时就已构成 slǣplēas「不眠的」一类形容词。"},{"era":"GERMANIC -LOS","en":"German -los and Dutch -loos are the same suffix, so the pattern is Germanic rather than borrowed from Latin.","cn":"德语 -los 与荷兰语 -loos 是同一后缀，可见这一构词模式属日耳曼语，而非从拉丁语借入。"},{"era":"ENGLISH FLIGHTLESS","en":"The adjective appears in English only in the modern period, once natural history needed a plain word for birds that cannot fly.","cn":"这个形容词到近代英语才出现，是博物学需要一个朴素的说法来描述不会飞的鸟时造出来的。"},{"era":"PARALLEL FORMS","en":"The same construction yields harmless, sleepless, weightless and wingless, all built on a noun plus -less rather than on a Latin prefix.","cn":"同一构词法造出了 harmless、sleepless、weightless、wingless，全都建立在「名词 + -less」上，而不是拉丁前缀。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertain: the pre-Germanic origin of -lēas is a reconstruction, and no firm first citation is available for the adjective flightless.","cn":"来源不确定：-lēas 在日耳曼语之前的来源属重构形式，形容词 flightless 也没有可靠的最早书证。"}]},"similar":{"note":{"en":"Group one holds the base word and the -less formations that look like it; group two holds adjectives that describe the same incapacity from other angles.","cn":"第一组是基词以及外形相似的 -less 构词；第二组是从别的角度描述同一种「不能飞」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"flight","ipa":"/flaɪt/","tag":"same root, base word","definition":"The noun from which flightless is built; it names the capacity itself, while the -less form names its absence.","definitionCN":"flightless 所由构成的基词；它命名能力本身，而 -less 形式命名的是能力的缺失。"},{"word":"flighty","ipa":"/ˈflaɪti/","tag":"same root, different suffix","definition":"Flight plus -y 'given to', meaning fickle; the suffix adds a habit rather than removing a capacity, so the sense runs the other way.","definitionCN":"flight 加 -y「倾向于」，意为轻浮善变；后缀添加的是一种习性而非移除一种能力，词义方向正好相反。"},{"word":"sightless","ipa":"/ˈsaɪtləs/","tag":"different root, same suffix","definition":"Built on sight plus -less; it shares only the suffix, since sight comes from Old English gesiht and has nothing to do with flying.","definitionCN":"由 sight 加 -less 构成；只共用后缀，sight 来自古英语 gesiht，与飞行毫无关系。"},{"word":"weightless","ipa":"/ˈweɪtləs/","tag":"different root, same suffix","definition":"Built on weight plus -less; the shape is identical but the base belongs to the weighing family, not the flying one.","definitionCN":"由 weight 加 -less 构成；外形完全相同，但基词属于「称重」词族，而非「飞行」词族。"}]},{"heading":"NEAR MEANING","entries":[{"word":"wingless","ipa":"/ˈwɪŋləs/","tag":"anatomical absence","definition":"Lacking wings outright; it names the missing organ, while flightless names the missing ability, which may survive in a wingless body.","definitionCN":"指根本没有翅膀；它命名缺失的器官，而 flightless 命名缺失的能力，后者在没有翅膀的身体上也可能谈得上。"},{"word":"grounded","ipa":"/ˈɡraʊndɪd/","tag":"kept on the ground","definition":"Kept from flying by an outside order or circumstance, as a grounded aircraft; the incapacity is temporary and imposed.","definitionCN":"因外部命令或情况被禁止飞行，如停飞的飞机；这种不能飞是暂时的、外加的。"},{"word":"earthbound","ipa":"/ˈɜːθbaʊnd/","tag":"bound to the ground","definition":"Confined to the ground by nature or circumstance; it is broader and more literary than flightless.","definitionCN":"因天性或处境被限制在地面；比 flightless 更宽泛，也更有文学色彩。"},{"word":"nonflying","ipa":"/ˌnɒnˈflaɪɪŋ/","tag":"plain negative","definition":"A neutral technical negative used of species or stages that do not fly; it states the fact without implying loss.","definitionCN":"中性的技术性否定词，用于不飞的物种或阶段；只陈述事实，不含「丧失」之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the base word, the real suffix and the real parallel formations, not invented rhymes.","cn":"正常联想：基词、真实后缀与真实平行构词，而非编造的顺口溜。"},"normal":[{"en":"flight + -less: the suffix takes away exactly what the noun supplies.","cn":"flight + -less：后缀拿走的正是名词提供的那样东西。"},{"en":"German -los and Dutch -loos prove the suffix is Germanic, not Latin.","cn":"德语 -los 与荷兰语 -loos 证明这个后缀属日耳曼语，而非拉丁语。"},{"en":"harmless, sleepless, weightless, wingless: one pattern, many nouns.","cn":"harmless、sleepless、weightless、wingless：一个模式，多个名词。"},{"en":"Penguins are the standard example: flippers for swimming, nothing for lifting.","cn":"企鹅是标准例子：鳍肢用来游泳，没有东西用来升空。"},{"en":"On islands the word becomes an ecological label, because loss of flight changes how a species lives.","cn":"在岛屿上这个词变成生态学标签，因为失去飞行会改变一个物种的生活方式。"}],"abstract":[{"en":"Picture a kite with a perfect frame and no wind beneath it.","cn":"想象一只骨架完好、身下却没有风的风筝。"},{"en":"Picture a staircase whose top step ends at a locked door.","cn":"想象一道楼梯，最高一级尽头是一扇锁住的门。"},{"en":"Picture a pair of wings folded neatly and never opened again.","cn":"想象一对折得整整齐齐、再也不展开的翅膀。"}]},"examples":[{"en":"New Zealand once held dozens of flightless bird species.","cn":"新西兰曾经有数十种不会飞的鸟类。"},{"en":"The beetle's flightless females look almost like larvae.","cn":"这种甲虫不能飞的雌性看起来几乎像幼虫。"},{"en":"Without wind, the design remained flightless no matter how light it was.","cn":"没有风，这个设计无论多轻都无法起飞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「弗莱特莱斯」——翅膀像被剪掉一样轻，却怎么也升不起来 → 不能飞的。","word":"flightless"},"root":"flight（古英语 flyht，fleogan「飞」+ -t）+ -less（古英语 -lēas「缺乏、没有」，与德语 -los、荷兰语 -loos 同源）；-lēas 更早的来源属重构形式，形容词本身首见年代不确定。","sensesIntro":{"en":"The eight senses all deny one capacity. The denial can come from anatomy, from a wingless stage, from breeding, from evolution on islands, from the niche that loss creates, from a metaphor about plans, or from a context where no flying is involved at all.","cn":"八个义项都在否定同一种能力。这种否定可能来自身体构造、无翅阶段、人工饲养、岛屿演化、丧失所造就的生态位、关于计划的比喻，或来自一个根本不涉及飞行的语境。"},"semanticMap":{"core":{"en":"CORE IMAGE: wings present or absent, and the air never entered.","cn":"核心意象：翅膀也许在、也许不在，但那片天空始终没有被进入。"},"chain":["NO FLIGHT","BODY TOO HEAVY","WINGS REDUCED","ISLAND ISOLATION","PLAN THAT CANNOT START","GROUND ONLY"],"branches":[{"senses":"01 · 02","en":"ANATOMY: the bird or insect simply lacks the organ or the power.","cn":"构造：鸟或昆虫干脆缺少器官或力量。"},{"senses":"03 · 07","en":"LOSS BY CIRCUMSTANCE: breeding makes the body heavy, a caste or stage never grows wings.","cn":"处境造成的丧失：饲养让身体变重，某个品级或阶段则从不长翅。"},{"senses":"04 · 05","en":"EVOLUTION ON ISLANDS: flight is traded away and the loss becomes a way of life.","cn":"岛屿演化：飞行被交换掉，丧失本身成了一种生活方式。"},{"senses":"06","en":"METAPHOR: plans and people can also fail to lift off.","cn":"比喻：计划和人同样可能升不起来。"},{"senses":"08","en":"NO FLYING INVOLVED: the suffix can negate the activity, not the animal.","cn":"不涉及飞行：后缀可以否定活动，而不是否定动物。"}]},"affixes":{"intro":{"en":"Flightless is transparent: a Germanic noun for flying, plus a Germanic suffix of deprivation. The interest lies in how far that deprivation can be stretched.","cn":"flightless 的结构一目了然：一个表「飞」的日耳曼名词，加一个表「剥夺」的日耳曼后缀；值得玩味的是这种剥夺能被拉伸到多远。"},"latinIntro":{"en":"No Latin entry applies here: both halves are Germanic, and the nearest Latin idea, 'without', is expressed by a different prefix entirely.","cn":"这里没有适用的拉丁词形：两半都属日耳曼语，而拉丁语中「没有」这一概念完全由另一个前缀表达。"},"items":[{"word":"fly-","structure":"fleogan (Old English strong verb, class II)","meaning":"to move through the air on wings","meaningCN":"振翅在空中移动","example":"The base verb names the capacity that will be denied.","exampleCN":"基词动词命名的是后来被否定的那种能力。"},{"word":"-t","structure":"-t (Old English action-noun suffix)","meaning":"the act of doing the verb","meaningCN":"动词所指的动作","example":"Flight is the act, not the actor.","exampleCN":"flight 指动作，不指施动者。"},{"word":"flight","structure":"fleogan + -t","meaning":"the act of flying","meaningCN":"飞行","example":"The noun must exist before it can be denied.","exampleCN":"名词必须先存在，才谈得上被否定。"},{"word":"-less","structure":"-lēas (Old English adjective suffix)","meaning":"without, free from","meaningCN":"没有；免于","example":"The suffix turns a possession into an absence.","exampleCN":"这个后缀把「拥有」变成「没有」。"},{"word":"flightless","structure":"flight + -less","meaning":"without the ability to fly","meaningCN":"没有飞行能力的","example":"The adjective is a plain statement of absence.","exampleCN":"这个形容词是对缺失的朴素陈述。"},{"word":"flightlessness","structure":"flightless + -ness","meaning":"the state of being unable to fly","meaningCN":"不能飞的状态","example":"Flightlessness evolved repeatedly on isolated islands.","exampleCN":"不能飞的状态在孤立岛屿上反复演化出来。"},{"word":"flightlessly","structure":"flightless + -ly","meaning":"in a manner that involves no flying","meaningCN":"以不飞的方式","example":"The adverb is rare and mostly technical.","exampleCN":"这个副词罕用，多见于技术文字。"},{"word":"wingless","structure":"wing + -less","meaning":"having no wings at all","meaningCN":"完全没有翅膀的","example":"Wingless names the organ, flightless names the power.","exampleCN":"wingless 指器官，flightless 指能力。"},{"word":"sleepless","structure":"sleep + -less","meaning":"without sleep","meaningCN":"不眠的","example":"The same suffix produced slǣplēas in Old English.","exampleCN":"同一后缀在古英语中造出了 slǣplēas。"},{"word":"flight path","structure":"flight + path (compound noun)","meaning":"the line along which a flying thing travels","meaningCN":"飞行路线","example":"A flightless bird has no flight path to record.","exampleCN":"不会飞的鸟没有飞行路线可记录。"}],"latinEntries":[]}},{"word":"migration route","ipa_uk":"/maɪˈɡreɪʃn ruːt/","ipa_us":"/maɪˈɡreɪʃən ruːt/","definition_zh":"候鸟迁徙路线；季节性往返的路径；由停歇地串成的路线；人类迁徙路径；动物廊道与鱼类洄游路线；引申的既定航线","definition_en":"the path followed by animals, people, aircraft or data when they move from one region or system to another, especially the seasonal path of migratory species","core_image":"一张铺在大陆上的虚线，从北方的繁殖地出发，绕过山脉，一连串小点串起湖泊与河口，最后落到南方的越冬地","scene":"湿地保护站里，研究者把一枚轻巧的定位器系在大雁背上，屏幕上随即出现一条跨越大陆的虚线。 Researchers fitted the geese with trackers to map the migration route they follow each autumn.","sceneCN":"这里 migration route 是「候鸟迁徙路线」（第 1 个义项：迁飞通道，即候鸟世代沿用的空中走廊）；句意为研究者给大雁装上追踪器，以绘制它们每年秋天沿用的迁徙路线。","pos":[{"tag":"n.","zh":"迁徙路线（多词短语，可数，复数 migration routes；作主语、宾语或介词宾语）"}],"collocations":[{"phrase":"bird migration route","zh":"鸟类迁徙路线"},{"phrase":"seasonal migration route","zh":"季节性迁徙路线"},{"phrase":"along the migration route","zh":"沿迁徙路线"},{"phrase":"migration route map","zh":"迁徙路线图"},{"phrase":"human migration route","zh":"人类迁徙路径"},{"phrase":"fish migration route","zh":"鱼类洄游路线"},{"phrase":"data migration route","zh":"数据迁移路径"}],"forms":[{"label":"原形","form":"migration route"},{"label":"复数","form":"migration routes"},{"label":"同义术语（鸟类）","form":"flyway（迁飞通道）"},{"label":"相关形容词","form":"migratory（迁徙的）"},{"label":"相关动词","form":"migrate（迁徙）"},{"label":"相关名词","form":"migration（迁徙）"}],"derivatives":[{"word":"migrate","pos":"v.","zh":"迁徙；洄游；迁移"},{"word":"migration","pos":"n.","zh":"迁徙；移居"},{"word":"migratory","pos":"adj.","zh":"迁徙的；有迁居习惯的"},{"word":"route","pos":"n.","zh":"路线；航线"},{"word":"reroute","pos":"v.","zh":"改变路线；改道"}],"senses":[{"no":"01","title":"A Flyway for Migratory Birds","titleCN":"候鸟迁飞通道","definition":"the broad corridor that migratory birds follow between breeding and wintering grounds","definitionCN":"候鸟在繁殖地与越冬地之间循行的宽阔空中走廊","example":"The East Asian flyway is a migration route used by millions of waterbirds.","exampleCN":"东亚迁飞通道是一条被数以百万计水鸟使用的迁徙路线。","why":"migration is the seasonal move and route is the line laid down for it, so the phrase names the corridor as a piece of geography.","whyCN":"migration 是季节性的移动，route 是为它铺下的线，这个短语因此把这条走廊当作一处地理事物来命名。"},{"no":"02","title":"The Specific Seasonal Path","titleCN":"季节性往返的具体路径","definition":"the particular track a population takes in one season and reverses in the next","definitionCN":"某一族群在一个季节走、下一季再反向走回的那条具体路径","example":"Satellite tags showed a migration route that turns north only in spring.","exampleCN":"卫星标记显示出一条只在春季才折向北行的迁徙路线。","why":"the same line serves two journeys in opposite directions, so route stresses the fixed track rather than the movement.","whyCN":"同一条线要服务两次方向相反的旅程，route 因此强调的是固定轨道，而不是移动本身。"},{"no":"03","title":"A Chain of Stopover Sites","titleCN":"由停歇地串成的路线","definition":"the sequence of feeding and resting sites that together make the journey possible","definitionCN":"由取食地与休息地依次串起、使整段旅程得以完成的序列","example":"Each wetland along the migration route is a link the birds cannot skip.","exampleCN":"迁徙路线上的每一片湿地都是鸟群不能跳过的一环。","why":"a long flight is impossible without fuel stops, so the route is understood as a chain of places rather than a line on a map.","whyCN":"长途飞行没有补给点就无从完成，于是这条路线被理解成一串地点，而不是地图上的一根线。"},{"no":"04","title":"The Path of Human Peoples","titleCN":"人类迁徙路径（历史与人口学）","definition":"the corridor along which a human population spread from one region to another","definitionCN":"某个人群从一地区扩散到另一地区时所经的走廊","example":"Linguists and geneticists traced the same migration route across the steppe.","exampleCN":"语言学家与遗传学家在草原上追溯出同一条人类迁徙路径。","why":"people move the way birds do, only once, so the phrase transfers cleanly from season to prehistory.","whyCN":"人像鸟一样移动，只是不再回头，这个短语于是从季节平移到了史前。"},{"no":"05","title":"A Wildlife Corridor","titleCN":"野生动物迁徙廊道","definition":"a strip of habitat that lets animals move between larger patches of suitable land","definitionCN":"让动物在较大片适宜栖息地之间移动的一条带状生境","example":"The reserve protects a migration route for elk between summer and winter range.","exampleCN":"保护区保护着一条麋鹿在夏季与冬季牧场之间往返的迁徙廊道。","why":"route here is a planning term: what matters is connectivity, not a single species or season.","whyCN":"这里的 route 是规划术语：重要的是连通性，而不是某一个物种或某一个季节。"},{"no":"06","title":"The Course of Fish Migration","titleCN":"鱼类洄游路线","definition":"the path fish follow between spawning, feeding and overwintering waters","definitionCN":"鱼类在产卵、索饵与越冬水域之间循行的路径","example":"Dams cut the migration route of salmon returning to their natal stream.","exampleCN":"水坝截断了鲑鱼返回出生溪流的洄游路线。","why":"fish migrate in water as birds do in air, and English reuses the same phrase rather than coining a separate one.","whyCN":"鱼在水里迁徙，正如鸟在空中迁徙，英语沿用同一短语，而不另造新词。"},{"no":"07","title":"An Established Air or Sea Lane","titleCN":"既定航线（航空、航运引申）","definition":"a fixed air or sea lane assigned to regular traffic","definitionCN":"分配给定期交通的固定空中或海上航道","example":"The airline shifted its migration route for the season to avoid storms.","exampleCN":"这家航空公司为避开风暴而调整了当季的既定航线。","why":"once aircraft and ships move on schedules, they too follow set lines, and the phrase extends from birds to traffic.","whyCN":"飞机与船只一旦按班期移动，也走固定的线，短语就从鸟群延伸到交通。"},{"no":"08","title":"The Path Data Takes in a Move","titleCN":"数据迁移路径（信息技术引申）","definition":"the sequence of systems and transfers through which data moves during a platform change","definitionCN":"平台更换期间数据所经的系统与转接序列","example":"The team documented every hop on the migration route from the old server.","exampleCN":"团队记录了从旧服务器迁出时数据路径上的每一跳。","why":"data is imagined as a population leaving one home for another, so the same phrase covers a technical move.","whyCN":"数据被想象成一群离开旧居、迁往新居的生物，同一个短语因此也覆盖技术层面的搬迁。"}],"etymology":{"intro":{"en":"Migration route joins two words of entirely different descent. Migration is Latin, from migratio and the verb migrare 'to move, change abode'. Route is French, from Old French rute, from Latin rupta (via) 'a broken-open way', built on rumpere 'to break'. The two halves share no root.","cn":"migration route 由两个来源完全不同的词拼成。migration 属拉丁系，来自 migratio 与动词 migrare「迁移、迁居」；route 属法语系，来自古法语 rute，更早是拉丁 rupta (via)「破开的路」，由 rumpere「破开」构成。两半不同源。"},"items":[{"era":"LATIN MIGRARE","en":"Migrare meant 'to move from one place to settle in another'; its own earlier origin is uncertain, with no settled Indo-European root.","cn":"migrare 意为「从一处迁走、到另一处定居」；它自身更早的来源不确定，没有公认的印欧词根。"},{"era":"LATIN MIGRATIO","en":"Migratio is the third-declension noun of that verb, naming the act of moving or a change of residence.","cn":"migratio 是该动词的第三变格法名词，指迁移这一动作或住所的更换。"},{"era":"LATIN RUMPERE","en":"Rumpere meant 'to break, burst open'; its past participle ruptum supplies the element seen in rupture and interrupt.","cn":"rumpere 意为「破开、冲破」；其过去分词 ruptum 提供了 rupture 与 interrupt 中可见的那个成分。"},{"era":"LATIN RUPTA VIA","en":"Rupta (via) meant a way cut or broken open through terrain, and it passed into everyday speech for any opened road.","cn":"rupta (via) 指在地形中破开、开辟出来的一条路，后来泛指任何已开通的道路。"},{"era":"OLD FRENCH RUTE","en":"Old French shortened the Latin phrase to rute 'road, way', which English borrowed as route.","cn":"古法语把这一拉丁短语缩短为 rute「道路、路程」，英语借入后写作 route。"},{"era":"ENGLISH COMPOUND","en":"The compound migration route is modern English, formed once migration had become a technical term in zoology; the exact first date is uncertain.","cn":"复合词 migration route 属近代英语，是在 migration 成为动物学术语之后才组成的；确切首见年代不确定。"}]},"similar":{"note":{"en":"Group one separates the phrase from words that look close but stand in different relations to it; group two gives the specialist and general words that overlap with one sense or another.","cn":"第一组把这个短语与外形接近、但关系各不相同的词区分开；第二组给出在某个义项上与之重叠的专业词与一般词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"migration","ipa":"/maɪˈɡreɪʃn/","tag":"same base, one word","definition":"The single noun for the movement itself, without any route attached; it names the journey, not the line it follows.","definitionCN":"单指出移动本身的那个名词，不含路线；它命名旅程，而不是旅程所循的线。"},{"word":"immigration","ipa":"/ˌɪmɪˈɡreɪʃn/","tag":"same root, different prefix","definition":"In- 'into' plus migrare: movement into a country, seen from the receiving side; the root is shared, the direction is not.","definitionCN":"in-「进入」加 migrare：从接收一方看的入境移居；词根相同，方向不同。"},{"word":"ration","ipa":"/ˈræʃn/","tag":"different root","definition":"From Latin ratio 'reckoning', which has nothing to do with migrare; the resemblance is only in the ending, so the two are not kin.","definitionCN":"来自拉丁 ratio「计算」，与 migrare 无关；相似只在词尾，二者并非同源。"},{"word":"routine","ipa":"/ruːˈtiːn/","tag":"same root as route","definition":"French routine descends from route 'road', so it is kin to the second half of the phrase, not to migration.","definitionCN":"法语 routine 源自 route「道路」，因此与短语的后半同源，而与 migration 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flyway","ipa":"/ˈflaɪweɪ/","tag":"ornithological term","definition":"The standard term for a bird migration route, usually a broad corridor; narrower and more technical than the phrase.","definitionCN":"指鸟类迁徙路线的标准术语，通常是宽阔的走廊；比该短语更窄、更专业。"},{"word":"corridor","ipa":"/ˈkɒrɪdɔː/","tag":"conservation term","definition":"A strip of habitat linking two patches; it names the land itself, while migration route names the movement it serves.","definitionCN":"指连接两片栖息地的带状地带；它命名土地本身，而 migration route 命名它所服务的移动。"},{"word":"itinerary","ipa":"/aɪˈtɪnərəri/","tag":"planned list of places","definition":"A planned sequence of stops for a traveller; it is written for people, not inherited by animals.","definitionCN":"指为旅行者事先排定的停留顺序；它是为人类书写的，而不是动物世代沿用的。"},{"word":"passage","ipa":"/ˈpæsɪdʒ/","tag":"the act of passing","definition":"The act of going through or across; it stresses the crossing rather than the fixed line followed.","definitionCN":"指穿过或横越的动作；强调穿越本身，而非所循的固定路线。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin and French halves, the real technical term flyway, and the real places that make a route work.","cn":"正常联想：拉丁与法语的两半、真实术语 flyway，以及真正让一条路线成立的那些地点。"},"normal":[{"en":"migrare 'to move' gives migration; rupta via 'a broken-open way' gives route: two roots, one phrase.","cn":"migrare「迁移」给出 migration；rupta via「破开的路」给出 route：两个词根，一个短语。"},{"en":"Rupture and interrupt carry the same rupt- element as route, which is why route has nothing to do with migration's root.","cn":"rupture 与 interrupt 与 route 共用同一个 rupt- 成分，这正是 route 与 migration 词根无关的原因。"},{"en":"Ornithologists say flyway for the same thing; the phrase is the plain-language version.","cn":"鸟类学家把同一事物称作 flyway；这个短语是它的通俗说法。"},{"en":"A route is only real if the stopover wetlands are still there, which is why conservation works site by site.","cn":"只有中途湿地还在，路线才真正成立，所以保护工作要一处一处地做。"},{"en":"The family runs migrate, migration, migratory, route, reroute.","cn":"同族词包括 migrate、migration、migratory、route、reroute。"}],"abstract":[{"en":"Picture a dotted line laid over a continent, each dot a lake where the flock rests.","cn":"想象一条铺在大陆上的虚线，每个点都是鸟群歇脚的湖泊。"},{"en":"Picture an old road cut through a mountain pass, opened by breaking the rock.","cn":"想象一条穿过山口的老路，是靠破开岩石才开通的。"},{"en":"Picture two arrows on the same line, one pointing south in autumn and one north in spring.","cn":"想象同一条线上的两支箭头，一支秋天指南，一支春天指北。"}]},"examples":[{"en":"The delta lies on a major migration route for shorebirds.","cn":"这片三角洲位于水鸟的一条主要迁徙路线上。"},{"en":"Historians disagree about the migration route taken into the valley.","cn":"历史学家对进入该谷地所走的迁徙路径仍有分歧。"},{"en":"Engineers mapped a migration route for the records before shutting the old system down.","cn":"工程师在关停旧系统之前，为这些记录规划了一条迁移路径。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「迈格雷申 如特」——迈开步子（migra）沿着一条开出来的路（route）走 → 迁徙路线。","word":"migration route"},"root":"migration 来自拉丁 migratio，源自动词 migrare「迁移、迁居」，migrare 更早来源不确定；route 来自古法语 rute，源自拉丁 rupta (via)「破开的路」，出自 rumpere「破开」。两半不同源：migration 属 migrare 词族，route 属 rumpere 词族。","sensesIntro":{"en":"The eight senses all describe one line between two places. Birds make it seasonal, stopovers make it a chain, people make it historical, corridors make it a planning unit, fish make it watery, aircraft make it scheduled, and data makes it digital.","cn":"八个义项描述的都是两地之间的一条线。鸟把它变成季节性的，停歇地把它变成一串，人把它变成历史的，廊道把它变成规划单位，鱼把它带进水里，飞机把它变成班期，数据把它变成数字的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dotted line between a home and a far place, with resting points along it.","cn":"核心意象：家园与远方之间的一条虚线，线上分布着歇脚的点。"},"chain":["MOVE AWAY","FIXED LINE","SEASONAL RETURN","STOPOVER CHAIN","HUMAN SPREAD","NEW DOMAIN"],"branches":[{"senses":"01 · 02","en":"THE CORRIDOR: a broad flyway, and the exact track a population reverses each season.","cn":"走廊：一条宽阔的迁飞通道，以及某族群每季反向行走的确切轨迹。"},{"senses":"03","en":"THE CHAIN: the route is only as good as the wetlands strung along it.","cn":"链条：路线的好坏取决于串在它上面的湿地。"},{"senses":"04 · 05","en":"LAND AND PEOPLE: the same line read as prehistory or as conservation planning.","cn":"土地与人：同一条线，可读作史前史，也可读作保护规划。"},{"senses":"06","en":"WATER: fish follow the same shape under the surface.","cn":"水中：鱼在水面之下循着同一形状。"},{"senses":"07 · 08","en":"TRANSFER: scheduled traffic and migrating data both inherit the phrase.","cn":"转移：班期交通与迁移中的数据都继承了这个短语。"}]},"affixes":{"intro":{"en":"The phrase splits into four morphemes: a Latin verb of moving, a Latin noun suffix, a French noun for a road, and the Latin participle hidden inside it.","cn":"这个短语可拆成四个语素：一个表「迁移」的拉丁动词、一个拉丁名词后缀、一个表「道路」的法语名词，以及藏在它里面的拉丁分词。"},"latinIntro":{"en":"Latin migrare yields migratio and English migration; Latin rumpere yields ruptum and ruptura, and the phrase rupta via passed through French into English route.","cn":"拉丁 migrare 衍生 migratio 与英语 migration；拉丁 rumpere 衍生 ruptum 与 ruptura，而短语 rupta via 经法语进入英语，成为 route。"},"items":[{"word":"migr-","structure":"migrare (Latin verb, first conjugation)","meaning":"to move, to change one's abode","meaningCN":"迁移；迁居","example":"The root supplies the movement before any line is drawn.","exampleCN":"词根提供的是画线之前的移动。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"the act or process of doing something","meaningCN":"动作或过程","example":"Migration names the act of moving away.","exampleCN":"migration 指迁离这一动作。"},{"word":"migration","structure":"migrare + -ation","meaning":"seasonal or permanent movement to a new region","meaningCN":"季节性或永久性的迁往新地区","example":"Migration in birds is usually seasonal.","exampleCN":"鸟类的迁徙通常是季节性的。"},{"word":"migrate","structure":"migr- + -ate (Latin -atus)","meaning":"to move from one region to another","meaningCN":"从一地区迁往另一地区","example":"The geese migrate south before the frost.","exampleCN":"大雁在霜降前南迁。"},{"word":"migratory","structure":"migrate + -ory (Latin -orius)","meaning":"given to migrating","meaningCN":"有迁徙习性的","example":"Migratory species depend on intact stopover sites.","exampleCN":"迁徙物种依赖完好的中途停歇地。"},{"word":"route","structure":"Old French rute, from Latin rupta (via) (noun, first declension)","meaning":"an opened way, a road","meaningCN":"开出来的路；道路","example":"Route names the line, not the moving.","exampleCN":"route 命名的是线，而不是移动。"},{"word":"-rupt-","structure":"rumpere, rupi, ruptum (Latin verb, third conjugation)","meaning":"to break, burst open","meaningCN":"破开；冲破","example":"A road through wild ground is ground that was broken open.","exampleCN":"穿过荒野的路，就是被破开的土地。"},{"word":"routing","structure":"route + -ing","meaning":"the assigning of a path, or the path assigned","meaningCN":"路线安排；路径选择","example":"Routing decides which line the traffic takes.","exampleCN":"路径选择决定交通走哪一条线。"},{"word":"reroute","structure":"re- + route","meaning":"to send along a different path","meaningCN":"改道；改走另一条路径","example":"Storms forced controllers to reroute the flight.","exampleCN":"风暴迫使管制员为航班改道。"},{"word":"migration route","structure":"migration + route (compound noun phrase)","meaning":"the path followed by a migrating population","meaningCN":"迁徙种群所循的路径","example":"The phrase names a line plus the movement that uses it.","exampleCN":"这个短语同时命名一条线与使用它的移动。"}],"latinEntries":[{"word":"migrare","structure":"migrare, migravi, migratum (verb, first conjugation)","meaning":"to move, change abode","meaningCN":"迁移；迁居"},{"word":"migratio","structure":"migratio, migrationis (f., third declension)","meaning":"a moving, a change of residence","meaningCN":"迁移；住所更换"},{"word":"rumpere","structure":"rumpere, rupi, ruptum (verb, third conjugation)","meaning":"to break, burst","meaningCN":"破开；冲破"},{"word":"rupta","structure":"rupta, ruptae (f., first declension, past participle of rumpere)","meaning":"broken open, as in rupta via 'an opened way'","meaningCN":"被破开的（如 rupta via「开出来的路」）"}]}}]);
